/**
 * 唐诗三百首 - 数据文件
 * 包含：诗人信息、诗歌内容、注释译文
 */

const tangPoetryData = [
  {"id":"libai","name":"李白","bio":"李白（701年－762年），字太白，号青莲居士，唐代伟大的浪漫主义诗人，被后人誉为'诗仙'。与杜甫并称'李杜'。","poems":[
    {"title":"静夜思","content":"床前明月光，疑是地上霜。\n举头望明月，低头思故乡。"},
    {"title":"望庐山瀑布","content":"日照香炉生紫烟，遥看瀑布挂前川。\n飞流直下三千尺，疑是银河落九天。"},
    {"title":"赠汪伦","content":"李白乘舟将欲行，忽闻岸上踏歌声。\n桃花潭水深千尺，不及汪伦送我情。"},
    {"title":"早发白帝城","content":"朝辞白帝彩云间，千里江陵一日还。\n两岸猿声啼不住，轻舟已过万重山。"},
    {"title":"黄鹤楼送孟浩然之广陵","content":"故人西辞黄鹤楼，烟花三月下扬州。\n孤帆远影碧空尽，唯见长江天际流。"},
    {"title":"月下独酌","content":"花间一壶酒，独酌无相亲。\n举杯邀明月，对影成三人。"},
    {"title":"行路难","content":"金樽清酒斗十千，玉盘珍羞直万钱。\n停杯投箸不能食，拔剑四顾心茫然。"},
    {"title":"将进酒","content":"君不见黄河之水天上来，奔流到海不复回。\n君不见高堂明镜悲白发，朝如青丝暮成雪。"},
    {"title":"夜宿山寺","content":"危楼高百尺，手可摘星辰。\n不敢高声语，恐惊天上人。"},
    {"title":"独坐敬亭山","content":"众鸟高飞尽，孤云独去闲。\n相看两不厌，只有敬亭山。"},
    {"title":"秋浦歌十七首·其十五","content":"白发三千丈，缘愁似个长。\n不知明镜里，何处得秋霜。"},
    {"title":"古朗月行","content":"小时不识月，呼作白玉盘。\n又疑瑶台镜，飞在青云端。"},
    {"title":"春夜洛城闻笛","content":"谁家玉笛暗飞声，散入春风满洛城。\n此夜曲中闻折柳，何人不起故园情。"},
    {"title":"望天门山","content":"天门中断楚江开，碧水东流至此回。\n两岸青山相对出，孤帆一片日边来。"},
    {"title":"闻王昌龄左迁龙标遥有此寄","content":"杨花落尽子规啼，闻道龙标过五溪。\n我寄愁心与明月，随君直到夜郎西。"},
    {"title":"峨眉山月歌","content":"峨眉山月半轮秋，影入平羌江水流。\n夜发清溪向三峡，思君不见下渝州。"},
    {"title":"渡荆门送别","content":"渡远荆门外，来从楚国游。\n山随平野尽，江入大荒流。"},
    {"title":"送友人","content":"青山横北郭，白水绕东城。\n此地一为别，孤蓬万里征。"},
    {"title":"宣州谢朓楼饯别校书叔云","content":"弃我去者，昨日之日不可留；\n乱我心者，今日之日多烦忧。"},
    {"title":"长相思","content":"长相思，在长安。\n络纬秋啼金井阑，微霜凄凄簟色寒。"}
  ]},
  {"id":"dufu","name":"杜甫","bio":"杜甫（712年－770年），字子美，自号少陵野老，唐代伟大的现实主义诗人，被后人誉为'诗圣'。","poems":[
    {"title":"春望","content":"国破山河在，城春草木深。\n感时花溅泪，恨别鸟惊心。\n烽火连三月，家书抵万金。\n白头搔更短，浑欲不胜簪。"},
    {"title":"春夜喜雨","content":"好雨知时节，当春乃发生。\n随风潜入夜，润物细无声。\n野径云俱黑，江船火独明。\n晓看红湿处，花重锦官城。"},
    {"title":"望岳","content":"岱宗夫如何？齐鲁青未了。\n造化钟神秀，阴阳割昏晓。\n荡胸生曾云，决眦入归鸟。\n会当凌绝顶，一览众山小。"},
    {"title":"绝句","content":"两个黄鹂鸣翠柳，一行白鹭上青天。\n窗含西岭千秋雪，门泊东吴万里船。"},
    {"title":"登高","content":"风急天高猿啸哀，渚清沙白鸟飞回。\n无边落木萧萧下，不尽长江滚滚来。"},
    {"title":"江畔独步寻花","content":"黄四娘家花满蹊，千朵万朵压枝低。\n留连戏蝶时时舞，自在娇莺恰恰啼。"},
    {"title":"月夜忆舍弟","content":"戍鼓断人行，边秋一雁声。\n露从今夜白，月是故乡明。"},
    {"title":"蜀相","content":"丞相祠堂何处寻？锦官城外柏森森。\n映阶碧草自春色，隔叶黄鹂空好音。"},
    {"title":"赠花卿","content":"锦城丝管日纷纷，半入江风半入云。\n此曲只应天上有，人间能得几回闻。"},
    {"title":"江南逢李龟年","content":"岐王宅里寻常见，崔九堂前几度闻。\n正是江南好风景，落花时节又逢君。"},
    {"title":"旅夜书怀","content":"细草微风岸，危樯独夜舟。\n星垂平野阔，月涌大江流。"},
    {"title":"八阵图","content":"功盖三分国，名成八阵图。\n江流石不转，遗恨失吞吴。"},
    {"title":"前出塞九首·其六","content":"挽弓当挽强，用箭当用长。\n射人先射马，擒贼先擒王。"},
    {"title":"绝句二首","content":"迟日江山丽，春风花草香。\n泥融飞燕子，沙暖睡鸳鸯。"},
    {"title":"茅屋为秋风所破歌","content":"八月秋高风怒号，卷我屋上三重茅。\n茅飞渡江洒江郊，高者挂罥长林梢，下者飘转沉塘坳。"},
    {"title":"石壕吏","content":"暮投石壕村，有吏夜捉人。\n老翁逾墙走，老妇出门看。"},
    {"title":"兵车行","content":"车辚辚，马萧萧，行人弓箭各在腰。\n爷娘妻子走相送，尘埃不见咸阳桥。"},
    {"title":"丽人行","content":"三月三日天气新，长安水边多丽人。\n态浓意远淑且真，肌理细腻骨肉匀。"},
    {"title":"哀江头","content":"少陵野老吞声哭，春日潜行曲江曲。\n江头宫殿锁千门，细柳新蒲为谁绿？"},
    {"title":"哀王孙","content":"长安城头头白乌，夜飞延秋门上呼。\n又向人家啄大屋，屋底达官走避胡。"}
  ]},
  {"id":"wangwei","name":"王维","bio":"王维（701年－761年），字摩诘，号摩诘居士，唐代著名诗人、画家，被誉为'诗佛'。","poems":[
    {"title":"相思","content":"红豆生南国，春来发几枝。\n愿君多采撷，此物最相思。"},
    {"title":"鹿柴","content":"空山不见人，但闻人语响。\n返景入深林，复照青苔上。"},
    {"title":"竹里馆","content":"独坐幽篁里，弹琴复长啸。\n深林人不知，明月来相照。"},
    {"title":"送元二使安西","content":"渭城朝雨浥轻尘，客舍青青柳色新。\n劝君更尽一杯酒，西出阳关无故人。"},
    {"title":"九月九日忆山东兄弟","content":"独在异乡为异客，每逢佳节倍思亲。\n遥知兄弟登高处，遍插茱萸少一人。"},
    {"title":"山居秋暝","content":"空山新雨后，天气晚来秋。\n明月松间照，清泉石上流。"},
    {"title":"鸟鸣涧","content":"人闲桂花落，夜静春山空。\n月出惊山鸟，时鸣春涧中。"},
    {"title":"画","content":"远看山有色，近听水无声。\n春去花还在，人来鸟不惊。"},
    {"title":"杂诗","content":"君自故乡来，应知故乡事。\n来日绮窗前，寒梅著花未？"},
    {"title":"终南别业","content":"中岁颇好道，晚家南山陲。\n兴来每独往，胜事空自知。"},
    {"title":"使至塞上","content":"单车欲问边，属国过居延。\n征蓬出汉塞，归雁入胡天。"},
    {"title":"渭川田家","content":"斜阳照墟落，穷巷牛羊归。\n野老念牧童，倚杖候荆扉。"},
    {"title":"青溪","content":"言入黄花川，每逐青溪水。\n随山将万转，趣途无百里。"},
    {"title":"老将行","content":"少年十五二十时，步行夺得胡马骑。\n射杀山中白额虎，肯数邺下黄须儿！"},
    {"title":"桃源行","content":"渔舟逐水爱山春，两岸桃花夹古津。\n坐看红树不知远，行尽青溪不见人。"},
    {"title":"陇西行","content":"十里一走马，五里一扬鞭。\n都护军书至，匈奴围酒泉。"},
    {"title":"少年行","content":"新丰美酒斗十千，咸阳游侠多少年。\n相逢意气为君饮，系马高楼垂柳边。"},
    {"title":"观猎","content":"风劲角弓鸣，将军猎渭城。\n草枯鹰眼疾，雪尽马蹄轻。"},
    {"title":"汉江临眺","content":"楚塞三湘接，荆门九派通。\n江流天地外，山色有无中。"},
    {"title":"积雨辋川庄作","content":"积雨空林烟火迟，蒸藜炊黍饷东菑。\n漠漠水田飞白鹭，阴阴夏木啭黄鹂。"}
  ]},
  {"id":"baijuyi","name":"白居易","bio":"白居易（772年－846年），字乐天，号香山居士，唐代伟大的现实主义诗人，有'诗魔'之称。","poems":[
    {"title":"赋得古原草送别","content":"离离原上草，一岁一枯荣。\n野火烧不尽，春风吹又生。"},
    {"title":"忆江南","content":"江南好，风景旧曾谙。\n日出江花红胜火，春来江水绿如蓝。\n能不忆江南？"},
    {"title":"暮江吟","content":"一道残阳铺水中，半江瑟瑟半江红。\n可怜九月初三夜，露似真珠月似弓。"},
    {"title":"池上","content":"小娃撑小艇，偷采白莲回。\n不解藏踪迹，浮萍一道开。"},
    {"title":"钱塘湖春行","content":"孤山寺北贾亭西，水面初平云脚低。\n几处早莺争暖树，谁家新燕啄春泥。"},
    {"title":"问刘十九","content":"绿蚁新醅酒，红泥小火炉。\n晚来天欲雪，能饮一杯无？"},
    {"title":"大林寺桃花","content":"人间四月芳菲尽，山寺桃花始盛开。\n长恨春归无觅处，不知转入此中来。"},
    {"title":"夜雪","content":"已讶衾枕冷，复见窗户明。\n夜深知雪重，时闻折竹声。"},
    {"title":"卖炭翁","content":"卖炭翁，伐薪烧炭南山中。\n满面尘灰烟火色，两鬓苍苍十指黑。"},
    {"title":"长恨歌（节选）","content":"汉皇重色思倾国，御宇多年求不得。\n杨家有女初长成，养在深闺人未识。"},
    {"title":"琵琶行（节选）","content":"浔阳江头夜送客，枫叶荻花秋瑟瑟。\n主人下马客在船，举酒欲饮无管弦。"},
    {"title":"观刈麦","content":"田家少闲月，五月人倍忙。\n夜来南风起，小麦覆陇黄。"},
    {"title":"白云泉","content":"天平山上白云泉，云自无心水自闲。\n何必奔冲山下去，更添波浪向人间。"},
    {"title":"后宫词","content":"泪湿罗巾梦不成，夜深前殿按歌声。\n红颜未老恩先断，斜倚薰笼坐到明。"},
    {"title":"花非花","content":"花非花，雾非雾。\n夜半来，天明去。\n来如春梦几多时？\n去似朝云无觅处。"},
    {"title":"放言五首·其三","content":"赠君一法决狐疑，不用钻龟与祝蓍。\n试玉要烧三日满，辨材须待七年期。"},
    {"title":"与梦得沽酒闲饮且约后期","content":"少时犹不忧生计，老后谁能惜酒钱？\n共把十千沽一斗，相看七十欠三年。"},
    {"title":"邯郸冬至夜思家","content":"邯郸驿里逢冬至，抱膝灯前影伴身。\n想得家中夜深坐，还应说着远行人。"},
    {"title":"秋雨夜眠","content":"凉冷三秋夜，安闲一老翁。\n卧迟灯灭后，睡美雨声中。"},
    {"title":"舟中读元九诗","content":"把君诗卷灯前读，诗尽灯残天未明。\n眼痛灭灯犹暗坐，逆风吹浪打船声。"}
  ]},
  {"id":"lisan","name":"李商隐","bio":"李商隐（约813年－约858年），字义山，号玉溪生，晚唐著名诗人，与杜牧合称'小李杜'。","poems":[
    {"title":"夜雨寄北","content":"君问归期未有期，巴山夜雨涨秋池。\n何当共剪西窗烛，却话巴山夜雨时。"},
    {"title":"登乐游原","content":"向晚意不适，驱车登古原。\n夕阳无限好，只是近黄昏。"},
    {"title":"锦瑟","content":"锦瑟无端五十弦，一弦一柱思华年。\n庄生晓梦迷蝴蝶，望帝春心托杜鹃。"},
    {"title":"无题","content":"相见时难别亦难，东风无力百花残。\n春蚕到死丝方尽，蜡炬成灰泪始干。"},
    {"title":"嫦娥","content":"云母屏风烛影深，长河渐落晓星沉。\n嫦娥应悔偷灵药，碧海青天夜夜心。"},
    {"title":"贾生","content":"宣室求贤访逐臣，贾生才调更无伦。\n可怜夜半虚前席，不问苍生问鬼神。"},
    {"title":"霜月","content":"初闻征雁已无蝉，百尺楼高水接天。\n青女素娥俱耐冷，月中霜里斗婵娟。"},
    {"title":"宿骆氏亭寄怀崔雍崔衮","content":"竹坞无尘水槛清，相思迢递隔重城。\n秋阴不散霜飞晚，留得枯荷听雨声。"},
    {"title":"风雨","content":"凄凉宝剑篇，羁泊欲穷年。\n黄叶仍风雨，青楼自管弦。"},
    {"title":"落花","content":"高阁客竟去，小园花乱飞。\n参差连曲陌，迢递送斜晖。"},
    {"title":"凉思","content":"客去波平槛，蝉休露满枝。\n永怀当此节，倚立自移时。"},
    {"title":"北青萝","content":"残阳西入崦，茅屋访孤僧。\n落叶人何在，寒云路几层。"},
    {"title":"蝉","content":"本以高难饱，徒劳恨费声。\n五更疏欲断，一树碧无情。"},
    {"title":"无题二首·其一","content":"昨夜星辰昨夜风，画楼西畔桂堂东。\n身无彩凤双飞翼，心有灵犀一点通。"},
    {"title":"隋宫","content":"紫泉宫殿锁烟霞，欲取芜城作帝家。\n玉玺不缘归日角，锦帆应是到天涯。"},
    {"title":"马嵬","content":"海外徒闻更九州，他生未卜此生休。\n空闻虎旅传宵柝，无复鸡人报晓筹。"},
    {"title":"为有","content":"为有云屏无限娇，凤城寒尽怕春宵。\n无端嫁得金龟婿，辜负香衾事早朝。"},
    {"title":"瑶池","content":"瑶池阿母绮窗开，黄竹歌声动地哀。\n八骏日行三万里，穆王何事不重来。"},
    {"title":"重过圣女祠","content":"白石岩扉碧藓滋，上清沦谪得归迟。\n一春梦雨常飘瓦，尽日灵风不满旗。"},
    {"title":"韩碑","content":"元和天子神武姿，彼何人哉轩与羲。\n誓将上雪列圣耻，坐法宫中朝四夷。"}
  ]},
  {"id":"duomu","name":"杜牧","bio":"杜牧（803年－852年），字牧之，号樊川居士，唐代著名诗人，与李商隐并称'小李杜'。","poems":[
    {"title":"清明","content":"清明时节雨纷纷，路上行人欲断魂。\n借问酒家何处有？牧童遥指杏花村。"},
    {"title":"山行","content":"远上寒山石径斜，白云生处有人家。\n停车坐爱枫林晚，霜叶红于二月花。"},
    {"title":"江南春","content":"千里莺啼绿映红，水村山郭酒旗风。\n南朝四百八十寺，多少楼台烟雨中。"},
    {"title":"泊秦淮","content":"烟笼寒水月笼沙，夜泊秦淮近酒家。\n商女不知亡国恨，隔江犹唱后庭花。"},
    {"title":"秋夕","content":"银烛秋光冷画屏，轻罗小扇扑流萤。\n天阶夜色凉如水，卧看牵牛织女星。"},
    {"title":"赤壁","content":"折戟沉沙铁未销，自将磨洗认前朝。\n东风不与周郎便，铜雀春深锁二乔。"},
    {"title":"赠别","content":"娉娉袅袅十三余，豆蔻梢头二月初。\n春风十里扬州路，卷上珠帘总不如。"},
    {"title":"寄扬州韩绰判官","content":"青山隐隐水迢迢，秋尽江南草未凋。\n二十四桥明月夜，玉人何处教吹箫？"},
    {"title":"题乌江亭","content":"胜败兵家事不期，包羞忍耻是男儿。\n江东子弟多才俊，卷土重来未可知。"},
    {"title":"过华清宫","content":"长安回望绣成堆，山顶千门次第开。\n一骑红尘妃子笑，无人知是荔枝来。"},
    {"title":"金谷园","content":"繁华事散逐香尘，流水无情草自春。\n日暮东风怨啼鸟，落花犹似坠楼人。"},
    {"title":"遣怀","content":"落魄江湖载酒行，楚腰纤细掌中轻。\n十年一觉扬州梦，赢得青楼薄幸名。"},
    {"title":"叹花","content":"自是寻春去校迟，不须惆怅怨芳时。\n狂风落尽深红色，绿叶成阴子满枝。"},
    {"title":"紫薇花","content":"晓迎秋露一枝新，不占园中最上春。\n桃李无言又何在，向风偏笑艳阳人。"},
    {"title":"齐安郡后池绝句","content":"菱透浮萍绿锦池，夏莺千啭弄蔷薇。\n尽日无人看微雨，鸳鸯相对浴红衣。"},
    {"title":"题齐安城楼","content":"呜轧江楼角一声，微阳潋潋落寒汀。\n不用凭栏苦回首，故乡七十五长亭。"},
    {"title":"初冬夜饮","content":"淮阳多病偶求欢，客袖侵霜与烛盘。\n砌下梨花一堆雪，明年谁此凭阑干？"},
    {"title":"屏风绝句","content":"屏风周昉画纤腰，岁久丹青色半销。\n斜倚玉窗鸾发女，拂尘犹自妒娇娆。"},
    {"title":"念昔游三首·其一","content":"十载飘然绳检外，樽前自献自为酬。\n秋山春雨闲吟处，倚遍江南寺寺楼。"},
    {"title":"题木兰庙","content":"弯弓征战作男儿，梦里曾经与画眉。\n几度思归还把酒，拂云堆上祝明妃。"}
  ]},
  {"id":"meng","name":"孟浩然","bio":"孟浩然（689年－740年），唐代著名的山水田园诗人，与王维并称'王孟'。","poems":[
    {"title":"春晓","content":"春眠不觉晓，处处闻啼鸟。\n夜来风雨声，花落知多少。"},
    {"title":"过故人庄","content":"故人具鸡黍，邀我至田家。\n绿树村边合，青山郭外斜。"},
    {"title":"宿建德江","content":"移舟泊烟渚，日暮客愁新。\n野旷天低树，江清月近人。"},
    {"title":"望洞庭湖赠张丞相","content":"八月湖水平，涵虚混太清。\n气蒸云梦泽，波撼岳阳城。"},
    {"title":"夜归鹿门歌","content":"山寺钟鸣昼已昏，渔梁渡头争渡喧。\n人随沙岸向江村，余亦乘舟归鹿门。"},
    {"title":"与诸子登岘山","content":"人事有代谢，往来成古今。\n江山留胜迹，我辈复登临。"},
    {"title":"夏日南亭怀辛大","content":"山光忽西落，池月渐东上。\n散发乘夕凉，开轩卧闲敞。"},
    {"title":"岁暮归南山","content":"北阙休上书，南山归敝庐。\n不才明主弃，多病故人疏。"},
    {"title":"留别王维","content":"寂寂竟何待，朝朝空自归。\n欲寻芳草去，惜与故人违。"},
    {"title":"秋登兰山寄张五","content":"北山白云里，隐者自怡悦。\n相望试登高，心随雁飞灭。"},
    {"title":"宿桐庐江寄广陵旧游","content":"山暝听猿愁，沧江急夜流。\n风鸣两岸叶，月照一孤舟。"},
    {"title":"早寒江上有怀","content":"木落雁南渡，北风江上寒。\n我家襄水曲，遥隔楚云端。"},
    {"title":"题大禹寺义公禅房","content":"义公习禅寂，结宇依空林。\n户外一峰秀，阶前众壑深。"},
    {"title":"宿业师山房期丁大不至","content":"夕阳度西岭，群壑倏已暝。\n松月生夜凉，风泉满清听。"},
    {"title":"秦中寄远上人","content":"一丘常欲卧，三径苦无资。\n北土非吾愿，东林怀我师。"},
    {"title":"洛中访袁拾遗不遇","content":"洛阳访才子，江岭作流人。\n闻说梅花早，何如北地春。"},
    {"title":"送杜十四之江南","content":"荆吴相接水为乡，君去春江正渺茫。\n日暮征帆何处泊？天涯一望断人肠。"},
    {"title":"渡浙江问舟中人","content":"潮落江平未有风，扁舟共济与君同。\n时时引领望天末，何处青山是越中？"},
    {"title":"送朱大入秦","content":"游人五陵去，宝剑值千金。\n分手脱相赠，平生一片心。"},
    {"title":"送友人之京","content":"君登青云去，予望青山归。\n云山从此别，泪湿薜萝衣。"}
  ]},
  {"id":"wangzhihuan","name":"王之涣","bio":"王之涣（688年－742年），唐代著名边塞诗人，以《登鹳雀楼》和《凉州词》闻名。","poems":[
    {"title":"登鹳雀楼","content":"白日依山尽，黄河入海流。\n欲穷千里目，更上一层楼。"},
    {"title":"凉州词","content":"黄河远上白云间，一片孤城万仞山。\n羌笛何须怨杨柳，春风不度玉门关。"},
    {"title":"送别","content":"杨柳东风树，青青夹御河。\n近来攀折苦，应为别离多。"},
    {"title":"宴词","content":"长堤春水绿悠悠，畎入漳河一道流。\n莫听声声催去棹，桃溪浅处不胜舟。"},
    {"title":"九日送别","content":"蓟庭萧瑟故人稀，何处登高且送归。\n今日暂同芳菊酒，明朝应作断蓬飞。"}
  ]},
  {"id":"hezhizhang","name":"贺知章","bio":"贺知章（约659年－约744年），字季真，唐代诗人、书法家。","poems":[
    {"title":"咏柳","content":"碧玉妆成一树高，万条垂下绿丝绦。\n不知细叶谁裁出，二月春风似剪刀。"},
    {"title":"回乡偶书","content":"少小离家老大回，乡音无改鬓毛衰。\n儿童相见不相识，笑问客从何处来。"},
    {"title":"回乡偶书·其二","content":"离别家乡岁月多，近来人事半消磨。\n惟有门前镜湖水，春风不改旧时波。"},
    {"title":"采莲曲","content":"稽山云雾郁嵯峨，镜水无风也自波。\n莫言春度芳菲尽，别有中流采芰荷。"},
    {"title":"答朝士","content":"鈒镂银盘盛蛤蜊，镜湖莼菜乱如丝。\n乡曲近来佳此味，遮渠不道是吴儿。"}
  ]},
  {"id":"wangchangling","name":"王昌龄","bio":"王昌龄（698年－757年），字少伯，盛唐著名边塞诗人，被誉为'诗家夫子'、'七绝圣手'。","poems":[
    {"title":"出塞","content":"秦时明月汉时关，万里长征人未还。\n但使龙城飞将在，不教胡马度阴山。"},
    {"title":"芙蓉楼送辛渐","content":"寒雨连江夜入吴，平明送客楚山孤。\n洛阳亲友如相问，一片冰心在玉壶。"},
    {"title":"从军行","content":"青海长云暗雪山，孤城遥望玉门关。\n黄沙百战穿金甲，不破楼兰终不还。"},
    {"title":"闺怨","content":"闺中少妇不知愁，春日凝妆上翠楼。\n忽见陌头杨柳色，悔教夫婿觅封侯。"},
    {"title":"长信怨","content":"奉帚平明金殿开，暂将团扇共徘徊。\n玉颜不及寒鸦色，犹带昭阳日影来。"},
    {"title":"采莲曲","content":"荷叶罗裙一色裁，芙蓉向脸两边开。\n乱入池中看不见，闻歌始觉有人来。"},
    {"title":"塞下曲","content":"饮马渡秋水，水寒风似刀。\n平沙日未没，黯黯见临洮。"},
    {"title":"送柴侍御","content":"沅水通波接武冈，送君不觉有离伤。\n青山一道同云雨，明月何曾是两乡。"},
    {"title":"西宫春怨","content":"西宫夜静百花香，欲卷珠帘春恨长。\n斜抱云和深见月，朦胧树色隐昭阳。"},
    {"title":"春宫曲","content":"昨夜风开露井桃，未央前殿月轮高。\n平阳歌舞新承宠，帘外春寒赐锦袍。"}
  ]},
  {"id":"gaoshi","name":"高适","bio":"高适（704年－765年），字达夫，盛唐著名边塞诗人，与岑参并称'高岑'。","poems":[
    {"title":"别董大","content":"千里黄云白日曛，北风吹雁雪纷纷。\n莫愁前路无知己，天下谁人不识君。"},
    {"title":"燕歌行","content":"汉家烟尘在东北，汉将辞家破残贼。\n男儿本自重横行，天子非常赐颜色。"},
    {"title":"塞上听吹笛","content":"雪净胡天牧马还，月明羌笛戍楼间。\n借问梅花何处落，风吹一夜满关山。"},
    {"title":"除夜作","content":"旅馆寒灯独不眠，客心何事转凄然。\n故乡今夜思千里，霜鬓明朝又一年。"},
    {"title":"送李少府贬峡中王少府贬长沙","content":"嗟君此别意何如，驻马衔杯问谪居。\n巫峡啼猿数行泪，衡阳归雁几封书。"},
    {"title":"营州歌","content":"营州少年厌原野，狐裘蒙茸猎城下。\n虏酒千钟不醉人，胡儿十岁能骑马。"},
    {"title":"和王七玉门关听吹笛","content":"胡人吹笛戍楼间，楼上萧条海月闲。\n借问落梅凡几曲，从风一夜满关山。"},
    {"title":"送李侍御赴安西","content":"行子对飞蓬，金鞭指铁骢。\n功名万里外，心事一杯中。"},
    {"title":"醉后赠张九旭","content":"世上漫相识，此翁殊不然。\n兴来书自圣，醉后语尤颠。"},
    {"title":"人日寄杜二拾遗","content":"人日题诗寄草堂，遥怜故人思故乡。\n柳条弄色不忍见，梅花满枝空断肠。"}
  ]},
  {"id":"cencan","name":"岑参","bio":"岑参（715年－770年），唐代著名边塞诗人，与高适并称'高岑'。","poems":[
    {"title":"白雪歌送武判官归京","content":"北风卷地白草折，胡天八月即飞雪。\n忽如一夜春风来，千树万树梨花开。"},
    {"title":"逢入京使","content":"故园东望路漫漫，双袖龙钟泪不干。\n马上相逢无纸笔，凭君传语报平安。"},
    {"title":"走马川行奉送出师西征","content":"君不见走马川行雪海边，平沙莽莽黄入天。\n轮台九月风夜吼，一川碎石大如斗。"},
    {"title":"碛中作","content":"走马西来欲到天，辞家见月两回圆。\n今夜不知何处宿，平沙万里绝人烟。"},
    {"title":"山房春事","content":"梁园日暮乱飞鸦，极目萧条三两家。\n庭树不知人去尽，春来还发旧时花。"},
    {"title":"春梦","content":"洞房昨夜春风起，故人尚隔湘江水。\n枕上片时春梦中，行尽江南数千里。"},
    {"title":"寄左省杜拾遗","content":"联步趋丹陛，分曹限紫微。\n晓随天仗入，暮惹御香归。"},
    {"title":"和贾舍人早朝大明宫之作","content":"鸡鸣紫陌曙光寒，莺啭皇州春色阑。\n金阙晓钟开万户，玉阶仙仗拥千官。"},
    {"title":"轮台歌奉送封大夫出师西征","content":"轮台城头夜吹角，轮台城北旄头落。\n羽书昨夜过渠黎，单于已在金山西。"},
    {"title":"热海行送崔侍御还京","content":"侧闻阴山胡儿语，西头热海水如煮。\n海上众鸟不敢飞，中有鲤鱼长且肥。"}
  ]},
  {"id":"liu","name":"刘禹锡","bio":"刘禹锡（772年－842年），字梦得，唐代文学家、哲学家，有'诗豪'之称。","poems":[
    {"title":"秋词","content":"自古逢秋悲寂寥，我言秋日胜春朝。\n晴空一鹤排云上，便引诗情到碧霄。"},
    {"title":"乌衣巷","content":"朱雀桥边野草花，乌衣巷口夕阳斜。\n旧时王谢堂前燕，飞入寻常百姓家。"},
    {"title":"竹枝词","content":"杨柳青青江水平，闻郎江上唱歌声。\n东边日出西边雨，道是无晴却有晴。"},
    {"title":"酬乐天扬州初逢席上见赠","content":"巴山楚水凄凉地，二十三年弃置身。\n怀旧空吟闻笛赋，到乡翻似烂柯人。"},
    {"title":"浪淘沙","content":"九曲黄河万里沙，浪淘风簸自天涯。\n如今直上银河去，同到牵牛织女家。"},
    {"title":"望洞庭","content":"湖光秋月两相和，潭面无风镜未磨。\n遥望洞庭山水翠，白银盘里一青螺。"},
    {"title":"石头城","content":"山围故国周遭在，潮打空城寂寞回。\n淮水东边旧时月，夜深还过女墙来。"},
    {"title":"蜀先主庙","content":"天地英雄气，千秋尚凛然。\n势分三足鼎，业复五铢钱。"},
    {"title":"再游玄都观","content":"百亩庭中半是苔，桃花净尽菜花开。\n种桃道士归何处，前度刘郎今又来。"},
    {"title":"赏牡丹","content":"庭前芍药妖无格，池上芙蕖净少情。\n唯有牡丹真国色，花开时节动京城。"}
  ]},
  {"id":"liuhe","name":"柳宗元","bio":"柳宗元（773年－819年），字子厚，唐代文学家、哲学家，唐宋八大家之一。","poems":[
    {"title":"江雪","content":"千山鸟飞绝，万径人踪灭。\n孤舟蓑笠翁，独钓寒江雪。"},
    {"title":"渔翁","content":"渔翁夜傍西岩宿，晓汲清湘燃楚竹。\n烟销日出不见人，欸乃一声山水绿。"},
    {"title":"登柳州城楼寄漳汀封连四州刺史","content":"城上高楼接大荒，海天愁思正茫茫。\n惊风乱飐芙蓉水，密雨斜侵薜荔墙。"},
    {"title":"与浩初上人同看山寄京华亲故","content":"海畔尖山似剑铓，秋来处处割愁肠。\n若为化得身千亿，散上峰头望故乡。"},
    {"title":"别舍弟宗一","content":"零落残魂倍黯然，双垂别泪越江边。\n一身去国六千里，万死投荒十二年。"},
    {"title":"岭南江行","content":"瘴江南去入云烟，望尽黄茆是海边。\n山腹雨晴添象迹，潭心日暖长蛟涎。"},
    {"title":"溪居","content":"久为簪组累，幸此南夷谪。\n闲依农圃邻，偶似山林客。"},
    {"title":"晨诣超师院读禅经","content":"汲井漱寒齿，清心拂尘服。\n闲持贝叶书，步出东斋读。"},
    {"title":"酬曹侍御过象县见寄","content":"破额山前碧玉流，骚人遥驻木兰舟。\n春风无限潇湘意，欲采蘋花不自由。"},
    {"title":"柳州二月榕叶落尽偶题","content":"宦情羁思共凄凄，春半如秋意转迷。\n山城过雨百花尽，榕叶满庭莺乱啼。"}
  ]},
  {"id":"hanshan","name":"韩愈","bio":"韩愈（768年－824年），字退之，唐代文学家、哲学家，唐宋八大家之首。","poems":[
    {"title":"早春呈水部张十八员外","content":"天街小雨润如酥，草色遥看近却无。\n最是一年春好处，绝胜烟柳满皇都。"},
    {"title":"春雪","content":"新年都未有芳华，二月初惊见草芽。\n白雪却嫌春色晚，故穿庭树作飞花。"},
    {"title":"左迁至蓝关示侄孙湘","content":"一封朝奏九重天，夕贬潮州路八千。\n欲为圣明除弊事，肯将衰朽惜残年！"},
    {"title":"晚春","content":"草树知春不久归，百般红紫斗芳菲。\n杨花榆荚无才思，惟解漫天作雪飞。"},
    {"title":"题榴花","content":"五月榴花照眼明，枝间时见子初成。\n可怜此地无车马，颠倒青苔落绛英。"},
    {"title":"湘中","content":"猿愁鱼踊水翻波，自古流传是汨罗。\n蘋藻满盘无处奠，空闻渔父扣舷歌。"},
    {"title":"答张十一","content":"山净江空水见沙，哀猿啼处两三家。\n筼筜竞长纤纤笋，踯躅闲开艳艳花。"},
    {"title":"题木居士二首·其一","content":"火透波穿不计春，根如头面干如身。\n偶然题作木居士，便有无穷求福人。"},
    {"title":"听颖师弹琴","content":"昵昵儿女语，恩怨相尔汝。\n划然变轩昂，勇士赴敌场。"},
    {"title":"山石","content":"山石荦确行径微，黄昏到寺蝙蝠飞。\n升堂坐阶新雨足，芭蕉叶大栀子肥。"}
  ]}
];

const poemExtras = {
  "静夜思":{notes:"【疑】好像。【举头】抬头。",translation:"明亮的月光洒在床前的窗户纸上，好像地上泛起了一层霜。我禁不住抬起头来，看那天窗外空中的一轮明月，不由得低头沉思，想起远方的家乡。",analysis:"这首诗写的是在寂静的月夜思念家乡的感受。诗的前两句写景，后两句抒情。语言清新朴素而韵味无穷，是李白最脍炙人口的名篇之一。"},
  "春晓":{notes:"【晓】天亮。【闻】听见。",translation:"春天的夜晚睡得很香甜，不知不觉天就亮了。醒来听到到处都是鸟儿的啼叫声。回想起昨天夜里的风雨声，不知道有多少花儿被打落了。",analysis:"这首诗描绘了一幅春天早晨绚丽的图景，抒发了诗人热爱春天、珍惜春光的美好心情。"},
  "登鹳雀楼":{notes:"【白日】傍晚的太阳。【依】依傍，靠着。【穷】尽，使达到极点。",translation:"夕阳依傍着西山慢慢沉没，滔滔黄河朝着东海汹涌奔流。若想把千里的风光景物看够，那就要登上更高的一层城楼。",analysis:"前两句写所见，后两句写所想。诗人通过登高望远，表达了积极向上的进取精神和宽广博大的胸襟。"},
  "相思":{notes:"【红豆】又名相思子，产于岭南，色鲜红而晶莹。【采撷】采摘。",translation:"红豆生长在南方，春天来的时候会长出多少新枝呢？希望你多采摘一些，因为它最能代表相思之情。",analysis:"这是借咏物而寄相思的诗。全诗情调健美高雅，怀思而不感伤。"},
  "咏柳":{notes:"【碧玉】碧绿色的玉，比喻春天嫩绿的柳叶。【绦】用丝编成的绳带，这里指像丝带一样的柳条。",translation:"高高的柳树像是碧玉妆扮成的，下垂的柳枝犹如千万条绿色的丝带。不知道这细细的柳叶是谁裁剪出来的？原来是二月的春风，它就像一把灵巧的剪刀。",analysis:"诗人借柳树歌咏春风，把春风比作剪刀，赞美她裁出了春天。诗中洋溢着人逢早春的欣喜之情。"},
  "出塞":{notes:"【秦时明月汉时关】互文见义，指秦汉时的明月和关隘。【但使】只要。",translation:"依旧是秦汉时的明月和边关，征战长久延续万里征夫不回还。倘若龙城的飞将李广而今健在，绝不许匈奴南下牧马度过阴山。",analysis:"这首诗慨叹边战不断、国无良将，表达了诗人希望朝廷起任良将，早日平息边塞战事，使人民过上安定生活的愿望。"},
  "江雪":{notes:"【绝】无，没有。【蓑笠】蓑衣和斗笠。",translation:"所有的山上都看不到飞鸟的影子，所有的小路都没有人的踪迹。江面孤舟上，一位披戴着蓑笠的老翁，独自在寒冷的江面上钓鱼。",analysis:"这首诗描绘了一幅寄兴高洁、寓意丰富的寒江独钓图，表达了诗人清高孤傲、不愿与世俗同流合污的品格。"},
  "望庐山瀑布":{notes:"【香炉】庐山香炉峰。【紫烟】日光照射水气呈现出的紫色云雾。",translation:"阳光照射下，香炉峰生起紫色烟霞，远远望去，瀑布像长河悬挂在山前。飞奔而下的水流直落三千尺，让人怀疑是银河从天上倾泻到人间。",analysis:"诗人运用夸张和想象的手法，描绘了庐山瀑布雄奇壮丽的景色，表达了对祖国大好河山的无限热爱。"},
  "春望":{notes:"【国破】指长安被安史叛军攻破。【城春】春天的长安城。",translation:"国都已被攻破，只有山河依旧存在，春天来了，城中杂草树木茂密。感伤时事，看到花开反而落泪，怨恨离别，听到鸟鸣反而惊心。",analysis:"这首诗写于安史之乱中，诗人目睹破碎的河山，感慨万千。全诗沉郁顿挫，感人至深。"},
  "赋得古原草送别":{notes:"【离离】青草茂盛的样子。【枯荣】枯萎和茂盛。",translation:"原野上的青草长得十分茂盛，每年都会经历枯萎和繁盛。野火无法把它们烧尽，春风一吹，它们又会生长出来。",analysis:"这首诗通过对古原上野草的描绘，抒发了送别友人时的依依惜别之情，赞美了野草顽强的生命力。"},
  "早发白帝城":{notes:"【白帝城】在今重庆奉节。【江陵】今湖北荆州。",translation:"清晨告别彩云缭绕的白帝城，千里之遥的江陵一天就可以到达。两岸猿猴的啼叫声还没停止，轻快的小船已经穿过了万重山峦。",analysis:"全诗洋溢着诗人经过艰难岁月之后突然迸发的激情，快船快意，将遇赦后愉快的心情和江山之壮丽多姿融为一体。"},
  "山行":{notes:"【寒山】深秋时节的山。【坐】因为。",translation:"沿着弯弯曲曲的小路上山，在那白云缭绕的地方居然还有人家。停下车来是因为喜爱这深秋的枫林晚景，霜染的枫叶比二月的花还要红艳。",analysis:"这首诗描绘了一幅山林秋色图，展现了一幅动人的山林秋色图，表达了诗人对大自然美景的热爱之情。"},
  "清明":{notes:"【断魂】形容伤感极深。【借问】请问。",translation:"清明时节细雨纷纷飘洒，路上的行人个个失魂落魄。请问当地之人何处买酒浇愁？牧童笑而不答遥指杏花山村。",analysis:"这首诗用优美生动的语言，描绘了一幅生动感人的雨中问路图，表现了清明时节行人思念亲人的愁苦心情。"},
  "乌衣巷":{notes:"【乌衣巷】在南京秦淮河南岸，东晋时王导、谢安两大家族居此。【王谢】指东晋时的王导、谢安两大家族。",translation:"朱雀桥边长满野草野花，乌衣巷口夕阳渐渐西斜。从前在王谢大堂前筑巢的燕子，如今飞入了寻常百姓家中。",analysis:"诗人通过对乌衣巷的描写，抒发了对世事沧桑、盛衰变化的慨叹。"},
  "竹枝词":{notes:"【晴】与'情'谐音，双关语。",translation:"杨柳青青江水宽又平，听见情郎江上踏歌声。东边出太阳西边下着雨，说是无晴（情）但是还有晴（情）。",analysis:"这首诗采用了民歌中常用的谐音双关手法，含蓄地表达了初恋少女微妙的内心世界。"}
};

/**
 * 创作故事 - 诗人写作此诗的背景与典故
 */
const poemStories = {
"静夜思":{story:"唐玄宗开元十四年（726年），26岁的李白带着远大的理想离开四川故乡，开始了漫游天下的旅程。这一年秋天，他客居扬州。旅舍清冷，月色如水，年轻的诗人躺在异乡的床榻上，久久不能入睡，思乡之情涌上心头，写下了这首千古传诵的小诗。\n诗的一开头就抓住了孩子也能想象到的画面：明亮的月光洒在床前，好像地上铺了一层白霜。诗人抬头看看天上的明月，又低头思念远方的故乡。相传原句是'床前看月光'和'望山月'，到了宋代才改成'明月光'与'望明月'，读起来更有韵味，也让这首诗定型为我们今天背诵的样子。\n短短二十个字，没有华丽辞藻，却道尽了天下游子共有的乡愁。它是中国传诵最广、背诵人数最多的唐诗，几乎每一个孩子学会的第一首诗就是它。"},
  "望庐山瀑布":{story:"唐玄宗天宝年间，李白约五十岁时隐居庐山屏风叠，过着读书写诗的悠闲日子。香炉峰瀑布就在附近，峰顶紫烟缭绕，瀑布如练垂空。他常常从早到晚对着瀑布出神，终于写下了这首想象奇特的名篇。\n太阳照耀香炉峰，生起紫色的烟霞，远远望去，瀑布像一条巨大的白色绢绸挂在山前。'飞流直下三千尺，疑是银河落九天'——三千尺的高度是夸张，银河从天而降更是大胆的想象，把一座瀑布写成了从天而降的星河。\n这首诗是李白浪漫主义诗风的代表作，夸张与想象浑然天成。千百年来，无数人因为这首诗而向往庐山，香炉峰瀑布也因此被称为'庐山第一奇观'。"},
  "赠汪伦":{story:"唐天宝年间，李白漫游到安徽泾县。当地名士汪伦十分仰慕他，修书一封相邀，信上巧言道：'先生好游乎？此地有十里桃花；先生好饮乎？此地有万家酒店。'爱游爱酒的李白见信大喜，立即动身前往。\n到了泾县才知道，所谓'十里桃花'是十里外的桃花潭水，'万家酒店'是姓万的人家开的酒店。李白非但没有生气，反而佩服汪伦的雅趣，二人数日饮酒论文，结为好友。\n离别那天，汪伦带着村民在岸边踏地为节、以歌相送，这是当地送客的隆重礼节。李白坐在船中，听歌声渐远，桃花潭水深不见底，而朋友的深情比潭水更深，于是写下'桃花潭水深千尺，不及汪伦送我情'，让汪伦的名字随这首诗流传了千年。"},
  "早发白帝城":{story:"至德二载（757年），李白因入永王李璘幕府获罪，被判流放夜郎（今贵州一带）。这一年他五十七岁，带着病妻幼子，一步步走向荒凉的远方。乾元二年（759年）春天，他拖着病体走到白帝城，忽然传来朝廷因关中大旱而大赦的消息——他获释了！\n惊喜交加的李白立刻从白帝城乘船东下江陵。顺流而下，舟行如飞，两岸猿声啼不住，轻舟已过万重山。重获自由的他欣喜若狂，把满腔的快意写进这首小诗。\n全诗没有一个'喜'字，却句句轻快飞扬。'两岸猿声啼不住，轻舟已过万重山'，以猿声的连绵反衬轻舟的神速，写出人生绝境逢生的狂喜，被后人誉为'惊风雨而泣鬼神'之作。"},
  "黄鹤楼送孟浩然之广陵":{story:"黄鹤楼在湖北武昌，临长江而立，是古代著名的送别之地。开元十八年（730年）前后，李白漫游至此，与仰慕已久的前辈诗人孟浩然重逢。孟浩然将乘船东下广陵（今扬州），李白在黄鹤楼为他设酒饯行。\n烟花三月，春意正浓，孟浩然的孤帆渐渐远去。李白久久伫立江边，目送帆影一点一点缩小，最后消失在碧空的尽头，只有长江水滚滚东流。离别之情都藏在这幅画面里。\n'孤帆远影碧空尽，唯见长江天际流'，被誉为'千古丽句'。李白把送别写成了一幅流动的画：有烟花三月的明丽，有孤帆远去的怅惘，更有长江无尽的深情，成为送别诗中的千古绝唱。"},
  "月下独酌":{story:"天宝初年，李白因诗才闻名，被召入长安供奉翰林。然而他傲岸的性格得罪权贵，不久便遭到排挤，被唐玄宗疏远。繁华的长安城里，他才华无处施展，孤独苦闷，常常独自饮酒。\n一个月色皎洁的夜晚，李白在花丛间摆开酒宴，身边没有一个人。他突发奇想：举起酒杯邀请天上的明月，加上自己的影子，竟然凑成了'三个人'。月既不解饮，影徒随我身，他只是暂时与明月和影子为伴，且歌且舞，在醉意中排遣孤独。醒时同交欢，醉后各分散，热闹是短暂的，醒来依然只有自己。\n'举杯邀明月，对影成三人'，把寂寞写得浪漫而旷达。这首诗是李白式的孤独：表面热闹，内心清冷，却始终不失豪放的本色。"},
  "行路难":{story:"天宝三载（744年），李白在长安供奉翰林近两年后，被唐玄宗'赐金放还'，体面地逐出了长安。他满怀报国之志而来，却只能为皇帝写几首助兴的诗，理想彻底落空。离京途中，朋友们设宴饯行，他写下这组《行路难》。\n'行路难'原是汉乐府旧题，多写世路艰难。李白借用古题，写自己离开长安时的心情：佳肴美酒都咽不下，拔剑四顾，心中茫然。诗中引用姜太公垂钓遇文王、伊尹梦舟过日月的典故，说明他仍盼望有朝一日能被重用。\n但李白毕竟是李白。诗的结尾忽然拔高：'长风破浪会有时，直挂云帆济沧海！'借用南朝宗悫'愿乘长风破万里浪'的志向，宣誓终将实现理想。这两句成为后世无数身处逆境者自我激励的千古名句。"},
  "将进酒":{story:"此诗约作于唐玄宗天宝年间，李白与好友岑勋、元丹丘在嵩山颍阳山居饮酒宴乐之时。此时距离他被'赐金放还'离开长安已有八年，漫游全国的足迹几乎踏遍名山，而报国之门始终紧闭。\n酒宴之上，李白借乐府旧题《将进酒》纵情高歌。他感叹人生得意须尽欢，借黄河之水从天而降的壮阔起笔，引用陈王曹植宴于平乐的典故，把满腔愤懑化为奔涌的诗情。\n'天生我材必有用，千金散尽还复来'，是困顿中的最强音；'钟鼓馔玉不足贵，但愿长醉不复醒'，写尽对权贵富贵的蔑视。全诗大起大落、如江河奔泻，被赞为'以气夺人'的千古绝唱，也是中国人饮酒文化中流传最广的名篇。"},
  "夜宿山寺":{story:"李白一生好游名山，夜宿山寺是常有的事。这首诗写的是他旅途中投宿深山寺院、夜宿高楼的情景，一说写的是湖北黄梅的江心寺，一说写于蔡山峰顶的寺院。\n寺院的高楼高到什么程度？站在楼上，伸手就好像能摘到天上的星星。诗人大气都不敢出，生怕自己大声说话，会惊动了住在天上的神仙。静夜里，高楼、星辰与想象中的天上人，构成了一幅神秘而有趣的画面。\n'危楼高百尺，手可摘星辰。不敢高声语，恐惊天上人'，通篇用夸张的手法写高，夸张里透着童稚般的天真与想象。短短二十字，境界全出，把山寺之高写得如在眼前，千百年来成为孩子们最喜欢背诵的唐诗之一。"},
  "独坐敬亭山":{story:"敬亭山在安徽宣城，风景秀丽。李白晚年飘泊江南时，曾七次登临此山。此时他年过花甲，历尽人生沧桑，官场失意，知交零落，昔日的豪门好友早已散作浮云。\n一个午后，李白独坐山巅。群鸟高飞，渐渐无影无踪；一片孤云也悠然远去，不再回来。天地之间，仿佛只剩下他和这座敬亭山，脉脉相对，谁也不厌烦谁。鸟儿有巢，浮云有山，而此刻这座敬亭山，就是他唯一的伴侣。\n'相看两不厌，只有敬亭山'，把山当成了唯一的知己。众鸟尽、孤云闲、青山对，写出了极致的孤独，也写出了孤独中的相知与安慰。这座默默无言的山，陪伴了诗人一生最后的岁月，这首诗也被后世誉为写孤独的千古绝唱。"},
  "秋浦歌十七首·其十五":{story:"秋浦在今天的安徽池州，唐时以产银和铜闻名，风景清幽。李白从天宝年间起多次游历秋浦，写下《秋浦歌》十七首，这是其中流传最广的一首。\n写这首诗时，李白已过了五十岁，离他从长安被'赐金放还'也已多年。报国的理想越来越远，白发却越来越多。他在秋浦对镜自照，看见满头白发如秋霜，不禁惊问：白发怎么会生出三千丈？\n原来是因为'缘愁似个长'——愁绪像三千丈白发一样长。这一问一答之间，把看不见的愁绪变成了摸得着的长度。以白发写愁，以长度写情，'白发三千丈，缘愁似个长'是千古咏愁的奇句，夸张得惊人，却又真实得让每个成年人都心有戚戚。"},
  "古朗月行":{story:"《古朗月行》是乐府旧题，'朗月'即明亮的月亮。李白借咏月追忆童年、感慨现实，原诗共十六句，我们今天读的多是前半部分。\n诗的前半写他小时候不认识月亮，把它叫作白玉盘，又怀疑是瑶台仙境里的明镜，飞在青云之端。孩子的天真和月亮的可爱，都在这短短几句里活了起来。\n相传诗的后半部分笔锋一转，写月亮被蟾蜍啃食变得残缺，又借后羿射落九日的故事影射小人当道，暗喻唐玄宗晚年宠信奸臣、朝政日渐昏暗，寄托了诗人的忧愤。教材常只选前半首，因为它写尽了孩童眼中月亮的美丽与神秘，也保存了每个人童年里那个闪闪发光的、充满幻想的月亮。"},
  "春夜洛城闻笛":{story:"唐玄宗开元二十二年（734年）前后，李白客居东都洛阳。洛阳是繁华的都市，但繁华是别人的，客居的诗人常常在深夜思念故乡。\n一个春夜，万籁俱寂，他忽然听见远处传来笛声，吹的正是《折杨柳》曲。古人送别时有折柳相赠的风俗，'柳'与'留'谐音，折柳就是挽留的意思。听到这支送别的曲子，谁能不勾起思念故乡的感情呢？\n'此夜曲中闻折柳，何人不起故园情'，由己及人，一个反问说尽天下游子之心。春夜、笛声、折柳，三个意象轻轻叠在一起，身在异乡的诗人浓浓的乡愁便油然而生。这首诗因春夜里一句笛声写出千古乡愁，成为思乡诗中的名篇。"},
  "望天门山":{story:"唐玄宗开元十三年（725年），二十五岁的李白'仗剑去国，辞亲远游'，乘舟出三峡，开始了人生第一次大漫游。船行到安徽当涂，两岸的青山忽然夹江对峙，如同一道天然的大门，这就是天门山。\n楚江（长江）冲开山梁，奔腾回旋，碧绿的江水在此打了个转折。两岸的青山隔着江面对面立着，像门扇一样；一叶孤帆从太阳升起的地方驶来，景色壮丽又清新。\n'天门中断楚江开，碧水东流至此回'，写出山川的雄伟气势；'两岸青山相对出，孤帆一片日边来'，青山仿佛在迎接远客，孤帆像从日边驶来，像一幅缓缓展开的画卷。这是少年李白初出蜀地时的壮游之作，字里行间都是少年意气。"},
  "闻王昌龄左迁龙标遥有此寄":{story:"王昌龄是盛唐著名的边塞诗人，与李白交好，史称'七绝圣手'。天宝年间，他因不拘小节被贬为龙标县尉（今湖南洪江一带），当时人们甚至以为他被贬到了更荒远的夜郎以西。\n李白当时在东南漫游，听到好友被贬的消息，心中十分担忧，便写下这首诗遥寄给他。他借明月寄情：我把为你忧愁的心托付给明月，让它伴随你一直到夜郎的西边。人虽相隔千里，心与心却借着明月紧紧相连。\n'我寄愁心与明月，随君直到夜郎西'，把抽象的'愁心'交给具体的明月，想象奇特，情谊深厚。从此，明月成为人间传情的使者，这句诗也成为表达牵挂与思念的千古名句。"},
  "峨眉山月歌":{story:"这是李白现存最早的一首写月诗，约作于开元十二年（724年）秋天，他初次离开蜀地远游之时。峨眉山是他家乡的山，山月是他家乡的月。\n夜色中，半轮明月高高地挂在峨眉山头，月影倒映在平羌江水中，随船流动。他乘船从清溪出发，向三峡驶去，家乡的人、家乡的月，都想见却再也见不到了。这一路的山水与月色，都被他写进了诗里。\n'峨眉山月半轮秋，影入平羌江水流'，二十八字中连用峨眉山、平羌江、清溪、三峡、渝州五个地名，却流转自如、不着痕迹，被称为'千秋绝调'。船越走越远，月与江水一路相随，写尽了少年离乡的不舍与对未来的憧憬。"},
  "渡荆门送别":{story:"唐玄宗开元十三年（725年），李白出蜀远游，乘船穿过三峡，渡过荆门山，从此进入楚地平原。蜀中的崇山峻岭渐渐消失，眼前是一望无际的旷野。\n'山随平野尽，江入大荒流'，山随着平原的出现而渐渐退去，江水奔流涌入辽阔的原野，写出平原初现的雄浑气势。江上明月如明镜飞落，天边云霞似海市蜃楼般变幻，让第一次看见大平原的李白目不暇接，一切都那么新鲜。\n这首诗里，故乡的山月渐渐远去，长江载着少年驶向未知的远方。结尾'仍怜故乡水，万里送行舟'，借故乡的江水万里相送，含蓄地表达了对蜀中亲友的惜别之情——壮阔的景色里，藏着一颗柔软的思乡心。"},
  "送友人":{story:"这首五律是李白送别友人的名篇。至于送的是谁，如今已无法确定，一说送的是杜甫，一说送的是入蜀的友人，但诗中深厚的情谊却超越了个别对象，感动了千百年来无数读者。\n送别之地青山横陈、白水环绕，城郭之外，马鸣萧萧。游子跨上马背即将远行，浮云随风飘去，正如游子漂泊无定的行踪；夕阳缓缓西沉，迟迟不肯落山，正如故人难舍难分的深情。一飘一走，一留一落，情景交融。\n'浮云游子意，落日故人情'，以浮云、落日两个自然景象作比，写尽离别时的微妙心情。全诗对仗工整而气韵流畅，被公认为李白五律中的压卷之作，也是古代送别诗中的工致名篇。"},
  "宣州谢朓楼饯别校书叔云":{story:"此诗约作于天宝末年，李白客居宣州（今安徽宣城）之时。族叔李云任秘书省校书郎，将离开宣州，李白登上谢朓楼为他设宴饯行。谢朓是南朝齐代著名诗人，李白一向仰慕，曾称赞其诗'清发'。\n登高望远，谢朓楼的美景没有让李白忘记现实的烦恼。理想抱负无法实现，时光一天天流逝，他心中的烦忧挥之不去。起句'弃我去者昨日之日不可留，乱我心者今日之日多烦忧'，脱口而出，像脱缰的野马。\n'抽刀断水水更流，举杯消愁愁更愁'，用刀断水水更流，借酒消愁愁更愁，把无法排遣的愁绪写得形象而深刻。结句'人生在世不称意，明朝散发弄扁舟'，抒发诗人要摆脱束缚、自在生活的愿望，成为后世无数怀才不遇者的心声。"},
  "长相思":{story:"《长相思》是乐府旧题，多写男女相思。李白借题发挥，写的是更深一层的'思君'之苦。一说此诗约作于他被'赐金放还'、滞留长安之时，政治理想难以实现，便借相思来寄托。\n秋夜，金井栏边秋虫声一声声传入帘内，微寒的风让烛光也变得黯淡，孤灯不明，他却无法入睡。他卷起窗帘望月长叹，美人如花却隔在云端——这'美人'，在古诗中往往比喻君王或理想。\n长相思，摧心肝。诗人渴望被明君重用，却报国无门，只能借一首缠绵的相思曲，抒发抱负不得施展的深沉苦闷。一唱三叹，回环往复，读来令人动容。\n全诗感情真挚、音调悠长，成为李白乐府诗中的名篇，也让'长相思'三个字从此带上了绵长的思念意味。"},
"春望":{story:"唐玄宗天宝十四载（755年）冬，安禄山起兵叛乱，战火很快烧到都城长安。756年，杜甫带着家人逃难，想把家眷安顿在鄜州后，独自赶去灵武投奔新即位的唐肃宗。谁知半路被叛军抓住，押回长安。整整八个月，他身陷这座曾经繁华、如今满目疮痍的孤城。\n757年春天，长安沦陷的第二年，杜甫悄悄走出临时栖身的小院。他看见昔日巍峨的宫殿烧得只剩残墙，杂草丛生的树林里野花悄悄开着，他却像肝肠都被针扎着一样伤心。一连三个月，战火不断，没有一封家书送到鄜州，他不知道妻儿是死是活，一撮撮白发，都是被愁绪搔掉的。\n「国破山河在，城春草木深」十四个字，没有一声喊叫，却把亡国之痛写得字字泣血。一句「家书抵万金」，道尽了乱世里亲人音讯的珍贵。后世有人说，这首诗像一部用眼泪写成的史书，孩子们读它，能读懂一个诗人心里装着家国、也装着家。"},
  "春夜喜雨":{story:"759年岁末，杜甫带着家人一路颠沛流离，翻过蜀道，终于到达成都，在城西浣花溪边盖起一座草堂，也就是今天我们说的「杜甫草堂」。第二年，也就是唐肃元二年（761年）的春天，成都迎来了一场好雨。\n那是一个安静的春夜，杜甫躺在床上，忽然听见窗外细细密密的声音。他翻身起来一看——下雨了！雨丝又轻又柔，随着夜风悄悄落下，不声不响地滋润着泥土里沉睡的种子。他高兴得几乎要笑出声来：田野里的禾苗正渴着呢，这场雨简直像知道农夫心思的老朋友，在最需要的时候赶来了。\n诗人推开窗，望着黑沉沉的田野，想象天亮以后：锦官城的大街小巷，被雨水洗过的花朵沉甸甸地开着，红的、紫的、白的，一眼望不到头。全诗没有一声音高的呼喊，那份喜悦却像春雨一样浸透每一句，尤其是「随风潜入夜，润物细无声」，后来被人们用来赞美所有默默奉献、不图回报的好老师、好榜样。"},
  "望岳":{story:"唐玄宗开元二十四年（736年），24岁的杜甫刚刚考进士落了榜，却没有一点垂头丧气的样子。他背起行囊，开始到山东、河北一带漫游。年青的杜甫觉得天地广阔，正等着自己去闯荡。走到泰山脚下，他仰头一望，被这座号称「五岳之首」的大山深深震撼了。\n远远望去，泰山的青翠山色一直铺到天边，好像把齐地和鲁地都一分为二。大自然仿佛格外偏爱它，把神奇和秀美都集中在这座山上；山腰的云雾层层叠叠，把人的心都荡涤得干干净净，归巢的飞鸟一掠而过，让人忍不住睁大眼睛，想把每一只都看仔细。\n登上山顶的念头在他心里燃烧起来。他挥笔写下：「会当凌绝顶，一览众山小」——总有一天，我要登上最高峰，那时候回头看，周围的山都会显得矮小！这两句诗像一声青春的呐喊，一千多年来，不知鼓舞了多少攀登人生高峰的追梦人。后来的杜甫果然走过千山万水，只是那座让他最早喊出豪言的泰山，他一直没能再回去。"},
  "绝句":{story:"唐肃宗上元元年（760年），经过四年的逃难生活，杜甫一家终于在成都西郊浣花溪边安定下来。他在溪边盖起草堂，窗前有菜园，屋后有小溪，房前屋后的竹林把喧嚷隔在外面，江面上天天有船只往来。奔波了半生的诗人，第一次尝到了安稳日子的味道。\n第二年的早春，成都的天格外蓝。杜甫推开门，一幅画似的景象扑进眼里：窗前的柳树枝条碧绿，几只黄鹂鸟在枝条间蹦来跳去，叫声又清又亮，像在唱歌；抬头一看，一行白鹭排着整齐的队伍，一直飞上湛蓝湛蓝的天空。门外是通往雪山的万里船道，窗里是终年不化的西山积雪，一整年的日子都被映衬得明明亮亮。\n四句诗，一句一景，像四张彩绘的小画拼在一起，被称为「绝句入画」的典范。「两个黄鹂鸣翠柳，一行白鹭上青天」色彩鲜明、声音清脆，成了孩子们学唐诗时最爱朗读的名句，也让今天的我们，看见了诗人在苦难间隙里难得的好心情。"},
  "登高":{story:"唐大历二年（767年）秋天，56岁的杜甫独自登上夔州城外的高台。此时的他，已经离开故乡整整十一年。安史之乱虽然平定五年了，但战乱的余波还在，唐朝像一台散了架的马车，他自己的身体也一天不如一天——肺病、风痹折磨着他，右耳几乎听不见声音，牙齿也掉了一半。\n重阳节登高本应是饮酒赏菊的欢乐日子，杜甫却只能拄着拐杖，一步一步挪上台去。他望着眼前的景象：无边无际的树林，枯叶被秋风卷得萧萧而下；长江滚滚东流，永不停歇，也永不回头。这景象多像他自己啊——落叶是衰老的自己，江水是流走的一生。\n他想起万里之外的故乡，想起一年比一年多的繁霜白发，想起这一生艰难的漂泊，悲从中来。全诗八句，每一句都对得严丝合缝，被誉为「古今七言律诗第一」。「无边落木萧萧下，不尽长江滚滚来」十四个字，把一个人、一个时代的悲凉，写得像长江一样深沉无尽，千百年后读来，仍让人心头一震。"},
  "江畔独步寻花":{story:"唐肃宗上元二年（761年）的春三月，成都的锦江两岸正是花开得最热闹的时候。杜甫在草堂里闷了几日，终于忍不住出了门，沿着江边小路，一个人慢慢散步寻花。他写了七首寻花诗，这一首是第六首。\n走呀走呀，他来到锦江边一户人家门口。相传这家的主人姓黄，排行第四，是个爱种花的女子，乡邻们都亲热地叫她「黄四娘」。杜甫刚靠近院墙，就被眼前的景象惊呆了：满院子的花层层叠叠，把小路都遮住了，千朵万朵的花把枝条压得低垂下来，像花的瀑布一样垂到墙外。\n彩色的蝴蝶在花丛里飞来飞去，舍不得离开；自由自在的小黄莺叫声又娇又软，像在拉着人不让走。老诗人站在花下，看蝴蝶、听莺啼，几乎忘记了回家的路。「留连戏蝶时时舞，自在娇莺恰恰啼」两句，像会动的画，把春天写活了，也成为孩子们描写春日最常用到的诗句。"},
  "月夜忆舍弟":{story:"唐肃宗乾元二年（759年），安史之乱的第四年，关中大饥荒，人们没有粮食吃。杜甫带着一家老小逃难，走到秦州（今天甘肃天水）时，几个弟弟却因为在战乱中各自逃散，谁也不知道谁在哪里。那时候没有电话、没有书信，消息一断，就像石沉大海。\n这年秋天的一个夜晚，正是农历二十四节气里的「白露」节令。杜甫独自站在秦州的院子里，夜风已经很凉了，草叶上结起白白的露珠。他抬起头，一轮明月挂在天上，忽然觉得，还是故乡的月亮最明、最亮。他想起小时候和四个弟弟一起玩耍、一起读书的日子，心里像被什么揪住了：今夜，散落各处的弟弟们，是不是也正望着同一轮月亮？明天这露水更重，就要到白露节气了，可他们有没有棉衣穿？有没有热粥喝？「有弟皆分散，无家问死生」，一家五个兄弟，活要见人，死要见尸，竟连问一句的地方都没有了。\n「露从今夜白，月是故乡明」十个字，把白露的凉和思念的暖交织在一起，成为中秋和月夜思念亲人时，中国人引用最多的诗句之一。后来的杜甫，直到晚年也没能把分散的弟弟们都找回来，这份手足深情，读来格外令人心酸。"},
  "蜀相":{story:"唐肃宗上元元年（760年），杜甫刚到成都不久，就专程去拜谒了城外那座翠柏环绕的祠堂——纪念诸葛亮的武侯祠。刘备与诸葛亮君臣相得的蜀汉故事，杜甫从小就烂熟于心。他自己一生怀才不遇、报国无门，此刻站在这座祠堂前，心里百感交集。\n他沿着柏树夹道的石阶一步步走进祠堂，四周幽静，碧绿的春草悄悄映在台阶上，黄鹂鸟在密叶深处自顾自地啼叫，仿佛在替人伤心。他不禁想：当年诸葛亮隐居隆中，刘备三顾茅庐请他出山， 他定下三分天下的谋略，辅佐两朝君主，勤谨辛劳，直到生命的最后一刻。\n最著名的两句来了：「出师未捷身先死，长使英雄泪满襟」。诸葛亮六出祁山，眼看就要成功，却在五丈原的军营里积劳成疾，五十四岁就离开了人世。这份「壮志未酬」的遗憾，让后世多少英雄豪杰一读落泪——抗金名将宗泽临终前反复吟诵这两句诗，怀着没能收复中原的遗恨离开了人世。杜甫把对诸葛亮的敬仰、也是对自己身世的不平，全都融进了这首诗里，它也因此成为咏赞诸葛亮最有名的一首诗。"},
  "赠花卿":{story:"「花卿」是谁呢？他就是当时驻守成都的武将花敬定。唐肃宗上元二年（761年）前后，梓州刺史段子璋发动叛乱，花敬定奉命率兵平定，立下了战功。可是打胜仗之后，他居功自傲，变得骄横起来，甚至在自己的宴席上，演奏起本该天子才能用的宫廷乐曲。要知道，在等级森严的唐朝，礼乐是有严格规矩的，王公大臣用了天子之乐，是要杀头的重罪。\n杜甫和成都的地方官经常应邀出席花敬定的宴会。有一天，他又听到堂上乐声悠扬，美如仙乐，十分动听。聪明的杜甫没有当面批评花敬定，那样做太危险；也没有直接举报，毕竟花敬定刚立战功。他眉头一皱，提笔写下了一首赞美乐曲的诗，把赞美藏在字缝里。\n「此曲只应天上有，人间能得几回闻」——表面上是说：这样美妙的乐曲，大概只有天上的仙宫才有吧，人间能听到几回呢？实际上是在委婉地提醒：这首曲子是天子御用之乐，普通百姓（包括你花将军）怎么能随便听呢？后人把这种绕着弯子提意见的方法叫作「讽喻」，这首诗也因此成为中国诗歌史上「温柔讽谏」的经典例子，大人和孩子们一起读，能读出话里有话的智慧。"},
  "江南逢李龟年":{story:"李龟年是谁？他是唐玄宗开元年间名满天下的歌唱家，经常在王公贵族的宴会上献唱，连唐玄宗都非常欣赏他。而年轻的杜甫，当年正在长安求取功名，常常出入岐王李隆范和中书监崔涤的府邸，没少听李龟年唱歌。那时候的开元盛世，长安夜夜笙歌，是多少人心中的美好记忆。\n可是好景不长。755年安史之乱爆发，盛世像一场美梦被彻底打碎。唐玄宗仓皇逃往蜀地，李龟年流落江南，靠着在酒席间卖唱为生。而杜甫更惨，战乱中他颠沛流离十几年，辗转到了湖南潭州（今天的长沙）。\n唐代宗大历五年（770年），也是杜甫生命的最后一年，一个暮春时节，杜甫在街上忽然遇见了一位两鬓斑白、衣衫破旧的老人——竟是当年的大歌唱家李龟年！四十年前，一个是意气风发的青年才子，一个是名动天下的歌坛巨星，在长安的宴席上何等风光；四十年后，两个老人却在落花飘零的江南，凄凉重逢。「正是江南好风景，落花时节又逢君」，「落花时节」四个字，明写春光将尽，暗写国运衰微、人生暮年，一个「又」字，藏着说不尽的沧桑。这首诗只有短短二十八个字，却把四十年的盛唐与衰世，写得荡气回肠，被称为杜甫绝句中的压卷之作。"},
"相思":{story:"相传这首诗原题《江上赠李龟年》，是王维写给好朋友、当时最有名的音乐家李龟年的。李龟年常在王公贵族家唱歌，连唐玄宗都是他的知音。王维把满腔的思念之情寄托在一颗小小的红豆里，写成了这首《相思》。\n安史之乱爆发后，长安城一片混乱，李龟年流落到江南。相传每逢有人请他唱歌，他总爱唱这首《相思》，唱着唱着便泪流满面，听的人也无不跟着落泪。一颗小小的红豆，就这样唱哭了整个江南。\n红豆又叫相思子，颜色鲜红，古人常用它寄托思念。王维用『愿君多采撷，此物最相思』告诉我们：最真挚的感情不需要华丽的话，只需要一件小小的信物就够了。从此，红豆就成了中国人心里永远的相思信物，直到今天，恋人们还把它当作传情的礼物。"},
  "鹿柴":{story:"唐玄宗天宝年间，王维在长安附近的辋川山谷里营建了一座庄园，叫作辋川别业，过起了半官半隐的生活。他喜欢这里的山山水水，常和朋友裴迪一起游山玩水、互相作诗唱和，两人各写二十首，合编成《辋川集》。《鹿柴》就是其中流传最广的一首。\n鹿柴（『柴』在这里读zhài）是辋川别业里一处养鹿的栅栏和幽静的树林。王维写诗时，眼前是空无一人的山林，只偶尔传来一两声人说话的声音。夕阳的金光斜斜地照进深林，又落在幽暗的青苔上，一闪，就不见了。\n『空山不见人，但闻人语响』用声音来衬托安静；『返景入深林，复照青苔上』又让一线光在幽暗中忽明忽暗。王维心中装着佛家的禅意，笔下的空山像一个安静的梦。宋代苏轼说王维『诗中有画，画中有诗』，这首二十字的小诗，就是最好的证明。"},
  "竹里馆":{story:"这首《竹里馆》也是王维隐居辋川时写的，是《辋川集》二十首之一。辋川竹林茂密，溪水潺潺，王维常常独自在竹林里静坐、弹琴，和大自然作伴。\n一个月色明亮的夜晚，王维独自坐在幽深的竹林里，一边弹琴，一边撮口长啸（古人用口发出悠长的声音来抒发心声）。竹林深深，没有人知道这里有一个人，只有一轮明月，静静地照着他。\n『深林人不知，明月来相照』——明明是独自一人，诗人却不觉得孤单，因为有明月像老朋友一样陪伴着他。全诗只有二十个字，却把幽静、自在、孤独又不寂寞的滋味写得干干净净。这份人与自然相亲的安然，正是王维最迷人的地方。"},
  "送元二使安西":{story:"渭城就是今天陕西咸阳一带，是唐代出阳关、前往西域的必经之地。有一年春天，王维的朋友元二奉朝廷之命出使安西都护府（在今天新疆库车一带），王维专程赶到渭城为他饯行。清晨刚下过一场小雨，打湿了路上的尘土，客舍边的柳树被洗得格外青翠。\n临别时，王维端起酒杯，殷殷劝道：『劝君更尽一杯酒，西出阳关无故人。』阳关再往西，就是茫茫大漠，老朋友一个也见不到了。再多喝一杯吧，把故乡的这份情谊都装在心里带走！\n这首诗后来成了最有名的送别诗。人们为它谱上曲调，歌唱时把诗句反复咏唱三遍，所以又叫《阳关三叠》。一千多年来，多少人在离别的路口反复吟唱：西出阳关，故人在心。"},
  "九月九日忆山东兄弟":{story:"相传唐玄宗开元四年（公元716年）前后，十七岁的王维独自一人在长安求学。重阳节那天，全城的人都登高、插茱萸、和家人团聚，只有王维孤零零地住在旅舍里，看着别人家热热闹闹，心里格外想念远在蒲州（今山西永济）家乡的亲人。\n于是他提笔写下这首传诵千年的诗：『独在异乡为异客，每逢佳节倍思亲。遥知兄弟登高处，遍插茱萸少一人。』他想象着家乡的兄弟们登高插茱萸时，一定会发现：怎么偏偏少了我一个人呢？不直接说自己想家，却说家人正在想念自己，这份心思多么细腻啊！\n『每逢佳节倍思亲』七个大字，把古往今来所有游子的心声都说了出来。据说这首诗让年少的王维在长安一举成名。直到今天，每逢中秋、春节回不了家的人，心里都会默念这一句。"},
  "山居秋暝":{story:"王维隐居辋川期间，最爱秋雨初晴的傍晚。一场秋雨刚刚停歇，空山被洗得干干净净，空气里带着泥土和草木的清香。月亮升起来了，松林里洒下斑驳的月光，竹林深处传来洗衣姑娘归来的欢声笑语，顺流而下的渔舟摇碎了水面的银光。\n王维把眼前的美景写进《山居秋暝》：『明月松间照，清泉石上流。』明亮的月光从松树间静静洒下，清亮的泉水在石头上淙淙流淌——一动一静，一光一声，像一幅会呼吸的水墨画。\n诗的末尾他说：『随意春芳歇，王孙自可留。』春天过去了没关系，秋日的山林一样可爱，我愿意留在这里。他借这句诗巧妙地说：官场再热闹，也比不上山里的清静自在。这首诗后来被誉为山水诗的极品，多少人读它，都忍不住想去山里住一住。"},
  "鸟鸣涧":{story:"王维有一位朋友名叫皇甫岳，他的云溪别墅坐落在幽静的山谷里。王维受邀去做客，一连写下六首组诗来歌咏那里的风光，《鸟鸣涧》是其中最出名的一首。『涧』就是山间的小溪。\n那是一个春天的夜晚，山谷里安静极了。桂花无声无息地飘落，月亮忽然升起来，月光惊醒了山中安睡的鸟儿，它们偶尔在山涧里发出一两声清脆的鸣叫。『月出惊山鸟，时鸣春涧中』——表面在写鸟叫，其实是用这一点点声音，把整座山的幽静衬托得更加深沉。\n这种以动衬静的写法，是中国古诗里最高明的手法之一。全诗四句像四格小动画：花落、月出、鸟惊、鸟鸣，最后定格在一条安静的春涧上。苏轼评价王维『诗中有画』，这首小诗，就是一幅会发声的月夜山水画。"},
  "画":{story:"《画》是一首有趣的谜语诗。相传王维看到一幅山水画，觉得画上的山水太逼真了：远远看去，颜色那样鲜明，仿佛真山一样；可走到跟前一听，画上哪有哗哗的水声呀！\n于是他把这种有趣的感受写成四句：『远看山有色，近听水无声。春去花还在，人来鸟不惊。』咦，春天都过去了，画里的花怎么还开着？人走到跟前，画里的鸟怎么也不飞走呀？——原来这是一幅画呀！\n这首诗四句都在夸画的妙处：画能把春天最美的颜色永远留住，画里的小动物永远那么安静可爱。最浅白的话，写出最深的趣味，难怪它千百年来一直伴着孩子们开口学诗。"},
  "杂诗":{story:"王维长年在外做官、游历，故乡在遥远的蒲州。有一次，他在异乡忽然遇见一位从家乡来的老朋友，心里一下子涌起了千言万语。他多想问问家里的每一个人、每一件事啊！\n可奇怪的是，王维开口问的既不是爹娘的身体，也不是家里的大事，而是：『来日绮窗前，寒梅著花未？』——动身那天，我家雕花窗前的那株寒梅，开了花没有？\n窗前的一株梅花，装着他整个童年的记忆。不问别的只问梅，正是因为太思念，反而不知从何问起。乡愁太深，所以只问一枝梅花，这份含蓄与深情，正是这首诗最打动人的地方。一千多年后的今天读到这句诗，我们依然能体会到游子心头那一点酸酸柔柔的牵挂。"},
  "赋得古原草送别":{story:"相传白居易十六岁那年初到长安，带着诗稿去拜见大诗人顾况。顾况看到他名字里的『居易』二字，笑着打趣说：『长安米贵，居大不易啊！』意思是京城开销大，想站稳脚跟可不容易。\n可是当顾况读到『野火烧不尽，春风吹又生』两句时，眼睛一下子亮了，拍案叫好，改口说：能写出这样的诗句，在长安居住就很容易了！从此，少年白居易名声大振。\n这首诗本是白居易为科举考试练习写的『赋得体』习作，题目里的『赋得』就是考场作文的意思，谁能想到竟流传千古。『野火』两句写出野草顽强的生命力，今天人们还常常用它比喻压不垮、烧不尽的希望与生机。"},
  "忆江南":{story:"白居易一生最幸福的一段时光，是在杭州和苏州做刺史的日子。他带领百姓修筑西湖的白堤，写下许多歌咏江南的诗。晚年他定居洛阳，人老了，江南的山山水水却常常在梦里回来。\n唐文宗开成三年（公元838年），六十七岁的白居易一连写下三首《忆江南》。他回忆道：『日出江花红胜火，春来江水绿如蓝。』清晨的太阳升起来，江边的花朵红得比火焰还要艳；春天来了，江水碧绿得像蓝草染过一样。\n『红胜火』和『绿如蓝』两个比喻，把江南春天的颜色写到极致；『能不忆江南？』一句反问，把满腔怀念轻轻收住。这三首小词当时就传遍大街小巷，直到今天，『江南好』三个字仍是中国人心头最温柔的风景。"},
  "暮江吟":{story:"唐穆宗长庆二年（公元822年），白居易离开京城，乘船前去杭州担任刺史。船行长江，九月初三的傍晚，他站在船头，看见一道残阳的余晖铺在江面上，江水一半被染得通红，一半仍是深深的碧色，美得让人屏住呼吸。\n夜幕降临，他再看岸边：草叶上的露珠一颗颗亮晶晶的，像圆润的珍珠；一弯新月升上天空，像一张精巧的弓。白居易高兴得脱口吟出：『可怜九月初三夜，露似真珠月似弓。』\n『可怜』在古诗里是『可爱』的意思。全诗从傍晚写到入夜，从残阳写到新月，像一部短短的电影。白居易最擅长发现平凡日子里的美，他告诉我们：只要留心看，沿途处处都是诗。"},
  "池上":{story:"晚年的白居易住在洛阳，心境闲适，喜欢观察身边的小事。一天，他在池塘边散步，忽然看见一个可爱的小娃娃撑着小船，偷偷采了一支白莲花回来，那天真烂漫的模样把他逗乐了。\n小娃娃采到莲花高兴极了，却完全不懂得掩藏行踪——小船划过，水面的浮萍荡开一道清清楚楚的水路，把『小贼』的行踪全暴露啦！白居易把这个有趣的画面写进诗里：『小娃撑小艇，偷采白莲回。不解藏踪迹，浮萍一道开。』\n全诗没有一个难字，却像动画片一样活灵活现。诗人没有责备偷采的小娃，满纸都是慈爱的笑意。大人读它想起童年，孩子读它学会观察——这就是白居易最厉害的地方：用最简单的诗，写最真的生活。"},
  "问刘十九":{story:"白居易在江州（今江西九江）做官时交了不少知心朋友，刘十九就是其中一位，相传是位隐居的处士，两人常在一起喝酒谈心。这首诗，就是白居易在一个冬日傍晚写给老朋友的一封小小邀请信。\n那天天色阴沉，眼看就要下雪了。白居易忽然想起老朋友，家里正好有新酿的米酒——刚酿的酒面上浮着细小酒渣，像一群绿蚂蚁，所以叫『绿蚁』；红泥做的小火炉也烧得旺旺的。于是他提笔写道：『绿蚁新醅酒，红泥小火炉。晚来天欲雪，能饮一杯无？』\n窗外冷风呼呼，屋内炉火融融，一句『能饮一杯无』，像老朋友轻轻拍着你的肩膀。全诗二十个字，没有一个华丽字眼，却把中国式待客的温暖和体贴写得恰到好处。一千多年过去，每逢雪夜，人们还是会想起这壶温热的酒。"},
  "大林寺桃花":{story:"唐宪宗元和十二年（公元817年），白居易被贬江州司马已经第四个年头。暮春时节，他游庐山，走进山上的大林寺，惊讶地发现：山下早已百花凋谢，这高山古寺里的桃花，才刚刚盛开！\n白居易又惊又喜，提笔写道：『人间四月芳菲尽，山寺桃花始盛开。』山下的花儿为什么谢了，山寺的桃花却开得正艳？——原来是山上冷，春天也爬得慢呀！诗人高兴得像个孩子：『长恨春归无觅处，不知转入此中来。』我常常遗憾春天悄悄走了，再也找不到它，原来它是转了个弯，躲到山里来了！\n被贬的愁闷，被这一片桃花一扫而空。这首诗用一次小小的发现，讲出一个科学小知识——海拔越高，气温越低，花开得越迟；也说出一个人生道理：美好从不曾真正离开，它只是换了个地方等我们。难怪后人把大林寺的桃花称作白居易的诗桃花。"},
"夜雨寄北":{story:"唐宣宗大中二年（约848年），李商隐在巴蜀一带游历做幕僚，长年漂泊在外。一个秋夜，窗外巴山的雨淅淅沥沥下个不停，涨满的秋池映着昏黄的灯光。这时他收到了一封来自北方长安的家书，妻子在信中轻声问他：你什么时候才能回来呀？\n李商隐望着夜雨，满心愧疚。这一年他仕途不顺，东川节度使柳仲郢的幕府事务繁忙，归期实在定不下来。他提笔回信，先安慰妻子：你问我归期，归期还很难说准啊。此时的巴山，夜雨涨满了秋池，我的思念也涨满了心。\n信写到这里，诗人的笔尖忽然轻轻一转，跳进了想象中的未来：什么时候我们才能一起坐在西窗下，剪着烛花彻夜长谈，再回头说起今天巴山夜雨的情景呢？\n这一句「何当共剪西窗烛，却话巴山夜雨时」妙极了——此刻的孤独，变成了将来重逢时的温馨话题；今天的雨，成了明天笑着回忆的故事。时间与空间在心里打了个回环，一句诗里装下了现在和未来两颗心。千百年来，无数游子读到这里都会眼眶发热。"},
  "登乐游原":{story:"乐游原在长安城南，地势高高隆起，站上去能望见整座京城。相传这里是汉宣帝许皇后葬地，后来修成皇家游览胜地，唐朝的贵族们最爱在这里登高赏景、宴饮赋诗。\n唐宣宗大中元年（约847年）前后，李商隐已年近四十，仕途坎坷，寄人篱下做幕僚，内心十分抑郁。一个傍晚，他心情烦闷，独自驾着马车登上乐游原，想借落日美景驱散胸中的愁云。\n登上高处，他看见了平生最美的夕阳：金色的晚霞铺满天边，整个长安城都被镀上一层温柔的光。诗人沉醉了，可紧接着一声轻轻的叹息——夕阳无限好啊，只是已经临近黄昏，这壮丽的美景转眼就要消失了。\n这声叹息里藏着深深的家国之忧。李商隐生活在晚唐，藩镇割据、宦官专权，大唐王朝正如这落日，灿烂却已临近衰亡。后世人们常用「夕阳无限好，只是近黄昏」来惋惜一切美好而短暂的事物，这两句诗也成了中国人心中最著名的一声叹息。"},
  "清明":{story:"晚唐的某一个清明节，杜牧在赶路。清明本是扫墓祭祖、踏青游春的日子，纷纷扬扬的细雨飘洒下来，打湿了行人的衣衫和心情。路上的行人中，有人上坟归来泪眼未干，有人赶路在外思乡心切，一个个神情凄迷，像丢了魂一样——这就是诗里说的「路上行人欲断魂」。\n杜牧走在这样的雨里，也被这凄清的气氛浸湿了心情。他多想找个小酒馆，喝上一杯暖暖身子、解解愁绪啊。正巧，路边走来一个骑在牛背上的小牧童，杜牧忙上前含笑询问：小朋友，请问哪里有酒家？\n小牧童抬起小手，朝远处一指——那杏花盛开的村庄深处，酒旗正迎风招展。放眼望去，粉白的杏花如烟似霞，一幅明丽的画面在迷蒙雨雾中忽然亮起，前一句的愁苦顿时化成了惊喜。\n杜牧把这一幕写进诗里，只有短短四句，却像一幅会动的画：雨、行人、牧童、杏花村。从此「杏花村」名扬天下，今天许多产酒的地方都争着说自己的村子就是诗中的杏花村，杜牧的一支笔，竟给一个村庄做了上千年的广告。"},
  "山行":{story:"杜牧做过池州刺史，池州就是今天的安徽贵池，那里山清水秀。一个深秋的日子，他沿着弯弯曲曲的山路前行，白云从山中人家的地方袅袅升起——「远上寒山石径斜，白云生处有人家」，清冷的山景里藏着温暖的人间烟火。\n走到一片枫树林前，杜牧忽然停下了车。原来他被眼前的美景迷住了：傍晚的枫林在夕阳下红得发亮，比春天二月盛开的鲜花还要艳丽！霜打过的枫叶怎么会这么红？因为深秋的寒霜反而让枫叶里的红色素显现出来，越冷越红，像一团团燃烧的火焰。\n一般的诗人写秋天，总爱写萧瑟、写落叶、写伤感，杜牧却偏要大声赞叹：「停车坐爱枫林晚，霜叶红于二月花」。这里的「坐」是「因为」的意思——停车，是因为太爱这傍晚的枫林了。\n这句诗用春天的花朵来反衬秋天的红叶，翻出了前人没有写过的新意：秋天不只是凋零的季节，也可以是最绚烂的季节。后来人们常用这句诗鼓励孩子换个角度看世界，困境里也能发现动人的美。"},
  "江南春":{story:"杜牧生活的时代，唐朝已经走向衰落，可富饶美丽的江南依旧生机勃勃。他曾经游历江南，把一路见到的春光写进了这首《江南春》。\n诗的开头就像铺开一幅巨大的画卷：千里江南，黄莺在绿树间婉转歌唱，红花映着水边的村庄，酒旗在山城和城郭间随风招展——「千里莺啼绿映红，水村山郭酒旗风」。莺啼、绿树、红花、水村、酒旗，有声有色，孩子闭上眼睛就能看见那片明媚的春光。\n画卷再往前铺，眼前出现了更多的楼台。南朝时期，佛教兴盛，梁武帝等皇帝大力修寺建庙，光是金陵（南京）一带，就建起四百八十座佛寺。如今这些古寺矗立在朦胧的烟雨之中，若隐若现——「南朝四百八十寺，多少楼台烟雨中」。「四百八十」不是精确数字，是说佛寺多得数不清。\n美景写到最后，诗人的心情却沉了下来：南朝的皇帝们大建佛寺求佛祖保佑，可江山照样一代代灭亡。楼台还在烟雨中静默，王朝却早已换了人间。这首诗表面写江南春光，内里藏着对历史兴亡的深深感慨，景越美，这份感慨就越悠长。"},
  "泊秦淮":{story:"秦淮河穿过金陵（今天的南京），两岸酒肆歌楼灯火辉煌，是六朝古都最热闹的地方。一个夜晚，杜牧乘船夜泊秦淮，河对岸灯火迷离，歌声随风飘来，他听着听着，眉头皱了起来。\n因为他听出歌女们唱的是《玉树后庭花》——这正是南朝陈后主写的亡国之音。陈后主名叫陈叔宝，是南朝陈朝的最后一位皇帝。他宠信贵妃张丽华，整天和张丽华、孔贵嫔等人在后宫饮酒赋诗、寻欢作乐，不理朝政。隋朝的军队已经打到大江对面了，他还抱着张丽华躲在景阳宫的一口井里，结果被隋兵用绳子一并吊了上来，成了亡国俘虏。《玉树后庭花》就是他亲手填的曲子，陈朝灭亡后，这支曲子成了「亡国之音」的代名词。\n此时的大唐，藩镇割据、国势日衰，而达官贵人们还在秦淮河上夜夜笙歌。杜牧悲愤地写下「商女不知亡国恨，隔江犹唱后庭花」。表面上是责怪唱歌的歌女不懂亡国之恨，其实是借古讽今——真正「不知亡国恨」的，是那些听歌享乐、醉生梦死的权贵们。\n这首诗把历史故事和眼前实景叠在一起，警告意味深长。千年之后，每当人们听到靡靡之音响起，还会想起秦淮河上这清醒的吟唱。"},
  "赤壁":{story:"唐文宗时期，杜牧被任命为黄州刺史。黄州城外有座赤鼻矶，江边山岩呈赭红色，相传是三国赤壁之战的古战场（一说真正的赤壁在湖北蒲圻）。一天，杜牧来到这里凭吊古迹，竟在江边的泥沙里发现了一支折断的铁戟。\n他拾起铁戟，洗去泥沙，认出这是前朝三国时期的兵器。铁戟沉睡江底六百多年，被这一场战争沉入泥沙——「折戟沉沙铁未销，自将磨洗认前朝」。一件小小的兵器，把诗人带回了那场惊天动地的大战。\n东汉建安十三年（208年），曹操率大军南下，孙权和刘备结成联盟，由周瑜率领吴军在赤壁迎战。曹军多为北方人，不习水战，就把战船首尾相连。周瑜的部将黄盖假意投降，乘着装满柴草、浇满油脂的战船冲进曹军水寨，借着东南风纵火，烧得曹军灰飞烟灭。这场战役中，东风起了决定性作用。杜牧于是奇想突发：「东风不与周郎便，铜雀春深锁二乔」——假如那天不刮东风，周瑜就要打败仗，江东的两位美女大乔、小乔，只怕要被曹操掳去，深锁在铜雀台里了。\n铜雀台是曹操在邺城修建的高台，台上养了许多歌伎，传说他想把美女都收罗其中。杜牧用这个大胆的假设感叹：一场战争的胜负，有时竟系于一缕风、一点点运气。怀古的诗人人都写，他这首却翻出了新角度，这是晚唐咏史诗里最奇峭的议论之一。"},
  "赠别":{story:"唐文宗大和九年（835年），杜牧在扬州淮南节度使幕府任职。他才华横溢却职务清闲，年轻的杜牧有时也出入歌楼舞榭。同僚韩绰（也是他的好朋友）与他诗酒唱和，而一位年轻美丽的歌妓，更让他久久难忘。\n这年春天，杜牧奉命离开扬州回京城长安任职。临别之际，他把满腔的惜别之情写成两首《赠别》，这是其中第一首，赠给这位歌妓（一说赠给友人）。诗中先把她比作风中柔嫩轻盈的柳枝——娉娉袅袅十三余，豆蔻梢头二月初。豆蔻是一种初夏开花的植物，含苞待放的花朵娇嫩无比，用来比喻十三四岁的少女，再贴切不过，「豆蔻年华」这个成语就是从这句诗来的。\n接着诗人说：就算走遍春风十里的扬州路，把珠帘一一卷起来看遍所有歌楼，所有的女子都比不上你啊——「春风十里扬州路，卷上珠帘总不如」。扬州是天下最繁华的都市，十里长街美女如云，可在他眼里，谁都比不上眼前这一位。\n这两句诗夸人不落俗套，没有直接说她美，而是用十里扬州的繁花似锦来做陪衬，越发显得独一无二。后来人们夸人或夸物出类拔萃，常常借用这个句子，可见杜牧的笔有多动人。"},
  "寄扬州韩绰判官":{story:"杜牧离开扬州回长安后，一直惦记着江南的老朋友韩绰。韩绰当时还在扬州做判官，是杜牧在幕府中的同僚，两人当年诗酒往来、十分相得。分别之后，一个在北，一个在南，杜牧常常想起扬州的月色。\n于是在一个秋夜（一说冬夜），他提笔写下了这首问候友人的诗：青山隐隐起伏，绿水悠悠远去，秋意渐浓，草木已经凋残——「青山隐隐水迢迢，秋尽江南草未凋」。诗人身在北方，心却顺着青山碧水飞回了江南，他仿佛看见：扬州的秋天尚未深透，草木还绿着呢。\n写到后两句，他的想象更加具体而浪漫：二十四桥的明月照着清夜，老朋友啊，此刻你在何处教歌女们吹箫呢——「二十四桥明月夜，玉人何处教吹箫」。「玉人」既可以指美丽的人，也可以指朋友韩绰，这里分明带着老朋友间的玩笑和调侃：你是不是又逍遥自在去了？\n二十四桥是扬州的名胜，相传隋代曾在扬州建有二十四座桥，一说有座桥名叫二十四桥。这些细节如今已难考证，但「二十四桥明月夜」七个字，把扬州的月夜写成了中国人心中最美的江南意象。直到今天，扬州人提起家乡的月色，第一个想到的还是这句诗。"},
  "过华清宫":{story:"华清宫坐落在长安城东的骊山上，原是唐太宗建的汤泉宫，唐玄宗扩建后成了与杨贵妃游乐的离宫。从长安东去，必经骊山脚下。杜牧某次途经此地，望着山上的宫殿遗址，想起了一段荒唐的往事。\n唐玄宗李隆基早年英明有为，开创了开元盛世，晚年却宠爱杨贵妃，沉湎享乐。杨贵妃是蜀地人，最爱吃新鲜的荔枝。可荔枝产于岭南和四川，离长安几千里路，而且荔枝一日变色、二日变味，极易腐坏。为了让贵妃吃到带着露水的鲜荔枝，唐玄宗下令每到荔枝成熟时，就用快马一站接一站地飞骑接力运送，人马昼夜不停，逢山开路、遇水搭桥，多少差官马匹累死在途中，多少百姓田地被飞驰的马蹄践踏。\n杜牧想象着当年的情景：尘土飞扬的驿道上，一骑快马疾驰而过，宫门里杨贵妃远远望见，嫣然一笑——没有人知道，那马背上风尘仆仆送来的，只是给贵妃解馋的荔枝啊——「一骑红尘妃子笑，无人知是荔枝来」。\n一个「笑」字和后面一句对照，贵妃的开心和驿使的辛苦、百姓的疾苦形成强烈反差，讽刺入骨。杜牧还写过《华清宫绝句三首》，其中一首「长安回望绣成堆，山顶千门次第开」说的正是同一件事。这首小诗寥寥二十八字，把一段宠妃误国的历史永远钉在了骊山脚下，千年之后读来，仍能听见那蹄声里的叹息。"},
  "遣怀":{story:"杜牧出身名门，祖父杜佑是唐代著名宰相，他自己更是少年成名，怀有经邦济世的大志向，曾研究兵法、注解《孙子》，梦想着建功立业。可现实的仕途却屡屡受挫，他大半生都在幕府里做幕僚，大志难酬。\n唐大和七年至九年（833至835年），杜牧在扬州淮南节度使牛僧孺的幕府任职。年轻的他放浪形骸，常去歌楼酒馆，牛僧孺不放心，还曾悄悄派士兵便衣保护他。多年后回首这段岁月，杜牧的心情五味杂陈。约在唐文宗开成二年（837年）前后，他写下这首《遣怀》，为往事做个了结。\n他先是自嘲：想当年落魄江湖，携酒而行，把腰缠十万的富翁也看作轻飘飘的一缕细绳（「楚腰纤细掌中轻」用楚王好细腰和赵飞燕可作掌上舞的典故，形容歌女的娇美）；接着一声长叹——「十年一觉扬州梦，赢得青楼薄幸名」。\n扬州十年，恍然像一场大梦；梦醒来数一数「收获」，只换来青楼歌伎们一句「薄情郎」的名声。看似轻松诙谐的自嘲，骨子里却藏着深深的痛楚：大好的青春年华，本该用来实现抱负，如今却只换来一个荒唐的名声。这一声自嘲式的感慨，戳中了后世无数怀才不遇者的心，「十年一觉扬州梦」也成了感叹岁月虚度的千古名句。"},
"春晓":{story:"孟浩然一生大部分时间隐居在襄阳的鹿门山，那里青山环抱，鸟语花香。相传他三十多岁时在这里过春天，一天夜里睡得很香，窗外下了一场春雨，打得屋檐沙沙作响，他却一点也不知道。清晨醒来，只听见满院子的鸟儿叽叽喳喳，像在唱歌比赛，随口就哼出了「春眠不觉晓，处处闻啼鸟」这两句。\n可是唱着唱着，他忽然想起夜里迷迷糊糊听到的风雨声，心里一紧：那么多开在春风里的花儿，该被吹落了多少呀？于是他轻轻叹了一声「夜来风雨声，花落知多少」。你看，他不写自己跑出去看花，只写躺在床上的一场想象，那份爱惜春天的心意，反而更打动人。\n这首诗只有二十个字，没有奇巧的字眼，就像小朋友早晨醒来时自然而然的念叨，却成为千古流传的第一春诗。后来的人们一到春天，几乎都会想起它。"},
  "过故人庄":{story:"孟浩然隐居襄阳鹿门山时，有一位住在村野的老朋友。一天，老友派人捎信来，请他到田家做客，还备好了黄米饭和现杀的鸡。这在当时是最真诚、最隆重的款待。孟浩然高高兴兴地赶去，一路上青山在窗外倒退，村庄掩映在绿树里，远远还能望见城郭的轮廓，他脱口吟出「绿树村边合，青山郭外斜」。\n老朋友的院子干干净净，场院敞亮，围坐着吃饭时，大家推开窗，一面喝酒一面闲谈今年的桑麻收成，说着今年的庄稼长得好不好，这便是「开轩面场圃，把酒话桑麻」。没有山珍海味，也没有高谈阔论，可这份农家待客的实在与暖意，让孟浩然格外留恋。\n临走时，他恋恋不舍，和老友约定：等到九月九日重阳节菊花盛开的时候，我还要回来，和你一起赏菊饮酒。这就是尾联「待到重阳日，还来就菊花」。这首诗句句都是平常话，却写出了中国乡村待客最温暖的样子，后来「重阳就菊」也成了朋友间重聚的美谈。"},
  "宿建德江":{story:"唐玄宗开元十八年（约公元730年），四十岁的孟浩然离开家乡襄阳，乘船去长安求取功名，希望有人能引荐他做官。船行到浙江建德江（今新安江一带）时，天色渐渐暗了下来，他把船停靠在江中一个烟雾蒙蒙的小洲边，一个人孤零零地过夜，于是写下这首小诗。\n「移舟泊烟渚，日暮客愁新」，船一停下，四野无人，只有暮色一层层压下来，旅人的忧愁便悄悄涌上心头。接着他抬起头看天空，原野空旷辽阔，远处的天空好像比树还要低，低低地压在头顶；低头再看江水，清清亮亮，月亮倒映在水里，仿佛比任何时候都离自己更近——「野旷天低树，江清月近人」。\n这两句妙极了：天地那么大，却只有一个旅人和一轮月亮作伴，月亮成了诗人唯一的朋友。一个小小的「近」字，把旅途的孤单写得又静又美。这首诗后来成了写羁旅乡愁的千古名篇，清代诗人评它「情景相生，句句如画」。"},
  "望洞庭湖赠张丞相":{story:"唐玄宗开元二十一年（公元733年），孟浩然西游长安，渴望出仕却无人引荐。当时张九龄任丞相，德高望重，又乐于提携后进。孟浩然便借游览洞庭湖的机会，写下这首诗赠给张丞相，委婉地表达求荐的心意，这类诗在古代叫作「干谒诗」。\n诗的前四句写洞庭湖的壮观：「气蒸云梦泽，波撼岳阳城」，湖上水气蒸腾，弥漫在云梦大泽之间；波涛汹涌，仿佛要把岳阳城都摇动。据说这两句气势太大，后来的人写洞庭湖，都很难越过它。\n后四句转入比兴：「欲济无舟楫，端居耻圣明」，意思是想过湖却没有船和桨，想在圣明的时代闲居不出，心里又觉得惭愧——其实是以「想渡湖没船」来比喻自己想为国效力却没有人引荐。最后一句「坐观垂钓者，徒有羡鱼情」，用了《汉书》里「临渊羡鱼，不如退而结网」的典故，含蓄地说：我看别人做官，只能白白羡慕呀。全诗把求人的话说得既漂亮又有分寸，被誉为干谒诗的典范。"},
  "岁暮归南山":{story:"唐玄宗开元十六年（公元728年），孟浩然到长安参加科举考试，结果落了榜。相传他在王维的官署里做客时，恰逢唐玄宗突然驾到，他吓得躲到床底下，被皇帝叫出来，让他献诗，他脱口吟出「不才明主弃，多病故人疏」，意思是：我没有才干，所以被圣明的君主抛弃；身体多病，连老朋友也渐渐疏远。玄宗听了不悦，说：「是你自己不来求官，怎么倒说是我抛弃你？」从此断了他的仕途之路（此为一说）。\n这一年的岁末，他心情低落地收拾行囊，回到襄阳城南的岘山（南山）隐居。北阙的宫殿再也无心去拜谒，南山破旧的家门又迎来了归人。白发越来越多，催得人一天天老去；新春还没到，年华却已渐渐消逝。「永怀愁不寐，松月夜窗虚」，满怀的愁绪让他整夜难眠，只有松间的月光，空空地照在窗前。\n这首诗把落第文人的委屈、自嘲和无奈写得又深又含蓄。那两句触怒皇帝的诗，偏偏成了传诵最广的名句，让人哭笑不得——可见好诗和好运气，有时候并不一起来。"},
  "留别王维":{story:"科举落第之后，孟浩然在长安又徘徊了一段时间，求仕的希望渐渐破灭，终于决定离开京城，回到襄阳隐居。临走前，他给好友王维写下这首留别诗。王维当时已是朝中的官员，才情名动长安，是孟浩然在最失意的时候难得的知音。\n诗里说：「寂寂竟何待，朝朝空自归。」待在长安还能等什么呢？天天满怀希望出门，又天天空手而归。他又自嘲：想找权贵们援引推荐，可谁肯给我一点帮助？知音本来就是世上最稀少的人啊——「当路谁相假，知音世所稀」。这既是诉苦，也是对世态炎凉的清醒认识。\n结尾他安慰朋友也安慰自己：「只应守寂寞，还掩故园扉。」既然无人赏识，不如守住寂寞，回去关上故乡的柴门。语气平静，心里却是千万般不舍。孟浩然后来真的终生布衣，成了盛唐最有名的「布衣诗人」，王维则一直惦念着他。两个大诗人惺惺相惜的这段友谊，也成为文学史上的一段佳话。"},
  "登鹳雀楼":{story:"王之涣是盛唐有名的边塞诗人，性格豪爽，常仗剑远游。相传他在唐玄宗开元年间路过蒲州（今山西永济）时，登上黄河边的鹳雀楼。这座楼因为常有鹳雀（一种水鸟）栖息而得名，登楼远望，前面是中条山连绵起伏，低头就能俯瞰奔腾的黄河水，气势十分雄壮。\n诗人先写眼前的景色：「白日依山尽，黄河入海流。」太阳靠着远山慢慢落下去，黄河翻滚着流向大海。十个字，把天、山、河、海全装进了诗里，画面有远有近，有静有动。接着，他忽然把笔锋一转：「欲穷千里目，更上一层楼。」如果想把千里风光都看尽，就再登上一层楼吧！\n后两句看似只是说登楼的窍门，其实讲出了一个深刻的道理：站得越高，看得越远。想要有更大的眼界和本领，就要不断努力向上。一千多年来，这两句诗被无数读书人当作座右铭，用来勉励自己和别人。鹳雀楼后来毁于战火，二十世纪末重建时，人们首先想到的，依然是王之涣留下的这两句诗。"},
  "凉州词":{story:"相传唐玄宗开元年间，王之涣曾长期在西北边地漫游，到过玉门关一带，亲身感受过戍边将士的生活。凉州在今甘肃武威，是通往西域的门户。当地春风难以吹到，杨柳稀少，守边的士兵想家时，便吹起羌笛，折柳寄情，于是有了这首《凉州词》：「黄河远上白云间，一片孤城万仞山。羌笛何须怨杨柳，春风不度玉门关。」\n关于这首诗，还有一个著名的「旗亭画壁」故事：王之涣和王昌龄、高适是朋友，一天三人在长安的酒楼（旗亭）喝酒，恰好来了一群歌女唱歌。他们约定，看歌女唱谁的诗多，谁就最厉害。结果前几位歌女唱的都是王昌龄和高适的诗，王之涣一个也没有。他不服气地说：最美的那位姑娘一定唱我的诗！果然，压轴的歌女开口便唱「黄河远上白云间」。王之涣得意极了，在墙壁上画痕记数，三人哈哈大笑，尽醉而散。\n这首诗明写边关的苍凉，暗藏对戍卒的同情，被誉为「唐音」的代表。传说旗亭中的那位歌女所唱，正是此篇，足见它当年传唱之广。"},
  "咏柳":{story:"贺知章是武则天时期的状元，一生仕途顺利，性情豁达，爱喝酒，爱说笑，是唐代最长寿的诗人之一。唐玄宗天宝三载（公元744年），他年逾八十，才思却依然敏捷。这一年他决定辞去官职，回浙江绍兴老家安度晚年。相传归乡的路上正是早春二月，他看见堤岸边的柳树抽出了嫩绿的新芽，千万条柳枝在风中轻轻摇摆，心里欢喜，便写下这首《咏柳》。\n他把柳树比作一位精心打扮的美人：高高的柳树像用碧玉装扮而成，千万条柳枝垂下来，好像她身上垂下的绿色丝织裙带——「碧玉妆成一树高，万条垂下绿丝绦」。接着他好奇地问：这些细细的柳叶，是谁的巧手裁剪出来的呢？答案妙极了：原来是二月里的春风，它就像一把灵巧的剪刀——「不知细叶谁裁出，二月春风似剪刀」。\n把看不见、摸不着的春风，比作一把神奇的剪刀，这是贺知章了不起的发明。这个比喻新鲜、俏皮又贴切，从此「春风似剪刀」成了咏春最有名的句子。八旬老人还能写出这样童心盎然的诗，难怪大家都喜欢他。"},
  "回乡偶书":{story:"贺知章离乡去长安做官，一晃就是五十多年。唐玄宗天宝三载（公元744年），八十六岁的他终于告老还乡，回到绍兴。离家时他还是风华正茂的青年，回来时却已白发苍苍。走在故乡熟悉又陌生的小路上，听着耳边没有改掉的乡音，看着镜中稀疏的鬓发，心里又酸又暖，于是写下这首《回乡偶书》。\n「少小离家老大回，乡音无改鬓毛衰」，乡音还是儿时的腔调，人却已经老得不成样子了。就在这时，一群村里的孩子围了上来，睁着好奇的眼睛打量这位白发老人，笑着问：客人您是从哪里来的呀？——「儿童相见不相识，笑问客从何处来」。\n这句「笑问」是全诗最动人、也最让诗人哭笑不得的地方：在孩子们眼里，这个满口乡音的老爷爷，竟是个外来的「客人」。一声天真的询问，写出了岁月的无情，也写出了故乡的亲切。这首诗没有一个难字，却惹得千百年来的游子一读就眼眶发热，因为它写出了所有离家太久的人，心底那份又甜又涩的滋味。"},
  "出塞":{story:"王昌龄年轻时曾仗剑漫游西北边塞，亲身走过玉门关、阳关一带，见过大漠、孤城和戍边的将士，所以他的边塞诗写得格外真切。这首《出塞》被誉为「七绝第一」，是他早年边塞生活的结晶：「秦时明月汉时关，万里长征人未还。」明月还是秦汉时的明月，关塞还是秦汉时的关塞，可一代代出征的将士，有多少人再也没能回家。\n后两句写道：「但使龙城飞将在，不教胡马度阴山。」只要像「飞将军」李广那样的名将还在，就绝不让匈奴的战马越过阴山！「龙城飞将」指西汉名将李广，他驻守右北平多年，匈奴人又敬又怕，几年都不敢来犯；他箭术高超，据说曾把石头射穿，却始终没有封侯。「阴山」在今内蒙古，是汉代中原抵挡匈奴的天然屏障。\n王昌龄感叹当时缺少像李广这样爱兵善战的良将。全诗悲壮而不消沉，成为盛唐边塞诗的压卷之作。因为王昌龄的七言绝句写得又多又好，后人送他一个响亮的称号——「七绝圣手」。这首《出塞》正是他「圣手」功力的最好证明。"},
  "芙蓉楼送辛渐":{story:"王昌龄中进士后，曾长期担任江宁（今南京）县丞，官不大，才干和诗名却很大。后来他调往洛阳，好友辛渐正好也要北上洛阳，二人同行到润州（今江苏镇江），在临水的芙蓉楼摆酒告别。面对滔滔江水，想到自己这些年屡遭贬谪、被人谗毁的遭遇，王昌龄写下这首送别诗，把要说的心里话，都托付给即将远行的好友。\n「寒雨连江夜入吴，平明送客楚山孤。」昨夜冷雨洒满江面，清晨送走了友人，只留下孤零零的楚山陪着自己。后两句是全诗的精华：「洛阳亲友如相问，一片冰心在玉壶。」请告诉洛阳的亲友们，我的心还是像玉壶里那一片纯净的冰心，绝没有因为贬谪和诽谤而改变。\n「冰心玉壶」的意象并非王昌龄首创，南朝诗人鲍照就曾写过「直如朱丝绳，清如玉壶冰」，用玉壶里的冰来比喻人品的清白坚贞。王昌龄借来这个意象，既回应了外界对他的中伤，也表达了对朋友最郑重的自白。「一片冰心在玉壶」从此成为表明高洁心志的千古名句，今天我们称赞一个人清白正直，仍常引用它。"},
  "从军行":{story:"《从军行》本是汉代乐府的旧题，专门用来歌唱军旅生活。王昌龄一共写了七首《从军行》，这是其中第四首，也是最有名的一首：「青海长云暗雪山，孤城遥望玉门关。」青海湖上空的浓云连着雪山，一座孤城远远望着玉门关——只开头两句，就把西北边塞辽阔而苍凉的风光推到读者眼前。\n「黄沙百战穿金甲，不破楼兰终不还。」将士们在茫茫黄沙中身经百战，连坚硬的铠甲都被磨穿了，可大家立下誓言：不打败敌人，绝不回家！「楼兰」是汉代西域的一个小国，国王反复无常，曾杀汉朝使者。西汉的勇士傅介子只带着少数随从出使西域，用计在宴席上斩杀了楼兰王，震慑西域，立下奇功。这里用「破楼兰」代指平定边患、建功立业。\n前两句写战争的艰苦，后两句写将士的决心，苦与勇对照，悲壮而昂扬。这首诗把盛唐军人保家卫国的豪情写得滚烫，至今仍被许多人当作激励自己迎难而上的座右铭。"},
  "闺怨":{story:"王昌龄写闺情诗也是一绝，这首《闺怨》就是其中代表。「闺」是古代女子的住处，「闺怨」写的就是闺中女子的愁怨。诗里讲的是一位年轻媳妇的故事：她住在妆楼之上，平日精心的梳妆打扮，无忧无虑，这天春日正好，她兴致勃勃地登上翠楼去赏春，心情原本轻松愉快。\n可就在登楼的一刹那，她忽然望见大路尽头（陌头）的杨柳，已经一片新绿。杨柳又绿，说明春光正好，也提醒她：离别的人离家，又是一年了。望着望着，她心里猛然一酸，后悔起来：早知道别离这样难熬，当初真不该让丈夫离开家，去边塞求取功名啊！「忽见陌头杨柳色，悔教夫婿觅封侯。」\n全诗没有直接写她如何思念，只抓住一个登楼的瞬间、一次意外的「忽见」，让满心欢喜突然转为深深的懊悔。这种由喜到怨的急转弯，细腻又真实，像一幕无声的小电影。王昌龄人称「七绝圣手」，连这样温柔的题材，也被他写得层层递进、余味悠长，难怪后世说他的绝句「深情幽怨，意旨微茫」。"},
  "别董大":{story:"唐玄宗天宝六载（公元747年），四十四岁的高适还在人生低谷里打转：科举不中，做小吏也不得意，长期漫游各地，布衣困顿。这一年，他在睢阳（今河南商丘）一带，遇见了老朋友董庭兰。董庭兰是当时最有名的琴师，排行老大，所以人称「董大」，他的七弦琴弹得出神入化，连宰相房琯都成了他的知音。可此时董大也正要离开，继续漂泊的生涯。两位不得志的朋友久别重逢又即将分手，高适写下了这首豪气干云的送别诗。\n「千里黄云白日曛，北风吹雁雪纷纷。」黄沙漫天，日色昏黄，北风吹着大雁，大雪纷纷扬扬——送别时的天气阴沉又寒冷，正像两人的处境。按常情，这样的离别该写得很伤感，可高适偏不。「莫愁前路无知己，天下谁人不识君？」他笑着对朋友说：别担心前方的路上没有知己，天下谁不认识您董先生呢！\n这话说得多么痛快、多么提气！在别人都落魄的时候，给朋友最坚定的信任和鼓励，这正是高适的胸襟。这首诗把送别诗写出了盛唐气象，千百年后人们送别友人，最爱引用的仍是这两句。"},
  "白雪歌送武判官归京":{story:"唐玄宗天宝十三载（公元754年），岑参第二次出塞，任安西北庭节度使封常清的判官，常驻轮台（今新疆轮台一带）军中。这里八月就飞雪，军营生活艰苦却充满新鲜感，岑参把满腔惊奇都写进了诗里。这一年冬天，同僚武判官奉命回京述职，岑参在轮台的营帐外摆酒相送，写下这首奇丽豪迈的送别诗。\n「北风卷地白草折，胡天八月即飞雪。」北风卷地而来，连坚韧的白草都被吹折，塞北的天空八月就飘起了大雪。最惊艳的是这两句：「忽如一夜春风来，千树万树梨花开。」早晨推门一看，大雪落满枝头，仿佛春风一夜之间吹开了千树万树的梨花！用春天盛开的梨花来比喻冬天的雪，新奇、明亮又温暖，让最严酷的雪景一下子有了生机。\n结尾写送别：武判官的身影在山回路转中消失，雪地上只留下一串马蹄印——「山回路转不见君，雪上空留马行处」。无限深情都留在这空荡荡的画面里。这首诗雄奇浪漫，是边塞诗的巅峰之作，「千树万树梨花开」从此成为人们咏雪时最先想到的句子。"},
  "逢入京使":{story:"唐玄宗天宝八载（公元749年），三十四岁的岑参第一次踏上西出边塞的漫漫长路，要到安西（今新疆库车一带）担任节度使高仙芝幕府的官职。古代去西域要走几个月，一路上大漠戈壁，风沙扑面，行旅艰难。这天，岑参骑着马在通往安西的路上赶路，迎面忽然来了一位回京城办事的使者，正是「入京使」。\n远赴绝域的游子遇见从家乡方向来的人，惊喜交加。岑参本想请他给家里捎一封书信，可仓促之间，马鞍上连纸笔都找不到。情急之下，他只好拉住使者，请他给自己远在长安的亲人捎一句口信：「马上相逢无纸笔，凭君传语报平安。」咱们就在马背上相逢了，没有纸和笔，只好托您带句话：一切都好，请家里放心。\n「报平安」三个字，是全诗最朴实也最揪心的地方。明明风餐露宿、前途茫茫，他只挑最要紧的平安二字报给家中老母。没有修饰，没有夸张，一个真实的生活瞬间，却写尽了游子对父母深深的爱与牵挂。这首小诗语言朴素得像大白话，却情深意长，千百年来打动了无数在外漂泊的人。"},
"秋词":{story:"公元805年，刘禹锡参与了王叔文领导的永贞革新，想革除朝廷弊病，结果改革失败，他被贬到偏远的朗州当司马。那年他才三十多岁，正是施展抱负的年纪，却要在荒凉之地度过漫长的岁月。\n秋天来了，古代文人一到秋天就唉声叹气，觉得草木凋零、人生凄凉，所以诗文里总是悲秋。刘禹锡偏不这样想，他在朗州举起笔，写下了一组与众不同的秋词：自古逢秋悲寂寥，我言秋日胜春朝。他说，自古以来人们都悲叹秋天的冷清，我却要说秋天比春天还要美好！\n诗人抬头看天，万里晴空里一只白鹤冲破云层，直上云霄，便借鹤明志：晴空一鹤排云上，便引诗情到碧霄。这只奋飞的鹤，正是诗人自己——虽然身在逆境，依然斗志昂扬，把诗情也带上了蓝天。\n这首豪气冲天的秋词，从此成了咏秋诗的千古绝唱。后来多少人一到秋天就想起它，它告诉我们：决定心情的不是季节，而是心里有没有阳光。"},
  "乌衣巷":{story:"宝历年间，刘禹锡担任和州刺史，路过六朝古都金陵，也就是今天的南京。他漫步到秦淮河边的朱雀桥，只见桥边野草从生了无人迹，夕阳斜斜地照着乌衣巷口，昔日的繁华荡然无存，忍不住提笔写下了这首怀古名作。\n乌衣巷为什么叫这个名字？相传因为三国时这里是吴国守卫石头城的军营，士兵都穿乌衣，所以得名。到了东晋，这条小巷更是不得了，成了两大顶级望族的居住地：丞相王导和名将谢安的家都安在这里。王导辅佐晋元帝建立东晋，谢安指挥淝水之战以少胜多，王家子弟里还有大书法家王羲之，真可谓人才辈出，钟鸣鼎食。\n可是再显赫的家族也有衰落的一天。几百年过去，东晋早已灭亡，昔日高门大户的豪宅如今野草遍地。诗人感叹道：旧时王谢堂前燕，飞入寻常百姓家。从前在王谢两大家族堂前筑巢的燕子，如今飞进了普通老百姓家。燕子还是那些燕子，主人却早已换了人间。\n这两句诗用一个小小的燕子，写出了历史变迁的沧桑，画面感极强又意味深长，成为怀古诗中流传最广的名句之一。后人常用它来感叹富贵无常、世事变迁。"},
  "竹枝词":{story:"唐穆宗年间，刘禹锡出任夔州刺史。夔州在今天的重庆奉节，那里山高水急，两岸百姓爱唱一种民歌，叫竹枝词，歌声嘹亮，充满乡土气息。诗人一向喜爱民间歌谣，便虚心向百姓学习，把巴渝民歌的风味写进了自己的诗里。\n夔州一带的青年男女，常常对着江水唱歌传情。这首诗写的正是一位姑娘的心事：江边杨柳青青，江水平静如镜，忽然传来小伙子熟悉的歌声。东边出着太阳，西边却下着雨，你说它到底是有情还是无情呢？\n原来道是无晴却有晴是一句绝妙的双关语。晴和情读音相同，表面说天气时晴时雨，实际是在说小伙子的心意时有时无、似无情却有情。姑娘听到歌声，心里又欢喜又疑惑，那捉摸不定的感觉，被这两句诗写得活灵活现。\n这种谐音双关的写法，刘禹锡是从民歌里学来的，让诗歌变得清新活泼、含蓄有趣。这两句诗千百年来被广泛传唱，至今仍是形容人心思婉转、情意朦胧的绝妙佳句。"},
  "酬乐天扬州初逢席上见赠":{story:"公元826年，刘禹锡罢去和州刺史之职，返回洛阳。在扬州，他与阔别多年的老友白居易意外相逢。白居易设宴为他接风，还赠诗为他抱不平，说自己也为刘禹锡被贬二十三年而难过。刘禹锡感慨万千，当场写下这首诗回赠，题目里的酬，就是答谢的意思。\n诗的开头连用两个典故，道尽了自己半生的辛酸。怀旧空吟闻笛赋，说的是西晋的向秀经过好友嵇康的旧居，听见有人吹笛，想起嵇康已被杀害，便写下怀念故人的文章。刘禹锡借此怀念那些被贬中逝去的旧友。到乡翻似烂柯人，讲的是晋人王质上山砍柴，看两个童子下棋入了迷，等棋局终了，斧柄已经腐烂，回到家乡，同代人都已不在。诗人说自己离开京城二十三年，重返时恍如隔世。\n面对这坎坷命运，刘禹锡没有消沉，反而喊出千古名句：沉舟侧畔千帆过，病树前头万木春。沉船旁边仍有千万只船竞发，枯树前面已是万木争春！他以沉舟、病树自比，却看到了千帆竞渡、万木争荣的新气象，把个人的不幸升华为对未来的信心。\n白居易读罢，感叹自己的诗不如刘禹锡的气魄。这两句诗因为充满乐观向上的哲理，至今仍常被引用来鼓励身处逆境的人们：旧的总会过去，新的正在到来。"},
  "望洞庭":{story:"相传唐穆宗长庆年间，刘禹锡担任和州刺史时，月夜遥望长江中下游的洞庭湖，写下了这首清丽的小诗。那时他虽仍在贬谪之中，却已渐渐适应了地方官的生活，常寄情山水，用明澈的眼睛去发现大自然的美。\n秋夜，月光如水洒在湖面上，湖光和秋月交相辉映，平静得像没有风的潭水。远远望去，月光下的洞庭湖和苍翠的君山浑然一体，朦朦胧胧，像一件精美的翠色艺术品。君山是洞庭湖中的一座小岛，相传舜帝的两个妃子娥皇、女英曾在这里泪洒斑竹，留下动人的传说。\n诗人越看越觉得奇妙，忽然想起一个绝妙的比喻：遥望洞庭山水翠，白银盘里一青螺。那平静的洞庭湖不就像一只白银做成的盘子吗？湖中的君山，不就是盘子里趴着的一颗青翠的小田螺？\n把八百里洞庭想象成白银盘，把小岛想象成青螺，这个比喻大胆又贴切，画面干净明亮，令人过目不忘。这首诗因此成为描写洞庭湖最传神的名篇，后人吟诵洞庭，总绕不开这一句白银盘里一青螺。"},
  "江雪":{story:"公元805年，刘禹锡、柳宗元等有志之士跟随王叔文发动永贞革新，想打击宦官和藩镇势力，挽回唐朝的颓势。谁知改革只进行了一百多天就失败，皇帝被宦官逼迫让位，改革派全部获罪。柳宗元被贬为永州司马，这就是历史上著名的二王八司马事件，八司马里就包括柳宗元和刘禹锡。\n永州在今天的湖南，当时是荒僻之地。柳宗元在这里一住就是十年，名义上是官，实际上受到监视，没有实权。政治上的巨大打击、母亲病逝的打击，让这位出身名门、才华横溢的诗人寄情山水，在永州的山水中寻找安慰，写下了著名的永州八记，也写下了这首江雪。\n请看这幅画面：千山鸟飞绝，万径人踪灭，所有的山上没有一只飞鸟，所有的路上不见一个人影，天地间白茫茫、静悄悄。忽然，江心出现一叶小舟，一位披着蓑衣、戴着斗笠的老翁，独自在大雪覆盖的寒江上钓鱼。孤舟蓑笠翁，独钓寒江雪。\n这位不怕寒冷、不怕孤独的老渔翁，正是柳宗元自己的写照——处境再险恶，他也不向黑暗势力低头。这首诗像一幅极简的冰雪画，冷峻而孤高，千百年来打动着无数身处逆境却依然坚守的人。"},
  "渔翁":{story:"柳宗元被贬永州后，常常徜徉在潇水与湘水之间。这里的渔民日出而作、日落而息，生活简单而自在，让苦闷中的诗人十分向往，于是写下这首渔翁，有人说它是柳宗元山水诗中最美的一首。\n夜幕降临，渔翁把船停靠在西山旁边歇宿。天没亮，他就起身，汲取清澈的湘江水，点燃楚地的竹子烧火做饭。你看这个渔翁，傍着山睡觉，就着水烧饭，吃的东西都是现取的，多么逍遥自在，多么贴近大自然！\n清晨，云雾散去，太阳升起，江面上却不见了渔翁的身影。忽然一声欸乃——那是摇橹或划船的声音，从山水深处传来，回头看时，满江满山的绿意扑面而来：烟销日出不见人，欸乃一声山水绿。那一声桨响，仿佛唤醒了整片青山绿水。\n绿字用得极妙，它既是颜色，又像是声音把绿色铺展开来的动态过程，被后人誉为神来之笔。这首诗写出了渔翁与山水融为一体的自在生活，其实寄托着诗人被贬之后对自由生活的深深向往。后世画家、音乐家常以此为题材，让渔翁与青山绿水永远定格在中国艺术里。"},
  "早春呈水部张十八员外":{story:"韩愈写这首诗时大约五十岁，正担任吏部侍郎，负责官员的任免考核。春天来了，长安城里下起了一场细细的小雨，热爱生活的韩愈心情大好，想约老朋友一起出门赏春。这位老朋友就是时任水部员外郎的张籍，他在家中排行第十八，所以题目里亲切地称他张十八员外。\n小雨像酥油一样滋润，韩愈在城中心的小道上漫步，远远看去，草色连成一片淡淡的绿；走近细看，却稀稀疏疏，还没有铺满地面。这若有若无的草色，正是早春独有的、最惹人怜爱的地方。\n正因为这份娇嫩，韩愈才认为早春是一年中最好的时节，他兴奋地对张籍说：最是一年春好处，绝胜烟柳满皇都。意思是早春这若有若无的草色，远比暮春时节烟柳浓绿、满城满眼的景象要美得多。\n韩愈用一双慧眼捕捉到了早春最细微的美，把寻常草色写得珍贵无比。这首诗清新自然又充满生活情趣，天街小雨润如酥一句尤其广为传诵，后世描写早春，很难绕开韩愈这句细腻传神的诗。"},
  "春雪":{story:"元和十年的正月，长安城里家家户户还沉浸在新年的热闹里，韩愈抬头四望，却见草木还没有发芽，看不到一点春天的芳华。冬天赖着不肯走，诗人等得心焦，不由得盼望春天快点到来。\n转眼到了二月，一场春雪悄然而至。韩愈惊喜地发现，被雪覆盖的地面上，竟然钻出了嫩嫩的小草芽！熬过漫长寒冬的小草，终于顶开泥土，向人们报告春天来了。\n诗人望着漫天飞舞的雪花，忽然生出一个可爱的想象：白雪却嫌春色晚，故穿庭树作飞花。这白雪好像也在嫌弃春色来得太迟，故意穿过庭院里的树木，化作片片飞花，热热闹闹地装点春天。\n把白雪当作会着急、会打扮的孩子来写，这就是拟人的手法。全诗没有一句直接说盼望春天，却把盼春的心情写得俏皮又真切。这两句诗构思新奇、充满童趣，成为咏雪诗中的名篇，历代诗人咏雪都爱拿它作榜样。"},
  "左迁至蓝关示侄孙湘":{story:"元和十四年，唐宪宗要从法门寺迎请佛骨到皇宫供奉，王公大臣们争相施舍，百姓更是狂热，有人甚至烧顶烧臂来表示虔诚。韩愈一向耿直，上表进谏，写下著名的论佛骨表，劝皇帝不要把佛骨迎进宫中，说佛骨不过是一块枯骨。宪宗皇帝勃然大怒，差点处死韩愈，经人求情，才改判贬为潮州刺史，即刻动身，这就是左迁，即被贬官。\n韩愈此时已年过半百，匆忙上路，仓促间连妻儿都来不及带走，只带着一个侄孙韩湘——相传就是八仙之一韩湘子的原型。走到蓝田关时，大雪纷飞，前路被积雪堵得严严实实，马儿也踟蹰不前。诗人回望来路，感慨万千：云横秦岭家何在，雪拥蓝关马不前。云气横亘在秦岭上，家乡在哪里？大雪拥塞蓝关，连马都不肯前行。\n尽管如此，韩愈没有后悔。他一字一句写下心声：欲为圣明除弊事，肯将衰朽惜残年。我想为圣明的君主革除弊病，怎肯吝惜自己这把老骨头、顾惜残余的年岁！明知进谏会招来灾祸，他仍然义无反顾。\n这首诗把忠而被贬的悲愤、对家人的牵挂与至死不悔的气节熔于一炉，沉郁顿挫，感人至深。云横秦岭、雪拥蓝关两句画面雄浑苍凉，成为描写贬谪路上风雪景象的千古名句，也永远记录了一位老臣刚直不阿的脊梁。"},
  "旅夜书怀":{story:"765年，杜甫已经在成都浣花溪边的草堂里住了五六年。这一年，一直接济、庇护他的朋友、剑南节度使严武忽然去世，杜甫顿时失去了依靠，只好带着全家老小乘船离开成都，顺江东下渝州。深秋的一个夜晚，小船停泊在辽阔的江面上，四野无人，只有星光月影与诗人作伴。\n细草微风岸，危樯独夜舟——江岸的小草在微风里轻轻摇摆，高高的桅杆下，诗人独自夜宿在孤零零的小船上。镜头忽然拉开：星垂平野阔，月涌大江流。星星低垂，好像垂到了无边无际的平原上；月亮随着大江的波浪一起涌动，好像在大江里翻腾。天地如此壮阔，人却渺小得像一粒尘埃。\n于是诗人发出长长的叹息：名岂文章著，官应老病休——我的名声难道真是因为文章才传开的吗？做官也做到老病该退休的时候了。飘飘何所似，天地一沙鸥——我这飘泊不定的一生像什么呢？不过就是天地间一只孤零零的沙鸥罢了。一联写尽江夜壮景，一联写尽身世悲凉，雄浑的画面与孤独的心形成强烈对照，读来让人鼻酸。"},
  "八阵图":{story:"766年，杜甫客居夔州（今重庆奉节）。夔州江边有一处奇特的石堆，相传是三国时诸葛亮在这里布下的「八阵图」：几十堆石头按八卦的方位排列，像一座神秘的石阵。江水日夜冲刷拍打，石头堆却纹丝不动，让来往的行人都啧啧称奇。\n杜甫望着石阵，想起诸葛亮的一生：他辅佐刘备建立蜀汉，三分天下，六出祁山，鞠躬尽瘁，死而后已。可是英雄也有遗憾。诗里说的遗恨失吞吴，指的是刘备为了给关羽报仇，不听诸葛亮劝阻，执意讨伐东吴，结果在夷陵之战中被火烧连营，大败而归。\n杜甫认为，诸葛亮的遗恨就在于此：蜀汉的精锐一战损失殆尽，统一天下的大业从此断送，复兴汉室成了不可能的梦。短短二十个字：功盖三分国，名成八阵图。江流石不转，遗恨失吞吴。前两句赞颂功业，后两句借江水冲不动的石阵，写出英雄心中永远无法磨灭的遗憾。一个「转」字，写尽江水奔流、遗恨长存，让沉默的石堆有了生命，也让后人每次站在江边，都忍不住为诸葛亮长叹一声。"},
  "前出塞九首·其六":{story:"唐玄宗天宝年间，大将哥舒翰屡次远征吐蕃，大军开拔，百姓抽丁，国库耗空，举国疲弊。约751年，杜甫借一位普通士兵的口吻，写下《前出塞九首》，其中第六首最有名：挽弓当挽强，用箭当用长。射人先射马，擒贼先擒王。\n诗里的主人公是个边疆老兵，他把半生打仗的经验用大白话讲出来：拉弓要拉最硬的弓，射箭要用最长的箭；打仗要先射倒敌人的战马，马一倒，骑兵就摔下来了；杀敌要先擒住敌人的首领，首领一垮，敌军自己就溃散了。\n老兵接着说：杀人亦有限，列国自有疆。打仗杀人要有个限度，每个国家本来就有自己的疆界，不能一味贪多求胜。这里藏着杜甫的深意：他表面上是在教士兵打仗，实际上是讽刺唐玄宗好大喜功、穷兵黩武，不顾士兵和百姓的生死。射人先射马，擒贼先擒王后来成了家喻户晓的谚语，意思也是做事要抓住关键，一下子制服要害。"},
  "绝句二首":{story:"759年到764年，杜甫为了躲避安史之乱，带着全家辗转多地，尝尽了颠沛流离的苦。763年，安史之乱终于平息；764年，杜甫几经周折回到成都，重新修葺了那间被风吹破的草堂。春天来了，浣花溪边又是一片生机，杜甫高兴极了，提笔写下《绝句二首》。\n第一首写道：迟日江山丽，春风花草香。泥融飞燕子，沙暖睡鸳鸯。迟日就是春天的太阳，阳光洒遍山河，处处明丽动人；春风轻轻吹过，送来花草的清香。泥土变得松软，小燕子飞来飞去忙着衔泥筑巢；沙滩被晒得暖暖的，成双成对的鸳鸯安安稳稳地睡在上面。\n这首诗像一幅色彩明快的春日图画：有太阳、有花草、有燕子、有鸳鸯，万物各得其所，安闲自在。这样的安宁，是经历了多年战乱之后诗人最珍惜的东西。孩子们读这首诗，要记住的是那份劫后重生的喜悦——和平的春光，比什么都宝贵。"},
  "茅屋为秋风所破歌":{story:"761年秋天，成都狂风大作。杜甫草堂屋顶上的茅草被一阵狂风卷走，飞过浣花溪去，有的挂在高高的树梢上，有的沉入水塘。他拄着拐杖，追得气喘吁吁，也没能捡回多少。这天夜里又下起大雨，屋顶到处漏雨，床铺都被淋湿了，一家人缩在湿漉漉的屋子里，坐着挨到天亮。\n诗人又冷又累，望着破旧的茅屋，本该先心疼自己。可杜甫偏偏不是普通人。他想到的不是自己一间茅屋，而是天下还有多少读书人，在风雨里连个遮身的地方都没有。于是他一拍床铺，喊出了千古名句：安得广厦千万间，大庇天下寒士俱欢颜，风雨不动安如山！\n他还说：呜呼！何时眼前突兀见此屋，吾庐独破受冻死亦足！——什么时候眼前能突然出现千万间温暖的大房子，哪怕只有我的茅屋破了、把我冻死，我也心甘情愿！从自己一间破茅屋，想到天下所有受苦的寒士，这份推己及人的博大胸怀，让杜甫赢得了「诗圣」的称号，也让这首诗成为中国人最熟悉、最感动的诗篇之一。"},
  "石壕吏":{story:"759年，唐朝九位节度使的军队在邺城（今河南安阳）围攻安史叛军，结果几十万唐军一战惨败。为了补充兵源，官府四处抓人，连老人、妇女也不肯放过。这一年，杜甫从洛阳返回华州，走到陕州石壕村时天黑了，就在一户人家投宿，半夜亲眼看见了惊心动魄的一幕。\n差役敲着门大喊抓丁。老翁吓得翻墙逃走，老妇人出去开门应付。差役凶神恶煞，非要从这家里抓走一个人不可。老妇人哭着诉说：三个儿子都去邺城当兵了，一个儿子刚捎信回来，说另外两个儿子已经战死。家里只剩一个还在吃奶的孙子，和连件完整衣服都没有的儿媳。可差役还是不肯走。\n老妇人擦干眼泪，挺身而出：老妇我虽然年老力衰，那就让我连夜跟你们去河阳服役吧，还能给士兵们做早饭。天亮了，差役抓走了老妇人，杜甫告别时，只剩下那个翻墙回来的老翁。存者且偷生，死者长已矣——活着的人只能苟且偷生，死去的人已经永远消逝。杜甫没有加一句评论，只是实录其事，却让这段历史永远刺痛人心，这就是诗史的力量。"},
  "兵车行":{story:"唐玄宗天宝年间，皇帝好大喜功，频频对南诏、吐蕃用兵，连年征兵，百姓苦不堪言。约751年，杜甫在长安城外亲眼目睹了征兵的一幕：车轮滚滚，战马嘶鸣，一队队新兵被押着开赴前线。送行的亲人扯着亲人的衣角，跺着脚嚎啕大哭，哭声直冲云霄。\n诗里写道：车辚辚，马萧萧，行人弓箭各在腰。耶娘妻子走相送，尘埃不见咸阳桥。牵衣顿足拦道哭，哭声直上干云霄。父母妻儿追赶着队伍送行，扬起的尘土遮住了咸阳桥。被征的人回头告诉亲人：刚到边关时里正给他们裹上头巾，转眼头发都白了，还在戍守，血流成海，活下来的有几人？\n诗的末尾，杜甫借百姓之口发出了血泪控诉：君不见青海头，古来白骨无人收。新鬼烦冤旧鬼哭，天阴雨湿声啾啾。边疆流过的血多得像海水，可皇帝开疆拓土的心思还没有停止（边庭流血成海水，武皇开边意未已）。这首《兵车行》是杜甫头一首站出来替老百姓说话的诗，开创了记录人间疾苦的写实传统，所以他被称为「诗史」。"},
  "丽人行":{story:"752年春天（一说753年），唐玄宗最宠爱的杨贵妃和她的兄弟姐妹到长安城南的曲江池畔游宴。曲江是皇家园林胜地，那一天杨氏一族前呼后拥，香车宝马，珠翠满头，锦衣耀眼，场面奢华到极点。杜甫正好看见这一幕，心里却翻江倒海，提笔写下讽刺诗《丽人行》。\n诗的开头不写人，先写景物：三月三日天气新，长安水边多丽人。上巳节那天，天气清新，曲江边上全是打扮艳丽的贵妇人。接着写她们的衣着首饰有多华美，写她们吃鱼切得多么细、多么讲究，连御厨的厨师都在一旁忙碌着传菜。句句看似夸赞，字字暗藏讽刺。\n诗的结尾笔锋一转：杨花雪落覆白苹，青鸟飞去衔红巾。杨花像雪一样飘落，盖住了水面的白苹。当时长安城里流传着歌谣，讥讽杨国忠和虢国夫人兄妹关系暧昧（一说暗指他们的丑事），杨花正是「杨」家的暗语。炙手可热势绝伦，慎莫近前丞相嗔！——杨家权势无人能比，可千万别靠近，丞相会生气的！全诗没有一个字骂人，却骂得入骨三分，是唐诗里讽刺艺术的名篇。"},
  "哀江头":{story:"756年，安史叛军攻破潼关、攻陷长安，唐玄宗仓皇逃往四川，长安城陷入一片混乱。杜甫本想追随皇帝，半路被叛军抓住，押回沦陷的长安。困在城中，有一天他悄悄走到城南的曲江池边——这里曾是皇家游宴的胜地，如今却宫殿千门紧锁，细柳新蒲无人欣赏，一片荒凉。\n杜甫想起从前：开元盛世时，唐玄宗和杨贵妃常常带着宫女乐队来游曲江，霓裳羽衣曲随风飘扬，杨贵妃明眸皓齿，艳绝人寰。可如今，明眸皓齿今何在？血污游魂归不得——美人早已惨死在马嵬坡，连魂魄都回不到旧日的宫殿。眼前嫩绿的柳枝，想起当年它刚发新芽时被折来簪在头上，仿佛还是昨天。\n诗人在曲江头看着流水，只能吞声痛哭，不敢放声，只怕引来叛军。他写下：少陵野老吞声哭，春日潜行曲江曲。江头宫殿锁千门，细柳新蒲为谁绿？这首《哀江头》把盛世与乱世的巨大反差写进了短短的诗行里，后人读它，就像看一场从繁华到崩塌的电影，令人掩卷长叹。"},
  "哀王孙":{story:"756年六月，安史叛军攻破潼关，唐玄宗连夜逃往四川，长安的皇室子孙来不及逃走，许多人被叛军抓去杀戮。杜甫被困在长安城里，有一天走在街上，看见一位王孙躲在断墙残垣后面，蓬头垢面，伤痕累累，还在躲避叛兵的搜捕。杜甫认出他是皇族子孙，心里又惊又痛。\n他拉住王孙的手，忍不住哭了起来。王孙告诉他：叛军正在到处搜杀皇室子孙，多少金枝玉叶都成了白骨。杜甫叮嘱他：千万要忍住，不要说出自己的真实身份，好死不如赖活着。诗里写道：朔方健儿好身手，昔何勇锐今何愚——当年身强力壮的朔方守军，怎么会溃败得这样愚蠢？这句话痛惜守军丢了潼关，葬送了长安。\n诗的结尾，杜甫劝这位王孙隐忍求生，熬过乱世，等到官军收复京城的那一天。这首《哀王孙》记录的不是传说，而是血淋淋的历史：曾经高高在上的王公贵族，在国破家亡时连活下去都要东躲西藏。杜甫把这份悲悯写进诗里，让千百年后的我们，仍能感受到安史之乱带给每一个人的灾难。"},
"终南别业":{story:"唐玄宗天宝三载（公元744年）前后，王维在终南山下的辋川买下宋之问的旧别墅，过上了半官半隐的生活。他名义上还是朝廷官员，却把大半日子交给了青山碧水。这首诗写的就是他独自出游的一个寻常日子。\n中年以后的王维倾心佛法，号「摩诘居士」。他顺着溪流随意地走，不问路，也不赶路，一直走到水的尽头，无路可走了，索性坐下来，看山间的云气慢慢升起。朋友问起他的行踪，他笑着说：回到山林深处去了。\n「行到水穷处，坐看云起时」之所以千古传诵，是因为它写出了人生最豁达的一种境界：走到绝境不必慌张，换一种心情，绝境处自有新的风景。这两句像一位禅师的开示，千百年来安慰了无数身处困境的人。"},
  "使至塞上":{story:"唐玄宗开元二十五年（公元737年），河西节度副大使崔希逸在青海西大败吐蕃。朝廷派王维以监察御史的身份，奉使前往凉州慰劳将士。这看起来是荣耀的差事，其实是宰相张九龄罢相后，王维受到排挤，被变相赶出京城。\n王维带着朝廷的车马一路向西北走去。边塞的风沙、荒凉的戈壁，都是他从未见过的景象。走到萧关附近，碰到了侦察的骑兵，告诉他都护正在燕然前线的方向。最让他震撼的是那一望无际的大漠：烽火台上一缕孤烟笔直升起，黄河尽头一轮落日又圆又大。\n「大漠孤烟直，长河落日圆」十个字，被后人誉为「千古壮观」。一个「直」字写出孤烟的劲拔，一个「圆」字写出落日的苍茫，简简单单，却把整个塞外风光收进了诗里。王国维称赞它是「千古壮观」的名句，边塞诗写到此处，气象已是雄浑无双。"},
  "渭川田家":{story:"开元年间（约公元721到726年），王维曾在终南山一带隐居。一个初夏的傍晚，他在渭水边的村落散步，看见了一幅温暖的乡村图景：夕阳照着村庄，牛羊从村外的巷口慢慢归来，拄着拐杖的老人惦记着放牧的孙儿。\n村里炊烟袅袅，野地的蚕儿已结成茧，农夫扛着锄头归来，一路上亲热地说着家常。好一派闲静安宁的田家生活！诗人看得入神，心里却泛起一阵羡慕：自己也想归隐田园，不禁怅然地吟起《诗经》里的「式微，式微，胡不归」——意思是天黑了，天黑了，为什么还不回家呢？\n全诗没有一句说教，只是白描田园的暮色，却把「归隐」的念头写得水到渠成。「式微」这个典故出自《诗经·邶风》，古人常用它来表达归隐之志。王维这首诗也因此成为田园诗的名篇，与陶渊明的田园诗一脉相承，又添了一层淡淡的怅惘。"},
  "青溪":{story:"隐居辋川期间，王维常在终南山中漫步。辋川有一条青溪，水流清澈，随山势千回百转。王维沿着溪流行走，看它在喧闹的乱石间跳过，在深色的松柏林里沉静地流淌，有时弯成安静的葫芦潭，有时又落进小小的荷叶池。\n相传这条溪上的桂花开得最香，却几乎没有外人愿意跋涉山路前来欣赏。山中的荇菜碧绿荇菜漂摇，山下的菜花金黄灿烂。溪水仿佛在幽深的山涧里自娱自乐，又像在安静中与人对话。王维看久了，忽然觉得这条溪正像自己的心。\n于是他写下了千古名句：「我心素已闲，清川澹如此。」意思是：我的心向来恬淡安闲，就像这清澈的溪水一样平静淡泊。王维晚年好佛，这一溪清水正是他禅心的写照。以水清比心清，物我交融，正是王维山水诗最动人的艺术特色。"},
  "老将行":{story:"开元年间（约公元721至737年），王维年轻时写下这首长篇古诗，替一位白发老将鸣不平。这位老将十五岁时就英勇无比，射杀过山中的猛虎，论功可以和北平太守李广相比；二十岁随军征战，一个人骑马直取吐蕃首领的人头。\n他立下的战功数也数不清：曾经率骑兵深入敌境，在青海一带俘虏过敌人，又用箭救过被困的将领。可年华渐老，他却被人遗忘，门前冷落，只能闲坐看柳树飘絮，卖尽宝剑换酒浇愁。王维愤愤不平地写道：「卫青不败由天幸，李广无功缘数奇。」卫青打胜仗靠的是上天保佑，李广一辈子不得封侯，只因命运不济！\n然而老将的报国之心并未熄灭。想当年耿恭被围疏勒城，拜井得水，天赐甘泉；老人发誓：要像耿恭一样，哪怕孤城被围，也要让泉水飞涌而出！只要朝廷一声令下，他还要提剑上阵。全诗用卫青、李广、耿恭三个典故，把老将的悲壮写得荡气回肠，至今读来仍令人动容。"},
  "桃源行":{story:"唐开元七年（公元719年），十九岁的王维还只是个风华正茂的少年，却做了一件大胆的事：把陶渊明六十多年前写下的散文《桃花源记》，改写成长篇叙事诗《桃源行》。\n他想象一位渔人驾着小船，顺着清溪，忽然遇到一片盛开的桃花林。穿过桃花林尽头的山洞，眼前豁然开朗：平坦宽广的土地上，房屋整齐，良田美池，鸡犬相闻，男耕女织，往来劳作，人人脸上都带着安然的神色。原来他们的祖先为躲避秦朝的战乱，带着妻儿躲进这深山，从此与世隔绝，不知外面已是汉朝，更不知魏、晋。\n渔人离开后想再寻桃源，却怎么也找不到路了。王维在诗末写道：「春来遍是桃花水，不辨仙源何处寻。」意思是春天来了，处处都是桃花映水，那桃花源究竟在哪里呢？这首少年之作想象瑰丽，把散文变成了流动的画，后来人称赞王维「诗中有画」，此篇已见端倪。桃源也成了中国人心中永远的理想乡。"},
  "陇西行":{story:"王维的《陇西行》沿用汉乐府旧题，写的是边塞军情紧急的一幕。陇西是古郡名，在今天甘肃一带，自古就是中原通往西域的门户，也是战火最多的地方之一。\n诗里描绘的场面扣人心弦：大雪纷纷扬扬，遮天蔽日，边防军营里警戒的梆子声敲个不停。忽然，一阵急促的马蹄声踏破风雪——前线都护的紧急军书送到了：匈奴的军队正包围酒泉！烽火接连燃起，把一座座高山照得通红，援兵连夜出发，准备杀向边城。\n全诗只有短短几句，却像一部紧张的电影：落雪、警柝、马蹄、烽火，一环扣一环。读者仿佛能听到风雪中的杀伐之声，感受到边关告急时将士们的勇猛与忠诚。王维一生没打过仗，却能写出这样气势逼人的边塞诗，正说明他想象力的惊人，也说明盛唐边塞诗的雄风早已深入人心。"},
  "少年行":{story:"王维的《少年行》一共四首，这是其中的第二首，写尽了长安少年的豪气。盛唐的长安城繁华开放，贵族少年们骑马佩剑，出入酒肆高楼，讲究意气相投，千金散尽也一笑置之。\n诗一开头就是一句豪语：「新丰美酒斗十千」。新丰是长安附近的名城，那里出产的美酒一斗值万钱，珍贵无比。这句诗其实化用了曹植《名都篇》里的「美酒斗十千」。王维信手拈来，便让豪奢之气扑面而来。少年们相逢意气相投，主人殷勤斟酒，座中都是豪迈的游侠之客。醉了就躺在酒楼里，哪怕楼前明月西沉、杨柳依依，也毫不在意。\n这首诗语言明快，色彩鲜明，短短几句就画出一群爽朗豪放的少年形象。「相逢意气为君饮，系马高楼垂柳边」成了写少年豪情的千古名句，后来无数写青春与友情的诗文，都在它的影响下展开。"},
  "观猎":{story:"开元九年（公元721年）前后，年轻的王维在京城长安附近游览，目睹了一场声势浩大的狩猎。猎场设在渭城一带，寒风劲吹，号角声从远处传来，将军带着随从，正在大泽之畔纵马围猎。\n枯草尽黄，狐狸兔子无处藏身；猎鹰的眼睛因为草低看得格外锐利，马蹄因为残雪消尽而格外轻快。转眼之间，将军在渭城以西射中了一只翱翔的大雕，卫士们骑马飞驰去替他捡回猎物。这一连串动作，王维只用了十个字：「草枯鹰眼疾，雪尽马蹄轻」。\n狩猎结束了，将军勒马回望，千里平野上暮云四合，安安静静，仿佛刚才的喧腾从未发生。结尾「回看射雕处，千里暮云平」，把动极而静写得余味悠长。传说北周的长孙晟一箭射穿双雕，称为「射雕手」，这里暗用其意。全诗节奏紧凑，像一张拉满的弓，被后人视为王维早期最精彩的边塞题材诗作之一。"},
  "汉江临眺":{story:"开元二十八年（公元740年，一说二十四年736年），王维南游襄阳。他登上城楼，凭栏远眺，只见汉江水浩浩荡荡，从他的眼前一直流向天地之外；远山若隐若现，在雾霭里似有似无，一半看得清，一半看不清。\n诗人看得心潮起伏，仿佛看见襄阳城邑漂浮在滔滔汉水之上，江面上白鸥的翅膀忽闪忽闪，渔夫的渔网在浦口收得满满的。天色向晚，水波映着悠悠的碧空，天空的色彩随着船帆渐渐远去而变幻。襄阳的好风光，足以供他这个山翁终日留恋醉饮。\n「江流天地外，山色有无中」被誉为咏汉江的千古名句。江水流到天地之外，山色在有无之间，十个字把水天相接、山色缥缈的画面写得如在眼前。后来南宋诗人陆游也写过「秋色连波，波上寒烟翠」式的名句，但论开阔空灵，人们总会想起王维这一联。此联气象宏大而意境悠远，正是盛唐诗的高处。"},
  "积雨辋川庄作":{story:"王维隐居辋川的岁月里，常常遇到连日的阴雨。这首诗写的就是一场久雨初晴的清晨。辋川庄在终南山脚下，是王维精心经营的别墅园林，稻田、菜圃、竹林环绕，宛如世外桃源。\n雨后的天空放晴，炊烟在树梢间袅袅升起。白鹭扑扇着翅膀，从水气蒙蒙的稻田上飞过；茂密的夏日林木深处，传来黄鹂一声声婉转的啼鸣。山里人正忙着在东边的田里插秧，烧过荒草的地方冒出轻烟；陪伴诗人住在宫里的，是刚采下的一树新鲜樱桃。槲叶落满山径，山路上传来砍柴人说话的声音。\n最妙的是结尾：「野老与人争席罢，海鸥何事更相疑。」《列子》里说，海边有人每天和海鸥玩耍，海鸥和他很亲近；后来他起了捉海鸥的念头，海鸥便再也不肯落下。列子也与众人争席而坐，不分彼此。王维说：我这个乡野老人早已与世无争，连海鸥也不用怀疑提防我啊。两个典故一并用出，把隐居的淡泊心境写得妙不可言，「漠漠水田飞白鹭，阴阴夏木啭黄鹂」更被历代画家誉为画里才有的好句子。"},
"卖炭翁":{story:"唐元和初年，约公元806到807年间，白居易正担任左拾遗，专门负责给皇帝提意见。那时长安城里有一种叫宫市的制度：皇宫缺了什么，宦官就打着皇家的旗号到集市上拿东西，名义上是采买，实际上几乎不给钱。白居易走街串巷，亲耳听到了卖炭老人的故事。\n诗里的老人整年在终南山里砍柴烧炭，满脸尘土，十指熏黑，腰间系着破围裙。最揪心的是两句矛盾的话：他身上穿着单薄的衣服，却希望天再冷一些。为什么呢？因为天冷炭才能卖个好价钱。孩子你看，这位爷爷冷得发抖，心里盼的却是更冷的天气，这该是多么无奈呀！\n结果两个宦官骑着马来，口称奉了皇上的命令，把老人一整车千余斤的炭牵走了，只丢下半匹红纱和一丈绫，系在牛头上就算付了炭钱。这两样东西远远抵不上炭的价钱。白居易用他的笔把这幅画面定格下来，让千年之后的人还能看见那位老人空空的手和牛头上飘着的红纱。这首诗就是著名的《新乐府》五十首之一，它像一篇新闻特写，替没有话语权的小人物发声，也成为中国诗歌史上揭露宫市黑暗最锋利的一篇。"},
  "长恨歌（节选）":{story:"公元806年，三十五岁的白居易正任盩厔县尉。一天，他和好友陈鸿、王质夫结伴游玩，来到马嵬坡附近的仙游寺。夕阳西下，古寺荒凉，他们坐在台阶上，谈起了四十多年前发生在这里的那件惊天动地的大事：唐玄宗和杨贵妃的爱情悲剧。\n唐玄宗年轻时英明有为，开创了开元盛世，可后来宠爱杨贵妃，渐渐不理朝政。安史之乱爆发后，他仓皇逃往蜀地，走到马嵬坡时，士兵哗变，唐玄宗被迫赐死心爱的杨贵妃。此后唐玄宗退位，晚年在孤寂中度过，据说还曾派人上天入地寻找杨妃的魂魄。白居易听着这段往事，感慨万千，提笔写下了这首长达八百多句的《长恨歌》。诗里故意用汉皇来代指唐明皇，为的是避人耳目。\n诗的前半部分写他们惊世的爱情与安史之乱的痛史，后半部分写唐玄宗刻骨铭心的思念。在天愿作比翼鸟，在地愿为连理枝——比翼鸟是传说中翅膀挨着翅膀才能飞的鸟，连理枝是两棵树枝干长在一起的树，这两句誓言写尽了生死不渝的深情。全诗一出立刻轰动长安，人人传诵，甚至有人用这首诗来换取歌女的演唱。直到今天，比翼鸟和连理枝仍是我们形容美满爱情最常用的词。"},
  "琵琶行（节选）":{story:"元和十一年秋天，公元816年，白居易在江州司马的任上已经待了两年。四年前他因为上书言事得罪权贵，被贬到这荒僻的江西小城，心里满是委屈。这天傍晚，他到浔阳江边为一位朋友送行，正在举杯时，忽然听见附近的船里传来一阵动听的琵琶声，那曲子是只有长安歌女才会弹的京都声调。\n白居易惊喜万分，把弹琵琶的人请到船上来。这是一位已经嫁作商人妇的女子，她年轻时曾是京城最有名头的歌伎，许多富贵子弟争着听她演奏。她怀抱琵琶，随手弹来，大弦嘈嘈如急雨，小弦切切如私语，弹得满座动容。弹罢她放下琵琶，讲起自己的身世：青春年华早已过去，如今嫁给商人，丈夫又重利轻别离，把她独自丢在空船上，夜里只能守着江水、明月，梦到自己年轻时在长安的欢笑。\n白居易听着听着，眼泪不知不觉流了下来。他想到自己本是京城朝官，只因敢说真话就被贬到这江州，住处的环境偏僻得一年到头听不到丝竹之声，和这位琵琶女的遭遇何其相似！于是他写下同是天涯沦落人，相逢何必曾相识这句千古名言，又写下江州司马青衫湿。这首诗不仅是唐诗中写音乐的名篇，更让江州司马这四个字从此成了怀才不遇的代名词。"},
  "观刈麦":{story:"公元806年前后，白居易在长安附近的周至县担任县尉，主管缉捕盗贼。麦收时节，他下乡巡视，亲眼目睹了农人们顶着毒日头收割麦子的情景，心里久久不能平静，回来便写下了这首《观刈麦》。\n五月里正是人倍忙的时候：男男女女都下了地，脚下蒸着滚烫的泥土热气，背上烤着毒辣辣的太阳光，人人筋疲力尽却顾不得歇一歇，只为抢收这一年的口粮。可就在田边，白居易还看到一位抱着孩子的贫妇，提着破篮子在捡拾别人落下的麦穗充饥。问她为什么这样，她说家里的田因缴不起税被官府收走了，只好靠拾穗活命。\n这景象深深刺痛了白居易。回到家他掩卷沉思，越想越惭愧：自己如今拿着俸禄，日子过得安稳，一年到头却从来没有种过田、蚕过桑，有什么功德配得上这份享受呢？于是他写下今我何功德，曾不事农桑这句自责的话。一位身居官位的诗人，能为挨饿的农夫低下头反思自己，这在当时是难能可贵的。这首诗也因此成了白居易同情人民疾苦的代表作。"},
  "白云泉":{story:"公元825年前后，白居易出任苏州刺史，治理这座江南名城的繁忙公务之外，他常登临城外的天平山散心。天平山上有一眼清泉，名叫白云泉，泉水从石间潺潺流出，如白云般自在，白居易看久了，竟觉得那泉水懂得他的心事，于是写下这首小诗。\n诗里他把天平山上那白云与泉水写得无拘无束：云自在地游荡，水自在地流淌，它们悠闲从容，从不着急，也从不忧愁。接着他忽然替泉水发问：既然这么自在，又何必奔冲到山下去，给纷纷扰扰的人间再添一层波浪呢？这哪里是在说泉水，分明是诗人自己的心声。\n其实白居易在苏州刺史任上政绩很好，很受百姓爱戴，但他年事已高，历经宦海浮沉，心里已生出了退隐之意。与其在官场的风浪里冲撞，不如学这山间的云与水，安闲自守。后人读这首诗，总能在快节奏的忙碌里感到一阵清凉——有时候，停下来欣赏一朵云、一泓泉，就是最好的休息。"},
  "后宫词":{story:"唐朝皇宫里住着成千上百的宫女妃嫔，她们中最幸运的才能得到皇帝的宠幸，更多的则是在深宫里孤独地老去。白居易一生关心底层的苦命人，后宫女子的寂寞自然也在他的笔下。这首《后宫词》用第一人称替一位失宠的宫妃说出了心里话。\n诗的一开始，这位女子就含着眼泪：夜里她连梦都做不成，泪把罗巾都湿透了，因为前殿正传来阵阵按着节拍的歌舞声。那是别的嫔妃正得到君王的宠爱，歌舞正欢。自己的君恩早已断绝，只能听着别人的欢笑，一夜一夜地熬。这是全诗最扎心的一笔：别人越热闹，自己越凄凉。\n后两句更是凄绝：她的容颜还没有衰老，皇帝的恩宠却早已断绝；她斜斜地倚着熏香的竹笼，就这么一直坐到天亮。一个熏笼，一把斜倚的身影，坐到天明的长夜，写尽了深宫里无数个无人知道的寂寞夜晚。这首短诗只有二十八字，却把失宠宫妃的哀怨写得入骨三分，历代读的人都为之心酸。后来它被选进许多选本，成为宫怨诗的典范之作。"},
  "花非花":{story:"这首小诗作于白居易晚年，大约写于他告别官场之后。诗只有短短几句，却像蒙着一层薄薄的雾，千年来引得无数人猜测它到底在写什么。白居易的好友元稹曾记下他的自注，说非花非雾这四个字本是为了配合音律的节拍——原来它的句式来自一首可以歌唱的歌行，所以它更像一段优美的旋律。\n它的美恰恰在这份朦胧：说它是花吧，却不是花；说它是雾吧，又不是雾。它夜半时分悄悄来，天一亮就悄悄离去，来如春梦，没有多少时候；去似朝云，连个落脚的地方都找不到。四句连环设喻，每个比喻都轻轻巧巧地落下，又都飘忽不定，像在写一场美梦，像在追一段往事，又像在叹一样留不住的东西。\n正因为不肯说破，历代解读众说纷纭：一说它写的是曾经陪酒唱曲的歌伎，来如春梦是昔日的欢聚，去似朝云是此后的离散；一说它悼念早亡的爱人，夜半来天明去像魂魄的相会；还有一说它只是写一场春夜的梦而已。白居易把答案藏了起来，让这首小诗像雾中花一样，每个人都可以照见自己的心事。这种可意会不可言传的美，正是它流传千年仍让人着迷的原因。"},
  "放言五首·其三":{story:"公元815年，一桩震动朝野的大事发生了：宰相武元衡在上朝路上被人刺杀。白居易时任太子左赞善大夫，他心急如焚，第一个上书请求火速缉拿凶手。谁知权贵们反而责怪他越职言事，把他贬为江州司马。踏上贬谪之路时，好友元稹正好也刚被贬官，写下五首《放言》诗寄给他。白居易一路读，一路和韵，写下这五首《放言》，其中最出名的就是这一首。\n诗里连用两个典故讲道理：试玉要烧三日满，用的是卞和献玉的故事。相传楚人卞和得到一块璞玉，两次献给楚王都被当成骗子砍去了双脚，直到第三任楚王命人剖开玉石，才发现里面是举世无双的和氏璧。玉是好玉，可要烧满三天才知道；辨材须待七年期，说的是周成王时，有人诬陷周公想夺位，周公东征避祸，等到后来成王明白真相，才把周公迎回来。周公的忠心，也要等时间来证明。\n白居易借这两个故事告诉自己，也告诉朋友：真假善恶一时看不清，不必急着分辩，时间一长自有公论。他当时蒙受冤屈，却不怨天不尤人，反而把眼光放得如此长远。这两句诗如今成了我们安慰蒙冤受屈之人最常用的话——时间，终会给所有人一个答案。"},
  "与梦得沽酒闲饮且约后期":{story:"大和年间，白居易和刘禹锡这两位老朋友先后回到洛阳定居。白居易号乐天，刘禹锡字梦得，两人都曾在宦海里几经沉浮，如今一个任太子宾客，一个任太子少傅，都是体面的闲职，正好结伴享受晚年的清福。大约公元834年的秋天，两位老人兴冲冲地一起凑钱买酒，痛痛快快地喝了一场。\n诗里写得热闹又可爱：两人凑了十千钱买一斗酒，边喝边算年纪——你我相差三岁，都离七十不远了！两位加起来一百三十多岁的老人，喝酒时还会互相打趣。喝到微醺，他们还玩起了高雅的游戏：酒到深处，开始抢着吟起旧日的诗来；兴致勃勃时，又铺开纸下棋对弈。诗里还提到侍候在旁的歌伎，看来这场酒宴颇有几分少年气象。\n喝得尽兴，两人又约定：今天还没喝够，改天再约。若是到了重阳佳节，你再来，我还来，咱们一醉方休！这首诗没有豪言壮语，只写两个老朋友的欢聚，却写得兴味盎然，真情扑面。它让我们看见，历经风浪之后，最珍贵的就是身边有个能陪你喝酒下棋、相约重阳的老友。"},
  "邯郸冬至夜思家":{story:"这首小诗作于公元804年前后，当时三十出头的白居易还没有考中进士，为了求取前程，他独自一人在外漫游。这年冬至，他路过邯郸，住在客店里。冬至在唐代是个大节日，民间讲究全家团聚，远行的人这一天也都要回家过冬节。可白居易身在异乡，只有一盏孤灯相伴。\n客店里显得格外冷清。抱着膝头的他，在灯前枯坐，灯影相伴，影子也跟着自己。到了深夜，外面传来一阵又一阵的喜庆声——客舍里的人都披着衣裳，纷纷出门参加节日的宴饮去了。只有他还坐在灯前，越听外面的热闹，心里越觉得孤单。\n可这首诗最妙的地方在最后两句：他没有直接说自己想家，而是想象家中的亲人此刻也一定夜深未睡，围坐在一起，正在念叨他这个远行在外的游子。明明是自己思念家人，偏偏写成家人思念自己。这个巧妙的笔法，与王维遥知兄弟登高处，遍插茱萸少一人的写法一脉相承，都是从对面落笔，让思念加倍。想家的人读了，往往鼻子一酸——原来千年之前的人，和今天的我们思念亲人的心情，一模一样。"},
  "秋雨夜眠":{story:"写下这首小诗时，白居易已告老还乡，以太子少傅的身份闲居洛阳多年，日子过得安闲自在。一场秋雨绵绵的夜，诗人随手记下自己的生活，竟成了一幅可爱的老人安睡图。\n诗里先说他这个老人家有个怪脾气：上床总爱拖得晚一些，等把灯吹灭了，才心满意足地睡下。而这一夜偏巧赶上秋雨，淅淅沥沥的雨声敲打着屋檐，正是天然的安眠曲。一觉醒来到早上，窗外还是灰蒙蒙的冷灰色调，可炉火早已烘得满满的，小屋里暖烘烘的。有心的家人在早霜初降之前，就让侍女铺好了新的寒衣和被褥。\n短短几句，没有一句惊天动地的话，却把一位老人的幸福写得满满的：有听雨安眠的好心情，有暖炉棉衣的照应，更有体贴的家人。这份从容知足，是白居易历经宦海风波、看尽人生起落之后换来的。后人读这首诗，常常心生向往：人这一辈子忙忙碌碌，到老了能有一个听雨入眠的秋夜，被照顾得妥妥帖帖，便是人间好时节了。"},
  "舟中读元九诗":{story:"公元815年，白居易因上书言事被贬为江州司马，只好乘船南下赴任。江上夜航，船舱里只有一盏孤灯。想到同样刚遭贬谪的好友元稹，白居易取出他的诗卷，在灯前细细地读。元稹在家族里排行第九，所以白居易亲切地叫他元九。\n这一读就读上了瘾。他把朋友的诗卷摊在灯前，一句一句地咀嚼，从掌灯时分一直读到天亮。读完了诗，灯油也熬干了，灯花将残，可天边还没有亮。眼睛早就读得又酸又痛，他却舍不得放下诗卷，就这么在昏暗里独自坐着，连灯也懒得再挑亮。灯残人未眠，那份灯下执卷的身影，千年之后读来仍让人动容。\n就在这时，窗外逆风卷起，波浪哗哗地拍打着船身，一声一声，像是拍在他的心上。景语即情语，风是逆风，浪是险浪，正衬出他胸中翻涌的愤懑与不平。一首诗，写尽了贬谪路上的孤愤，更写尽了两位诗人同甘共苦的深情。白居易与元稹并称元白，他们互相唱和的诗多达几百首，这首舟中夜读的小诗，正是他们患难之交最好的见证。"},
"锦瑟":{story:"这首诗写于李商隐晚年，大约唐宣宗大中十二年（858年）前后，此时他已近生命尽头，在郑州家中病卧不起。因年深日久，原题已失传，后人便取开头「锦瑟」二字为题。锦瑟是一种绘有锦纹的瑟，共二十五弦，传说瑟本为五十弦，因为弦声太悲，黄帝才改为二十五弦。\n诗中最神奇的是中间四句，一口气用了四个典故：「庄生晓梦迷蝴蝶」用庄周梦蝶的故事——庄子梦见自己变成蝴蝶，醒来后分不清是庄周梦见了蝴蝶，还是蝴蝶梦见了庄周；「望帝春心托杜鹃」讲的是古蜀国的望帝杜宇，国亡身死后化作杜鹃鸟，日夜悲啼，啼到口中流血；「沧海月明珠有泪」说海中鲛人哭泣时，眼泪会变成一颗颗晶莹的珍珠；「蓝田日暖玉生烟」说陕西蓝田的美玉埋在地下，暖日照耀时会升起若有若无的烟霭。\n这四个美丽又迷离的典故，追忆的是他逝去的青春华年。至于他到底怀念什么——是死去的妻子，是难忘的恋情，还是感伤自己一生的不得志，千百年来争论不休，却谁也没有标准答案。正因为人人读出的滋味不同，这首诗才被称为千古绝唱。"},
  "无题":{story:"这是一首没有题目的诗。李商隐写了不少「无题」诗，因为诗里藏着不便明说的情感，或许是刻骨的相思，或许是一段无疾而终的恋情，只能让懂的人自己去体会。\n这首诗大约写于他年轻时恋爱的阶段，讲述一对恋人相见艰难、离别更难的痛苦。暮春时节百花凋零，东风无力，更添伤感；春蚕吐丝直到生命最后一刻，「丝」与「思」谐音，比喻思念到死方休；蜡烛燃尽成灰，烛泪才干，正像恋人相思的眼泪。\n「春蚕到死丝方尽，蜡炬成灰泪始干」是传诵千古的名句。古人用它赞美坚贞的爱情，今天人们也用它歌颂老师、父母等无私奉献的人——无论情为何物，这份至死不变的执着，都同样打动人心。"},
  "嫦娥":{story:"相传远古时天上有十个太阳，晒得大地龟裂，英雄后羿射落九个，救了苍生。西王母赐给他一包不死药，吃了可以飞升成仙。后羿舍不得妻子嫦娥，把药交给嫦娥保管。谁知嫦娥一时好奇偷吃了灵药，身子便轻飘飘地飞上天去，从此住在清冷的月宫里，只有一只玉兔相伴。\n李商隐借这个人人皆知的神话，写下这首咏嫦娥的诗。前两句写月宫的清寂：云母屏风上映着暗淡的烛影，银河渐渐西斜，晨星也将隐没。后两句是诗人的猜想：嫦娥现在一定后悔偷吃了灵药吧，面对碧海一样的青天，夜夜只有孤独的心陪伴。\n这首诗历来有两种说法：一说是李商隐自伤身世——他自己才华出众却一生漂泊，正像月宫里孤独的嫦娥；另一说讽刺那些表面清净、内心寂寞的修道女子。月光清冷，心事悠长，这首诗把孤独写到了极致。"},
  "贾生":{story:"贾生就是西汉著名的才子贾谊。他二十多岁便才华横溢，文章写得极好，汉文帝非常赏识他，把他从长沙召回京城，还破格让他在深夜入宫，促膝长谈。\n按理说，这该是一段君臣遇合的佳话。可是李商隐在诗里笔锋一转，感叹文帝听得入神，不知不觉把座席往前挪动，空有一片求贤的诚意，可问的却不是百姓疾苦、治国大计，而是些鬼神之类的虚无之事。一句「不问苍生问鬼神」，点破了这场夜谈的空洞。\n李商隐借古讽今。他生活在晚唐，皇帝迷信方术、追求长生，有才华的读书人却报国无门。连汉文帝这样的明主尚且冷落真正的治国之才，更何况当朝的统治者？短短二十八字，把怀才不遇的愤懑写得入木三分。"},
  "无题二首·其一":{story:"这是一首追忆昨夜宴席的诗。昨夜画楼上西风吹拂，桂花飘香，李商隐在那里与一位心仪的女子不期而遇。筵席上灯红酒暖，两人目光相遇，却又不能相近，只能隔墙相望，如同隔着蓬山万重。\n诗中最有名的是「身无彩凤双飞翼，心有灵犀一点通」。灵犀，是古人传说中的一种神异的犀牛角，角中有白线贯通两头。诗人说：我身上没有彩凤那样的一双翅膀，不能立刻飞到你身边；可我们的心，却像灵犀一样，有一丝白线暗暗相通。\n这两句诗把恋人之间那种欲近不得、却又心意相通的感觉写得妙极了。今天人们仍常用它来形容知己之间不用说话便能彼此理解的默契。"},
  "落花":{story:"李商隐一生漂泊四方，寄身幕府，才华满腹却始终沉沦下僚。这首《落花》写于他客居异乡之时，表面上看是咏落花，骨子里咏的是他自己飘零的身世。\n一个暮春的日子，高阁上的客人们已经散尽，热闹的小园一下子空了；园中的花朵被风吹得纷纷乱飞，越过围墙，散落在小路上，飘进帘栊，追随着流水的落花，越来越远，再也回不到枝头。\n芳菲散尽，唯有青苔上的细点，像残留的墨迹，还带着落花的余香。诗人望着这一片狼藉的残红，心中涌起无限的惜花之情——那「肠断」的，到底是落花，还是自己呢？\n「高阁客竟去，小园花乱飞」，前一句写人散，后一句写花飞，人如客散，花如人飘零。李商隐把自己的身世之感悄悄融进落花里，全诗没有一个「我」字，却字字都是诗人的自伤。这种不直说、只暗示的写法，正是他缠绵悱恻的诗风。"},
  "隋宫":{story:"隋朝第二个皇帝隋炀帝杨广，是中国历史上出了名的奢侈皇帝。他为了下扬州游玩，征发几十万百姓开凿大运河，乘着豪华龙舟南下，船队绵延二百余里，沿途州县都要献上精美的食物，吃不完的就埋掉。\n当时朝廷中有不少忠臣上奏章劝谏，隋炀帝不但不听，还把劝他的人杀掉。他以为天下太平，自己大可以尽情享受，一次次乘兴南游，根本不在乎警戒防备。\n李商隐写这首咏史诗，借隋炀帝的故事讽刺晚唐的统治者。诗的结尾说得好：隋炀帝不是不想再来游赏，只是如今的隋宫已成废墟，只馀几只流萤在暗夜里飞来飞去。一个不爱惜百姓的皇帝，再豪华的宫殿，最后也只能留给萤火虫做家。"},
  "马嵬":{story:"唐玄宗天宝十五载（756年），安史之乱爆发，叛军攻破潼关，唐玄宗带着杨贵妃仓皇逃往四川。走到马嵬坡这个地方，随行的禁军将士又饿又累，愤怒地停下来不肯前进，他们说祸乱的根子是宰相杨国忠和他的妹妹杨贵妃，不杀掉他们就不护驾。玄宗无可奈何，只好忍痛赐死杨贵妃，一代美人就这样香消玉殒在马嵬坡前。\n更讽刺的是，就在不久之前，唐玄宗还和杨贵妃在七夕之夜对着牛郎织女星山盟海誓，笑牛郎织女一年只能相会一次，不如他们朝夕相守。可到了危难时刻，六军停马不前，皇帝连自己的爱妃也保护不了。\n李商隐用笔极为冷峻：军营里传来巡夜的梆声，却再也听不到宫中报晓的筹声，暗示贵为天子的玄宗，晚年竟被软禁般失去了自由。这首诗借历史讽刺帝王的爱情与承诺，在安史之乱的硝烟散尽之后，读来格外令人警醒。"},
  "为有":{story:"这是一首风趣的闺怨诗，写的是一位新婚不久的妻子对丈夫的娇嗔。诗中这位年轻妻子，家中云母屏风华丽精美，她容貌娇美，居住在京城。春天到了，京城里的寒气已经消尽，本该是和丈夫共度春宵的好时光，她却偏偏怕起春宵来。\n原来她的丈夫做官了，而且做的是大官——唐代三品以上的高官可以随身佩带金龟袋，人称「金龟婿」。天刚蒙蒙亮，丈夫就要起身去上早朝，把温暖的香被和娇妻独自留在床上。\n于是她忍不住埋怨：没来由地嫁了个佩金龟袋的好官婿，反倒辜负了这暖融融的鸳鸯被！「无端嫁得金龟婿，辜负香衾事早朝」把少妇又娇又怨的神情写得活灵活现。埋怨的背后其实全是爱，这种带着甜味的抱怨，正是古诗中最可爱的生气。"},
  "蝉":{story:"蝉住在高高的树梢上，只饮清露，不食人间烟火，古人因此把它看作高洁的象征。李商隐仕途坎坷，一生在幕府与科场之间漂泊，才华出众却始终得不到重用，于是借蝉来诉说自己的身世。\n诗里写：蝉因为栖身太高，餐风饮露，自然难以吃饱；它整夜不停地鸣叫，叫声里满是怨恨，却无人理会，只是白白费力。到了五更天，稀疏的叫声几乎要断绝了，可它寄身的那棵大树依旧一树碧绿，无动于衷——树无情，人更无情。\n这首诗的高明之处在于句句写蝉，又句句写人：蝉的高洁难处正像诗人的清高困顿，蝉的哀鸣无人理睬正像诗人的才华无人赏识。「本以高难饱，徒劳恨费声」，道尽了古往今来多少有才之士的辛酸。"},
  "宿骆氏亭寄怀崔雍崔衮":{story:"崔雍和崔衮是李商隐的表兄弟，他们的父亲崔戎曾任华州刺史，对李商隐有知遇之恩，给过他很多帮助。后来崔戎去世，崔家子弟分散，李商隐与他们聚少离多。一个深秋的日子，李商隐旅途中寄宿在一位骆姓人家的园亭里，秋夜萧瑟，思念之情涌上心头，便写下这首诗寄给远方的表兄弟。\n诗的前两句写眼前景：竹坞水清，槛外开阔，相思之情隔着重重城郭和夜幕蔓延。后两句最动人：秋阴久久不散，寒霜也下得晚了，池塘里枯败的荷叶虽已凋零，却还留着听雨的好所在。\n「秋阴不散霜飞晚，留得枯荷听雨声」是千古名句。相传曹雪芹写《红楼梦》时特别喜欢这一句，还特意借林黛玉之口说：只喜欢「留得残荷听雨声」（残荷一作枯荷）。枯荷本是无用的残景，在诗人听来，雨点打在枯叶上的声音，却成了秋夜里最知心的陪伴。"},
  "风雨":{story:"李商隐一生大部分时间都在做幕僚，寄人篱下，奔波于各地幕府之间，贫病交加，漂泊凄凉。这首诗以「风雨」为题，写的正是他羁旅生涯中一个凄风苦雨的夜晚。\n诗的开头用了一个典故：唐代名将郭元振（郭震）年轻时写下气势磅礴的《宝剑篇》，献给武则天，得到赏识，从此走上仕途。李商隐却叹息道：可惜啊，我的「宝剑篇」无人赏识，只能在风雨中漂泊，这样穷困潦倒的日子，似乎要过到头了。\n窗外黄叶在风雨中纷飞，心里更添羁旅之愁。但诗的结尾没有沉沦：新知道遇的美好，总让他忘掉羁旅的辛酸；素昧平生的人尚且肯伸出援手，何况是故乡的亲人呢？在风雨飘摇的晚唐，这份对人间温情的相信，是诗人心里最后的一点暖。"},
  "凉思":{story:"这首诗写于李商隐客居异乡之时。秋日里，一位客人来访又离去，水波渐渐平息，栏杆外一片平阔；蝉声停歇了，树枝上挂满凉凉的秋露。这些寂静的景物里，藏着诗人绵长的思念——他在远方怀念着一位「良人」，或许是挚爱的亲人，或许是心心相印的知己。\n诗的后两句把这种思念写得极深：他独自倚着栏杆伫立，凝望远方，久久不肯离去，不知不觉间，月亮已经悄悄移动了位置，时间悄然流逝，而他自己竟全然没有察觉。\n「倚立自移时」五个字，没有一句说「思念有多深」，却用一个人站到月亮都移了位的画面，把思念写得无声而绵长。这正是李商隐最擅长的本领——把最浓的感情，藏在最淡的景致里。"},
  "北青萝":{story:"深秋的傍晚，残阳西沉，落入崦嵫山——古人传说太阳落山的地方。李商隐独自走进深山，踏着落叶，去寻访一位住在茅屋里的孤僧。山路被寒冷的云气笼罩，一层又一层，不知走了多远，落叶深处，那茅屋中的人到底在哪里呢？\n等到终于见到孤僧，诗人被他的宁静深深打动。独敲木鱼，清磬声中，世界仿佛只剩下这一间茅庵；世界之大，不过如一粒微尘，人活在微尘之中，又何必苦苦执着那些爱与憎恨呢？\n「世界微尘里，吾宁爱与憎」融入了深深的佛家思想。李商隐一生为情所困、为仕途所累，此刻面对超然物外的孤僧，忽然觉得尘世间的一切爱憎得失，都如微尘般渺小。这首诗意境清冷幽远，像一幅淡墨的山水画。"},
  "霜月":{story:"深秋的夜晚，李商隐独自登上高楼。月光如水，洒满楼前，远处传来断续的雁鸣；连霜雪之神青女和月宫仙子素娥，都不畏惧这深夜的寒冷，在月光与霜色里争相展现她们皎洁美好的姿容。\n诗里的两位女神各有来历：青女是掌管霜雪的天神，每年深秋，她乘着霜气降临人间；素娥就是奔月的嫦娥，住在清冷的月宫之中。\n诗人眼中的「冷」，并不是萧瑟的冷，而是一种清寒高洁的美。青女与素娥敢于在严寒中争辉，正是诗人自己品格的写照——身处晚唐污浊的世道，他依然愿意守一份清冷，守一份不随波逐流的志气。「青女素娥俱耐冷，月中霜里斗婵娟」，写的不只是月与霜，更是一颗在寒夜里依然明亮的心。"},
  "瑶池":{story:"《穆天子传》记载了一个古老的神话：西周的周穆王有八匹日行三万里的骏马，他乘着八骏驾的车远游西方，在瑶池受到了西王母的热情款待。席间西王母唱歌挽留他，希望他日后再来相会。\n可是李商隐在诗里问了一句让神仙都尴尬的话：八骏一天能跑三万里，周穆王为什么再也不来赴约了呢？原来传说周穆王也是个向往长生的帝王，可他终究是一介凡人，终究会有死去的一天，那个西王母许下再会的瑶池，他再也无法重来。\n还有一个对照：相传周穆王南游时，路上遇到百姓冻饿而死，他便作了哀伤的《黄竹歌》；而一转头，他又在瑶池与西王母饮酒作乐。一边是民间的疾苦，一边是帝王的欢宴，李商隐借这个神话讽刺晚唐皇帝迷信仙道、妄想长生，实在可叹可笑。"},
  "重过圣女祠":{story:"圣女祠相传建在陕西陈仓的大散岭附近，祭祀的是一位传说中犯了罪、被贬谪到人间的仙女。大约在唐宣宗大中十年（856年）前后，李商隐又一次经过这座祠堂，想起多年前自己也曾路过这里，物是人非，不由得感慨万端。\n诗里写的圣女祠荒凉而神秘：白石砌成的门扉上长满了碧绿的苔藓，圣女就像是从天上「上清」仙境被贬下来的人，迟迟不能归去。一整个春天，如烟如梦的细雨常常飘洒在瓦上；整整一天，灵性的风吹着祠前的旗子，却怎么也吹不满。\n最奇妙的是「一春梦雨常飘瓦」——雨丝细得像梦一样，轻轻飘在瓦上，这哪里是写圣女，分明是写诗人自己。李商隐一生怀才不遇，在幕府之间辗转沉沦，正如这位沦谪不归的圣女。千古年来，不知多少失意的人，在这首诗里认出了自己的影子。"},
  "韩碑":{story:"唐宪宗元和十二年（817年），淮西节度使吴元济叛乱，宰相裴度亲自督师平乱，名将李愬在一个大雪之夜奇袭蔡州，活捉吴元济，这场困扰朝廷多年的叛乱终于平定。捷报传来，举国欢腾。\n韩愈奉命撰写《平淮西碑》。他忠于史实，认为裴度运筹帷幄居首功，碑文便多写裴度。这下惹恼了李愬的妻子——她是唐安公主之女，进宫向皇帝哭诉碑文不实。皇帝于是下令磨去韩愈的碑文，命段文昌重新撰写。\n多年后，李商隐读史至此，愤然写下这首《韩碑》，力赞韩愈原文的公正与文采。他赞叹碑文写得像河流一样浩荡，像山一样安稳，甚至说愿抄写万本、诵读万遍，直到口角流沫、右手磨出老茧。「愿书万本诵万过，口角流沫右手胝」，这份对真理与良史的执着，正是诗人心中最硬的骨头。"},
"秋夕":{story:"相传这首诗是杜牧看见宫中女子的生活后有感而作，也有人把它当作一首宫词。唐朝的皇宫幽深广大，成百上千的宫女被选入宫后，很多人一生都见不到皇帝，只能在深宫里一年一年地消磨青春。\n诗里的故事发生在一个秋天的夜晚：清冷的烛光映着描花的屏风，一名宫妃拿着轻罗小扇，无聊地扑打着飞来飞去的萤火虫。夜越来越深，石阶凉得像水一样，她索性躺在台阶上，仰看天上的牵牛星和织女星。\n牵牛和织女一年还能相会一次，宫妃却连这样的盼望也没有。古人写团扇，常常用它来比喻被抛弃的女子，因为扇子在夏天备受宠爱，一到秋天就被丢进箱子。全诗没有一个愁字，却把深宫的寂寞写到了极处，画面又美又凉，是宫怨诗中的名篇。"},
  "题乌江亭":{story:"相传唐武宗会昌年间，杜牧出任黄州刺史，赴任途中路过乌江亭。这座亭子就在当年西楚霸王项羽兵败自刎的地方。楚汉相争时，项羽被刘邦大军围在垓下，一路突围逃到乌江边，亭长撑船劝他渡江回江东，将来再图大业。\n可是项羽却说：我带江东子弟八千人渡江而西，如今没有一个人回来，我还有什么脸面见江东父老？说完把战马送给亭长，转身与追兵厮杀，最后自刎而死。\n杜牧站在这座亭子前，越想越替项羽惋惜，挥笔写下这首翻案诗：胜败是兵家常事，难以预料，能忍受失败和耻辱才是真正的男儿；江东子弟人才济济，若能忍辱负重、卷土重来，胜负还未可知呢！别人都在嘲笑项羽，杜牧偏偏为他惋惜，这正是杜牧咏史诗最厉害的本领——爱唱反调，却唱得句句在理。"},
  "金谷园":{story:"唐武宗会昌四年，杜牧在洛阳任监察御史。一天傍晚，他散步走到金谷园旧址，只见荒草流水，繁华不再，想起这里发生过的故事，心中十分感慨。\n金谷园是西晋大富豪石崇的别墅，里面奇花异草、珍珠宝贝堆积如山。石崇最宠爱一个叫绿珠的歌姬，她美若天仙，又善吹笛。权臣孙秀想要绿珠，石崇坚决不给。后来孙秀假传圣旨捉拿石崇，绿珠哭着说：我情愿死在您面前！说完纵身跳楼而死。\n几百年过去，名园成了废墟。杜牧写下：繁华事散逐香尘，流水无情草自春。日暮东风怨啼鸟，落花犹似坠楼人。傍晚的东风里，鸟儿的啼叫仿佛带着怨恨，纷纷落下的花瓣，多像当年从楼上坠落的绿珠啊！一句「落花犹似坠楼人」，把花和人的命运叠在一起，让千百年后的读者依然心头一颤。"},
  "叹花":{story:"相传杜牧年轻时到湖州游玩，遇见一个十几岁的美丽少女，惊为天人，便和她的母亲约定：十年之内我一定来娶她，如果过了十年不来，就任凭她另嫁他人。说完留下聘礼，依依而别。\n此后杜牧辗转各地做官，等他被任命为湖州刺史时，已经过去十四年了。他兴冲冲地赶到那户人家，却得知少女早已嫁人，如今已是两个孩子的母亲。杜牧怅然若失，埋怨自己来晚了。\n可他还是提笔写下了这首《叹花》：只怪自己寻春来得太迟，不必惆怅埋怨花开的时候。狂风已经把深红色的花朵吹落殆尽，如今已是绿叶成荫、果实满枝。诗里没有一句责备女子的话，只把遗憾轻轻放下，这份温柔和克制，正是杜牧的风度。一说此诗只是咏叹春光的泛泛之作，但这个美丽的约定故事，却让这首诗流传得更广。"},
  "紫薇花":{story:"唐武宗会昌末年，杜牧升任中书舍人，负责为皇帝起草诏书。唐朝的中书省一度改名紫微省，官署的庭院里种着紫薇花。夏天到秋天，别的花都已凋谢，紫薇却开得正好，杜牧于是以花自喻，写下这首诗。\n紫薇花开在清冷的秋露里，一枝独秀；它不占春天园中最显眼的位置，不跟桃花李花争一时的风光。等到秋高气爽，桃花李花早已不知去了哪里，紫薇却迎着秋风开放，仿佛在笑那些在艳阳里热闹一时的花。\n杜牧借着紫薇讲自己的人生：他出身名门，少年成名，却不肯逢迎权贵，宁可被挤到外地去做刺史，也不肯同流合污。他就像这株紫薇，花开得晚，却开得有风骨。「桃李无言又何在，向风偏笑艳阳人」两句，把不肯趋炎附势的气节写得淋漓尽致，所以后人也把杜牧称作「杜紫薇」。"},
  "齐安郡后池绝句":{story:"唐武宗会昌四年，杜牧出任黄州（古代叫齐安郡）刺史。黄州在当时是个偏僻的小地方，政务清闲。夏日里，杜牧常常坐在郡衙后面的池边乘凉，这首小诗写的就是那里幽静的风光。\n池塘上，菱角叶和浮萍相间，绿得像一匹锦缎；夏天的黄莺千百遍地婉转啼叫，在蔷薇花丛里穿来穿去。下了一整天的蒙蒙细雨，因为没有人来欣赏，池塘便一直保持着安静的样子。\n只有一对鸳鸯，披着红褐色的美丽羽毛，面对面地在水里洗着澡，一点也不怕人。前两句热热闹闹，是莺歌燕语；后两句安安静静，是微雨鸳鸯。动与静合在一起，画面又清新又闲适。短短二十八字，把一座无人打扰的小池塘写得像世外桃源，让人一读就安静了下来。"},
  "题齐安城楼":{story:"杜牧在黄州做刺史时，登上齐安城楼，写下了这首思乡的小诗。呜轧一声，是城楼上的画角吹响的声音，在江面上悠悠回荡。淡淡的夕阳洒在江中，波光粼粼，慢慢沉入寒冷的沙洲。\n杜牧祖籍京兆万年，也就是今天的西安，那里离黄州有几千里路。诗人说：故乡远在七十五个长亭之外，不用靠在栏杆上苦苦回头张望了，望也望不见。\n古代大路边每隔十里建一座长亭，供行人休息。杜牧用「七十五长亭」把看不见摸不着的遥远，变成了一座一座可以数出来的亭子，故乡有多远，心里就数了多少遍。全诗前两句写景，后两句抒情，角声、夕阳、寒汀，再配上一个凭栏远望的背影，把贬谪外地的孤独和乡愁写得又淡又浓。"},
  "初冬夜饮":{story:"唐武宗会昌二年，杜牧被派到黄州做刺史，远离京城，壮志难酬。一个初冬的夜晚，他独自在客馆里喝酒取暖，想起西汉一位叫汲黯的老臣，提笔写下这首诗。\n汉武帝的时候，忠臣汲黯因为敢于直言，得罪了许多权贵，晚年被外放做淮阳太守。他常常生病，有一次皇帝问起，他说自己就像被丢在淮阳的病人，空有一腔忠心。杜牧借汲黯自比：我就像那个多病的老汲黯，偶尔只好借酒寻一点欢乐。\n喝着喝着，他看见台阶下堆着白雪，白得像一树盛开的梨花。这么美的雪夜，明年此时我又会在哪里，靠着谁的栏杆看雪呢？「砌下梨花一堆雪，明年谁此凭阑干」，明明是雪，偏说成花，把客居的凄凉藏进眼前的美景，美里透着一股说不出的孤独，这就是杜牧的含蓄。"},
  "屏风绝句":{story:"杜牧家里有一扇年代久远的屏风，上面画着唐代大画家周昉的仕女图。周昉最擅长画体态丰腴、姿态优雅的贵族女子，人称「周家样」。屏风上的美人细腰纤纤，可是年月太久，红漆的颜色已经剥落了一半。\n奇妙的是，屏风斜放在玉窗旁边，画中的美人映着窗外的光，仿佛斜倚在窗前。一位现实中的女子走过，拂去屏风上的灰尘，仔细一看，竟对着画里的美人暗暗生起嫉妒心来——她要和画中人比一比谁更娇美。\n诗人没有直接夸画中美人，也没有直接夸眼前人，只写真人拂尘自照、心里暗暗比较的小动作，意味立刻丰富起来。真的美，假的美，谁更胜一筹？杜牧把答案轻轻留给读者。「岁久丹青色半销」也说明，他写下这首诗时，眼前这幅周昉真迹已经流传了很久很久。"},
  "念昔游三首·其一":{story:"杜牧年轻时在江西、宣歙等地的幕府里做了将近十年幕僚，那十年他远离京城的是非，也远离了功名的束缚。后来他回忆起这段时光，一口气写了三首《念昔游》，这是第一首。\n诗的大意是：十年间我飘然生活在规矩法度之外，喝酒时自己给自己斟酒、自己给自己敬酒。秋天看山，春天下雨，都是我最悠闲自在的吟诗时光；我靠着栏杆，几乎倚遍了江南每一座寺院的楼台。\n「绳检」是规矩和约束的意思，「绳检外」三个字，把一个不受拘束、自得其乐的青年杜牧写得活灵活现。自斟自饮不是孤独，而是自在；倚遍寺楼不是无聊，而是把整个江南都装进了诗里。这三首诗是杜牧对自己青春漫游的纪念，也让我们看见，这位忧国忧民的诗人，也有如此潇洒快乐的一面。"},
  "题木兰庙":{story:"杜牧在黄州做刺史时，有一次经过一座木兰庙，庙里供奉的是代父从军的女英雄花木兰。他进庙瞻仰，想起木兰的故事，写下这首诗。\n木兰本是织布的姑娘，父亲老了，弟弟还小，朝廷又来征兵，她便女扮男装，替父出征。多年征战凯旋归来，同伴们才知道并肩作战的好男儿，原来是女郎。杜牧在诗里说：弯弓征战时她扮作男儿，可是在梦里，她也曾经对镜画眉，恢复女儿模样。\n胜利归来后，木兰不恋功名，只想回家乡。杜牧想象：木兰几次想家的时候，只能端起酒杯，在拂云堆上对着王昭君（明妃）的雕像遥祭，把自己说不出的乡思，寄托给同样远离故乡的另一位奇女子。全诗把战场上的英雄和梦里的女儿、木兰和王昭君叠在一起，写出巾帼英雄柔软的心肠，短短四句，回肠荡气。"},
"夜归鹿门歌":{story:"孟浩然四十岁之前一直隐居在襄阳城南的鹿门山，这首诗写的就是他某个傍晚回家路上的所见所感。黄昏时分，山寺里的钟声远远传来，汉江边的渔梁渡头人声鼎沸，人们争着摆渡回家，各家炊烟袅袅。可是孟浩然不走人多的路，他独自沿着山路往鹿门山深处走去。\n鹿门山可大有来历。相传东汉末年，襄阳有位高士名叫庞德公，诸葛亮曾向他请教，司马徽对他执弟子之礼。乱世将起时，庞德公带着妻子儿女隐居鹿门山，采药度日，从此再不问世事。后人就把这座山看作隐逸之山，孟浩然选择住在这里，正是追慕先贤的风骨。\n诗人写道「岩扉松径长寂寥，惟有幽人自来去」——山岩当门，松间小路又长又静，只有他这个「幽人」独自来去。一边是热闹的尘世，一边是清冷的幽山，两相对照，诗人把孤独写得那么自在，那么骄傲。\n这首诗像一幅有声的画：前四句有钟、有喧、有渡头的人声，后四句忽然静下来，只剩下松径和月光。这种由闹入静的写法，成为后世山水田园诗的经典范本。"},
  "与诸子登岘山":{story:"岘山又名岘首山，就在襄阳城南，孟浩然和几位朋友同来登山。登上山顶远望汉水，他却想起了另一位常登此山的古人——西晋名将羊祜。\n羊祜曾镇守襄阳十年，德高望重，深得军民爱戴。他闲暇时常与好友邹湛同登岘山饮酒赏景，久久不愿离去。有一次他望着眼前青山，忽然感慨万千，对邹湛说：「自有宇宙，便有此山。自古以来，多少贤达胜士登临此山远望，都和你们一样多啊！」言下之意是——他们和我们一样看山，如今他们在哪里？将来我又在哪里？羊祜死后，百姓感念他的恩德，在山上立碑建庙。据说往来行人读碑文时无不被羊祜的事迹感动落泪，这块碑从此被称为「堕泪碑」。\n孟浩然站在同一座山上，眼前山水依旧，人事全非，于是吟出了千古名句：「人事有代谢，往来成古今。江山留胜迹，我辈复登临。」人世间的事物新旧更替，寒来暑往就成了古今；江山留下了名胜古迹，而今我们又来登临凭吊。\n这首诗把一次普通的登山写得沉甸甸的：它告诉孩子，山河长在，人生却如过客，所以我们更要懂得珍惜眼前、奋发有为。"},
  "夏日南亭怀辛大":{story:"这是一个夏夜。南亭大概是孟浩然隐居处附近的一座小亭。夕阳西沉，山边的日光渐渐隐没，池中的月亮悄悄升起，荷花的香气随风飘来，露珠在竹叶上滴落，发出清脆的声响。\n孟浩然把头发散开，推开窗户，悠闲地躺在亭中纳凉，「散发乘夕凉，开轩卧闲敞」。古人平日要把头发束起戴上冠帽，只有在最放松的时候才会披散头发。这一「散」一「卧」，把隐者夏日的自在写得活灵活现。\n晚风拂面，夜色清凉，他想取出鸣琴弹上一曲，却忽然「恨无知音赏」——遗憾没有知音来一起欣赏。这里用了一个著名的典故：春秋时，俞伯牙弹琴，只有锺子期能听懂他琴声中「巍巍乎若泰山、洋洋乎若江河」的心意，锺子期死后，伯牙摔琴绝弦，终身不再弹琴。孟浩然想念的辛大，是他平生最要好的朋友之一，一位懂他琴声的人。\n于是他在诗的最后轻轻问了一句：「感此怀故人，中宵劳梦想。」如此良夜，只能把思念带到梦中相见了。夏夜美景与怀友之情交融，成为唐人写乘凉怀人的名篇。"},
  "秋登兰山寄张五":{story:"秋天到了，孟浩然登上襄阳附近的兰山（一说即城北的北山），极目远望，想念远方的好友张五。张五是谁，历来有争议，有学者认为他可能就是孟浩然的同乡好友张子容，两人自幼交好，后来张子容进京求仕，与孟浩然天各一方。\n清秋的山色明净高远，诗人站在高处向朋友所在的方向眺望：「相望试登高，心随雁飞灭。」他试着登上高山遥遥相望，心却随着天边南飞的鸿雁，越飞越远，直到消失在视线之外。大雁是候鸟，秋往南飞，古人常用它寄托对远方亲友的思念。\n傍晚来临，暮色四合，淡淡的愁绪悄悄升起，而清秋的山光却激发了他登高的兴致：「愁因薄暮起，兴是清秋发。」天色一暗，思念就浓了；秋风一爽，兴致就高了。这「一愁一兴」，正是登山怀友时复杂心情的真实写照。\n结尾「何当载酒来，共醉重阳节」，他热切地盼望：什么时候你才能带着酒来，我们痛痛快快喝一场，一醉方休，共度重阳佳节？登高、饮酒、赏菊，正是重阳节的习俗。全诗情景相生，由秋景引出秋思，把对友人的一片深情写得含蓄又绵长。"},
  "宿桐庐江寄广陵旧游":{story:"唐玄宗开元十三年（725年）前后，孟浩然离开了居住多年的家乡襄阳，开始漫游吴越，顺长江东下。这一晚，他的船停泊在桐庐江（今浙江桐庐一带的富春江段）。\n夜宿江上，两岸山色在暮色里越来越暗，远处传来猿猴一声声哀切的啼叫。江水湍急，在夜里哗哗奔流；两岸的树叶被风吹得呜呜作响，清冷的月光照在一叶孤舟上。这便是诗中「山暝听猿愁，沧江急夜流。风鸣两岸叶，月照一孤舟」的画面。山暝、猿愁、江急、风鸣、月冷、孤舟，六个意象叠在一起，把江上秋夜的孤独写得淋漓尽致。\n越旅越孤独，他不禁想起了远方的朋友：「建德非吾土，维扬忆旧游。」建德不是我的故乡，我更怀念扬州（维扬）的旧日朋友啊！广陵即扬州，孟浩然此前曾在那一带游历，结交了不少知心好友。\n于是他把这份思念托付给滔滔江水：「还将两行泪，遥寄海西头。」就让这江水带着我的两行热泪，一直流向西边的扬州，寄给我的老朋友吧。全诗景中有情，情随景生，是孟浩然漫游诗中的代表作。"},
  "早寒江上有怀":{story:"孟浩然漫游吴越，客居江上，秋风一起，寒意先到。木叶萧萧飘落，大雁排成一字或人字，向南飞去——这正是「木落雁南度，北风江上寒」的画面。江上北风劲吹，让人真真切切地感到秋天来了，冬天也不远了。\n望着南飞的大雁，诗人想起了北方的家乡：「我家襄水曲，遥隔楚云端。」我家在襄阳的襄水湾，被楚地南天的白云远远隔开。襄水在襄阳，孟浩然是襄阳人，此诗作于他在异乡漂泊之时。楚云，是他游子心头一道望不穿的屏障。\n思乡之外，诗里还藏着更深的迷惘：「迷津欲有问，平海夕漫漫。」这里用了一个典故：孔子周游列国时，曾派子路向长沮、桀溺两位隐士打听渡口在哪里，隐士反问子路——天下滔滔，谁能改变？你跟着孔子东奔西走，倒不如和我们一样归隐算了。孟浩然此时也想问一问人生的「渡口」究竟在何方：是继续求仕，还是归隐田园？可他放眼望去，只见暮色中江水浩渺，一望无边，前途就像这茫茫平海，没有答案。\n这首诗把早寒的秋景、浓浓的乡愁和对人生的迷惘揉在一起，情景交融，低回婉转，被后人视为孟浩然五律中的精品。"},
  "题大禹寺义公禅房":{story:"孟浩然漫游吴越时来到越州（今浙江绍兴），曾拜访过大禹寺的义公禅师，并参观了禅师的禅房，写下这首诗。大禹寺相传是为纪念大禹而建，是越中著名的古刹。\n禅房建在哪里呢？「义公习禅寂，结宇依空林。」义公一心修习禅定的寂静功夫，把房子建在空寂的山林之间，远离尘世的喧嚣。「空林」二字，既写环境之幽深，也衬心境之空明。\n诗人站在禅房前放眼四望，只见「户外一峰秀，阶前众壑深。」门外一座山峰挺拔秀丽，台阶前万条山谷幽深静谧。群峰万壑仿佛都在默默守护这一方净土。接着夕阳西照，风雨初收，「夕阳连雨足，空翠落庭阴」，雨后的夕阳把满山的青翠都洒落在庭院的阴影里，绿得仿佛要滴下来。\n最动人的是结尾：「看取莲花净，应知不染心。」莲花洁净，出淤泥而不染，是佛教里象征清净的经典意象。孟浩然说，看着义公禅房内外这般洁净的莲花，就能知道义公禅师的心也如同莲花一般，一尘不染。全诗明写禅房之景，实赞禅心之净，景、禅、情三者交融，令人读后也觉心旷神怡。"},
  "宿业师山房期丁大不至":{story:"孟浩然借宿在业禅师（一位名叫业的僧人）的山间禅房，与朋友丁大约好今晚前来相会。可是左等右等，丁大始终没有到。\n等待中的时间过得格外快。夕阳缓缓翻过西边的山岭，群山深谷转眼间就暮色四合，「夕阳度西岭，群壑倏已暝」——一个「倏」字，写出天黑得那样快，也写出等待的人心里越来越急。\n夜色降临，山中的景致却愈发清幽动人：月亮升上松梢，夜风送来凉意；清风吹动山泉，叮咚作响，满耳都是悦耳的清音。「松月生夜凉，风泉满清听」，十个字里月色、凉意、风声、泉声全有了，被誉为写山间夜景的神来之笔。\n可是风景越好，越显得孤独。「樵人归欲尽，烟鸟栖初定。」打柴的人差不多都回家了，暮霭中的鸟儿也都安歇了，万物归巢，只有诗人还痴痴地等着，盼着一个终究没有出现的身影。结尾「之子期宿来，孤琴候萝径」——说好今晚要来的朋友啊，我抱着一张琴，独自在藤萝丛生的小径上等候着你。守着孤琴、守着月色、守着松风泉响，赴约的人未至，这份心意和这份美景，都留在了诗里。全诗不写一个「怨」字，却处处都是等待的怅惘。"},
  "秦中寄远上人":{story:"孟浩然曾在长安（秦中）求仕多年，却始终没有谋得一官半职，心灰意冷之下写下这首诗，寄给远方的上人——「上人」是对僧人的尊称，远上人是他相交多年的僧人朋友。\n诗的开头近乎决绝：「北阙休上书，南山归敝庐。」北阙是皇宫门前向北的楼观，代指朝廷；南山指终南山，代指隐居之地。他说：不要再向朝廷递什么自荐书了，还是回到终南山我那间破草屋去吧！「休」字带着一股憋闷已久的怨气。\n接着是他最沉痛也最著名的一句：「不才明主弃，多病故人疏。」我没有才华，所以被圣明的君主抛弃；我多病，所以老朋友们也渐渐疏远。相传这句诗后来还惹出一段公案：孟浩然在王维宫中值房偶遇唐玄宗，唐玄宗让他念诗，他脱口念出这两句，唐玄宗听了很不高兴，说：「是你自己不求做官，朕并没有抛弃你，怎么反倒怪起朕来？」孟浩然求仕之路从此彻底断绝。这段故事的真假已不可考，但这句诗的辛酸是千真万确的。\n诗的结尾，他宣布了自己的归宿：「白首卧松云，迷花不事君。」从此白头卧于松云之间，迷恋花草，不再侍奉君王。「永怀愁不寐，松月夜窗虚」，可真正豁达谈何容易？长夜里，他仍望着窗外松间的月亮，愁得难以入眠。一个想报国而无门的读书人，就此走向山水之间。"},
  "洛中访袁拾遗不遇":{story:"孟浩然漫游到洛阳，想去拜访好朋友袁拾遗——「拾遗」是朝廷里负责劝谏皇帝的官职，姓袁，一说即袁瓘，与孟浩然交情很深。可他兴冲冲赶去，却扑了个空：朋友不在。\n再一打听，才知道友人已经获罪，被流放到江岭去了。江岭指五岭以南的岭南地区，当时还是蛮荒烟瘴之地，被贬去那里，几乎等于生离死别。孟浩然百感交集，写下了这首小诗：「洛阳访才子，江岭作流人。」前一刻还在洛阳做京官的才子，转眼成了江岭的流放之人，一「访」一「作」，一热一冷，物是人非之叹尽在其中。\n最能见深情的是后两句：「闻说梅花早，何如北地春。」听说岭南地暖，梅花开得比北方早得多，可这早早开放的梅花，哪里比得上故乡洛阳的满园春光啊！诗人没有直接说「我为你难过」，而是把思念和惋惜藏进梅花与春光的比较里——岭南的梅花开得再早、再好，在思念故乡的友人眼里，也及不上北方故园的一缕春色。\n全诗短短二十字，凭吊时事、怜惜友人、眷恋故土三重情感交织，语浅情深。后人评价孟浩然的绝句「冲淡自然却真挚动人」，这首诗是最好的例子。"},
  "送杜十四之江南":{story:"孟浩然在武昌一带送好友杜晃远行。古人以同曾祖父的兄弟排行为「十四」，这位杜十四要去的地方是江南。\n送别的时节正是春天。孟浩然家在襄阳，杜十四的目的地大约在今江浙一带，两地之间水路相连，荆吴之地，江河纵横，人们往来都以船为家，「荆吴相接水为乡」一句，先写出江南水乡的特点——在那里，船就是屋，水就是路。\n春天本是明媚的，可在送别的人眼里，春江却显得烟波浩渺、迷迷茫茫：「君去春江正渺茫。」浩荡的江水一去不回，正如友人的前程，望不到尽头，也追不上脚步。\n最揪心的是结尾两句：「日暮征帆何处泊？天涯一望断人肠。」天色将晚，你那远行的小船今晚会在哪里停泊呢？我独自向着水天尽头远远望去，只见孤帆一点，终于消失，离愁别绪顿时涌上心头，令人肝肠寸断。日暮、孤帆、天涯，三个意象层层铺展，把看不见、抓不着的思念，化作了眼前苍茫的江景。\n这首诗以景写情，句句是水，句句是情，被誉为唐人送别绝句中的上品。"},
  "渡浙江问舟中人":{story:"浙江就是今天的钱塘江。孟浩然此行渡江，前往越中，也就是会稽（今浙江绍兴）一带。当时越中山水名动天下，李白就写过「我欲因之梦吴越，一夜飞度镜湖月」。孟浩然此行，也是慕名而去。\n钱塘江江面宽阔，渡江需时，站在船上，他恨不得一步跨过江去。于是便有了诗的开头：「时时引领望天末，何处青山是越中？」他一次又一次伸长脖子，踮起脚向天边张望——哪一座青山，才是我日思夜想的越中啊！「引领」这个动作写得天真又急切，像极了一个迫不及待要去游乐园的孩子。\n后两句写道：「时时引领望天末，何处青山是越中。」一路舟行，一路张望，一路相问，连向舟中人打听带自言自语，恨不得江风再快一点、船桨再快一点，好让他早点看到越中的青山。\n这首小诗像旅途中随手抓拍的一个镜头：没有典故，没有辞藻，只有一个望眼欲穿的旅人和一江浩荡的春水。可正因为这份毫无掩饰的急切与喜悦，千载之下读来，仍能感到一个旅人奔向山水时那颗怦怦跳动的心。"},
  "送朱大入秦":{story:"朱大是孟浩然的一位好友，排行老大，一说是一位行走江湖的道士。孟浩然送别他，他要去的方向是秦——长安所在的关中地区，那是当时天下人建功立业、一展抱负的地方。\n开头一句「游人五陵去」，点出友人此行的目的地与身份。「五陵」本指长安附近汉代五位皇帝的陵墓，汉代富贵人家都迁居到那一带，「五陵少年」成了豪侠少年的代名词。孟浩然说友人要去五陵之地，既是交代去向，也带着一份对友人前程的期许——那是豪杰云集的地方啊。\n最动人的是后两句：「分手脱相赠，平生一片心。」临分手时，孟浩然解下自己随身佩带的一把宝剑，送给友人。这把剑不是普通的剑，诗人接着说，它价值千金。相传孟浩然自己曾记载：「少好节义，喜振人患难。」他年轻时崇尚侠义，最爱急人之难。这把千金宝剑，正是他任侠精神的象征。\n更贵重的是剑里藏着的东西：「平生一片心」。千金之剑，价值不菲，而比剑更贵重的，是孟浩然对友人「平生」——一辈子积攒下来的赤诚之心。全诗仅二十字，借一把宝剑写尽肝胆相照的友情，豪爽洒脱，掷地有声。"},
  "送友人之京":{story:"京，指京城长安。一位友人将要启程赴京求仕，孟浩然为他送行。一「送」一「赴」，两人的命运在此分岔。\n开头两句对照鲜明：「君登青云去，予望青山归。」你要登上青云直上京城，去做官、去飞黄腾达；而我，只能望着青山，回到隐居的地方去。一个「登」字写尽友人的春风得意，一个「望」字写尽自己的落寞向往。青云既指高天，也暗喻仕途显达；青山既是实景，更是孟浩然心灵的归宿——他一生大半岁月都隐居在襄阳的山水之间。\n后两句写尽离别之痛：「云山从此别，泪湿薜萝衣。」从此我们被层层叠叠的云山隔开，天各一方。送别的泪水打湿了衣襟，那衣服上，还挂着隐居处的薜荔和女萝——这些山间藤蔓，是隐者衣装的标志。\n耐人寻味的是，诗人送的是「别人去当官」，自己却选择「回归山林」。孟浩然并非不想做官，只是求仕多年处处碰壁，最终把一腔热望埋进青山。这首诗送的是友人，道的却是自己的选择：从此你入你的官场青云，我守我的云山薜萝。二十个字，把仕与隐的分岔路口写得意味深长。"},
  "送别":{story:"王之涣一生只留下六首诗，首首都脍炙人口，这首《送别》是其中之一。它写的是路边一个极常见的场景，却被他写得意味深长。\n「杨柳东风树，青青夹御河。」送别的地点，是皇宫外一条名叫御河的水道旁。春风拂过，两岸的杨柳青翠欲滴，枝条低垂，依依拂水。御河人来人往，本是繁华之地，可再好的春光，也留不住远行的脚步。\n「近来攀折苦，应为别离多。」攀折，就是折下柳条。近来柳枝都被折苦了——为什么？因为离别的人实在太多了。原来，古人在送别时有一个传统习俗：折一枝杨柳送给远行的亲友。为什么呢？一来「柳」和「留」读音相近，折柳就是「留你」的意思，希望行人多留一会儿；二来柳条插在哪里都能活，折柳相赠，也祝愿远行人随遇而安、一路平安。\n全诗没有一个「愁」字，却处处是愁。诗人不直说送别有多伤感，而是借被「攀折苦」的杨柳，道出人间离别的频繁与沉重。二十个字，像一句轻轻的叹息，道尽了所有送别者心里共同的滋味，这正是绝句「以小见大」的妙处。"},
  "宴词":{story:"这首小诗是王之涣在一次饯别宴席上写下的。「宴词」，就是宴席上为送别而作的诗。\n「长堤春水绿悠悠，畎入漳河一道流。」长堤之下，春水涨得满满的，碧绿碧绿的，悠然流淌；田间的水沟（畎）把这碧绿的春水汇聚起来，一道流入漳河。画面清新辽阔，春水仿佛也带着宴会上人们的欢声笑语。\n可是欢乐总有尽头。宴席一散，客人就要登船远行。这时，船工开始摇桨，桨声一声一声，催促着行人上路。王之涣对即将分别的朋友说：「莫听声声催去棹」——不要听那一声声催促开船的桨声啊！桨声越急，离别就越近；越催，心里越舍不得。\n最后一句更是神来之笔：「桃溪浅处不胜舟。」桃花夹岸的溪水那么浅，浅浅的水面，怎么能载得动我们满载离愁的小船呢？——表面说水浅载不动船，实际上是说离愁太重，船根本载不动。把看不见的「愁」变成有重量的东西压在船上，这种写法叫「无理而妙」：溪水当然不会因为愁而变浅，可离别的滋味，偏偏就是这样沉重。\n全诗写景、写声、写情融为一体，二十八字里，有春水的绿，有桨声，有桃花溪，更有说不出口的千钧离愁。"},
  "九日送别":{story:"九日，指农历九月初九重阳节。这天古人要登高、赏菊、饮菊花酒。可在这个本该团圆欢聚的节日里，王之涣却要在蓟庭（蓟地的庭院，唐代边地蓟门一带）送别一位老朋友。\n「蓟庭萧瑟故人稀，何处登高且送归。」边地的庭院秋风萧瑟，老朋友本来就越来越少，如今又要送走一个。重阳节本来要登高，可举目望去，竟没有一处适合登高饯别的地方——故人稀、无处登高，两重凄凉叠在一起，让这个重阳格外冷清。\n「今日暂同芳菊酒，明朝应作断蓬飞。」今天的我们，还能暂且坐在一起，共同饮一杯芬芳的菊花酒；可到了明天，我们就要像断了根的蓬草一样，随风飞散，各自飘零，天各一方。「断蓬」是很有画面感的意象：蓬草枯后根断，被风一吹就卷着滚远，古人常用它来比喻漂泊无定、身不由己的游子。\n更辛酸的是地点：蓟庭是边塞之地，朋友此去不知是归乡还是远行，诗人自己也是羁旅之人。重阳的酒越香，明天的离别就越苦。以「今日」之乐反衬「明朝」之苦，短短四句，把节日、边塞、友情、漂泊四味糅在一起，苍凉沉郁，余味悠长。"},
  "回乡偶书·其二":{story:"这是《回乡偶书》的第二首。唐玄宗天宝三载（744年），贺知章已经八十六岁了，他辞去朝廷官职，告老还乡。回到家乡绍兴后，他接连写下了这组名诗，这是第二首。\n「离别家乡岁月多，近来人事半消磨。」他离开家乡去做官，一晃就是五十多年。如今白发苍苍地回来，才发现家乡的人和事，一半都已经不在了——老朋友有的已经去世，有的音信全无；当年的孩童如今也成了白发老人。一个「半」字，写尽沧桑。\n可是，当他走到自家门前，却看到了令人欣慰的一幕：「惟有门前镜湖水，春风不改旧时波。」只有家门前那一湖镜湖的水，还是老样子啊！春风一起，湖面荡起的波纹，和他五十年前离开家时一模一样。镜湖就是鉴湖，在绍兴城西南，贺知章的家乡就在湖边，这里是他童年游泳垂钓的地方。\n这首诗最动人之处在于「变」与「不变」的对照：人事半消磨，是「变」；镜湖水波依旧，是「不变」。诗人没有说一个「悲」字，也没有说一个「喜」字，只是平静地陈述「湖没变、人变了」这个事实，可这份物是人非的感慨，却比任何嚎啕大哭都更震撼人心。\n八十六岁的老人，用一生告别的经验，为后人留下了一个永恒的乡愁形象。后世每有游子归乡，看到故乡的山水依旧而故人已非，都会想起这两句诗。"},
  "答朝士":{story:"贺知章是越州永兴（今杭州萧山）人，在长安做了五十多年官，是唐玄宗时期德高望重的老臣。这首诗是他在长安与同僚「朝士」们之间的玩笑之作，充满了诙谐的家乡自豪感。\n「鈒镂银盘盛蛤蜊」，鈒镂是一种金银雕刻工艺。是说在京城官员的餐桌上，用雕花的银盘盛着一道美味——蛤蜊（一种海产贝类）。这是吴地越地的特产，味道鲜美。\n「镜湖莼菜乱如丝」，镜湖在贺知章的家乡绍兴，湖里出产一种莼菜，嫩芽上有晶莹的黏液，做成莼菜羹滑嫩可口，是江南名菜。银盘里的莼菜细如乱丝，晶莹剔透。\n接下来是最有趣的两句：「乡曲近来佳此味，遮渠不道是吴儿。」乡曲，指京城本地人；遮渠，即「管他、随他」。贺知章开玩笑地对同僚们说：近来你们京城人也最爱吃这蛤蜊、莼菜羹，味道好得不得了——既然你们这么爱吃我们家乡的菜，以后可别再叫我「吴儿」（吴地人）啦！你们吃的不也是吴地风味吗？\n这首诗通篇自嘲自辩，幽默风趣。一个八旬老人，在严肃的朝堂之外，用家乡美食和同僚开着玩笑，把「乡恋」写得那么俏皮可爱。它让我们看到了贺知章「旷达不羁」的另一面，也遥相呼应了五十多年前张翰「莼鲈之思」的典故——那一位西晋名士也是因为想念家乡的莼菜羹、鲈鱼脍而辞官归乡的。江南的味道，总是游子心里最深的牵挂。"},
"长信怨":{story:"汉朝时有一位班婕妤，她才华出众、品德贤良，深受汉成帝的敬重。后来她渐渐失宠，因为赵飞燕、赵合德姐妹进了宫，把皇帝的心全占了。班婕妤不争不抢，主动请求到长信宫去侍奉太后，过着清冷寂寞的日子。\n相传她曾写过一首《怨歌行》，把自己比作一把团扇：夏天被人拿在手里爱不释手，秋天一到就被丢进箱子里，再也无人想起。王昌龄正是借这个典故写下此诗：天刚亮，宫门打开，她捧着扫帚在殿前打扫，只能拿起那把团扇，在殿里独自徘徊。\n最伤心的句子是「玉颜不及寒鸦色，犹带昭阳日影来」。她说：我这美丽的容颜，竟还不如一只乌鸦——乌鸦飞过天空，身上还带着昭阳殿（赵飞燕姐妹居住的宫殿）的阳光，而我连见一眼阳光的机会都没有了。用人和乌鸦相比，越比越心酸，这种对比的写法千百年来打动着无数读者。"},
  "采莲曲":{story:"王昌龄一生写了不少边塞诗，可他也擅长写江南的明丽风光。相传这首《采莲曲》是他乘船经过江南水乡时，看见少女们采莲的情景，随手写下的妙作。\n诗中写道：采莲少女的绿罗裙，仿佛和荷叶用同一块绿色的料子裁出来的；她们红润的脸颊，夹在盛开的荷花中间，人和花互相映衬，分不清哪朵是花，哪张是脸。少女们钻进荷叶深处采莲，身影完全被荷叶荷花遮住，看不见人了；忽然听到一阵清脆的歌声传来，人们这才发觉——原来池子里有人呀！\n这首诗最妙的地方就是「乱入池中看不见，闻歌始觉有人来」，先让你看不见人，再用歌声把人「找」出来，画面像捉迷藏一样活泼有趣。全诗没有一句正面描写少女的模样，只写裙、荷、脸、歌，却让人仿佛亲眼看见了那片碧绿的荷塘。"},
  "塞下曲":{story:"王昌龄年轻的时候曾经投笔从戎，到过西北边塞。这首《塞下曲》就是他随军在边地生活时写下的，时间约在开元年间。\n诗的开头写他亲身经历的一幕：牵着马渡过秋水去饮马，河水冰冷刺骨，吹来的风像刀子一样刮在脸上。太阳还没落山，广阔的沙漠上一片昏暗，远远能看见边城临洮的轮廓。那景象又冷又荒凉，让人心里发紧。\n后四句笔锋一转，想到古往今来在这里打过的仗：人们都说当年长城下的战士意气高昂，可你看那漫天的黄尘从古至今没有散过，荒野里散乱的白骨淹没在蓬蒿之中。前两句是眼前的景，后四句是历史的眼泪，王昌龄没有直接喊「战争好残酷」，只是把黄沙和白骨摆在你面前，让读者自己震撼。这种写法的边塞诗，被称为「反战」的名篇。"},
  "送柴侍御":{story:"王昌龄一生做过不少小官，也结交了许多朋友。有一次，他的好友柴侍御（侍御是官名）要调往武冈，也就是今天的湖南武冈。送别的时候，王昌龄写下了这首别具一格的送别诗。\n一般送人离开，诗人总会哭哭啼啼、难舍难分，王昌龄却说：「送君不觉有离伤。」为什么？因为沅江的水波一路相通，连到了武冈；我们头顶的青山连成一片，共同承受着云雨；我们看见的，是同一轮明月啊！既然山水相连、明月共照，哪里算是两个地方呢？\n「青山一道同云雨，明月何曾是两乡」是流传千古的名句。后来很多人离开家乡、离开朋友时，都会用这两句来互相安慰。它告诉我们：真正的友情不会被距离隔断，只要心在一起，看的是同一轮月亮，就永远没有分别。"},
  "西宫春怨":{story:"唐朝皇宫里，除了皇后和得宠的妃子，还有许多进了宫却见不到皇帝的女子，她们被安置在西宫等冷清的宫院里，人们把她们的幽怨称为「宫怨」。王昌龄没有明说写的是哪一位妃子，而是借一个春夜，替千万个失宠的女子说出了心事。\n诗中的情景是这样的：西宫春夜，静得能听见落花的声音。夜里的花香一阵阵飘进屋子里来，逗得人心更乱。失宠的妃子卷起珠帘想看一看外面，看了看，又失望地放下。百无聊赖之中，她斜抱着云和琴，久久地望着月亮，只见远处朦胧的树影，把昭阳殿（得宠妃子居住的地方）遮得严严实实——那里灯火温暖，这里只有月色寒凉。\n全诗没有一句直接说「怨」字，可卷了又放的珠帘、望不见的昭阳殿，处处都是怨。「斜抱云和深见月，朦胧树色隐昭阳」两句，把寂寞写进了月色和树影里，正是王昌龄最擅长的含蓄笔法。"},
  "春宫曲":{story:"这首诗借汉朝的一件宫闱旧事，来写唐朝皇宫里失宠女子的心事。故事要从平阳公主说起：汉武帝年轻时，到姐姐平阳公主家做客，公主家的歌女卫子夫出来唱歌，汉武帝一眼就看中了她，把她带进了宫。卫子夫后来做了皇后，她的家人也跟着显贵，有名的武将卫青、霍去病都是她娘家的人。\n王昌龄抓住承宠那一夜来写：昨夜春风吹过，露井边的桃花悄悄开了；未央宫前殿上，一轮明月升得又高又亮。平阳公主家的歌女刚刚得到皇帝的宠爱，夜已经很深了，帘外还带着春寒，皇帝却特意派人赐给她锦袍御寒。\n全诗写的都是新人的得意，没有一句写失宠者，可字字都在反衬那些独守空房的旧人。在明月高照的夜晚，有人得到锦袍，有人只能对着冷墙。这种「只写一边、让人自己想另一边」的写法，就是诗家所说的「背面傅粉」，意味格外深长。"},
  "燕歌行":{story:"开元二十六年（738年），一件边关的丑闻传遍了朝野：幽州节度使张守珪的部将在跟契丹的作战中大败，损失惨重，可他的幕僚却贿赂使者，向朝廷谎报胜利。当时高适正怀着建功立业的壮志游历边塞，得知真相后非常愤慨，写下这首千古名作，诗前的小序里明确说了写作缘由。\n诗中最刺痛人心的是「战士军前半死生，美人帐下犹歌舞」：城墙前，战士们浴血奋战，生死各半；而将军的帐篷里，美人还在轻歌曼舞，寻欢作乐。当官的享乐，当兵的卖命，一句话就把不公平写尽了。可即便如此，战士们仍然「相看白刃血纷纷，死节从来岂顾勋」——他们互相看着刀口上的鲜血，依然奋勇杀敌，因为他们报效国家，从来不是为了个人邀功。\n诗的结尾高适感叹：「君不见沙场征战苦，至今犹忆李将军。」李将军是汉代的飞将军李广，他爱兵如子，与士兵同甘共苦。高适借古讽今，多么盼望唐朝也能出现这样一位将军啊！这首诗把边塞战争的真相和士兵的心声写得淋漓尽致，被称为盛唐边塞诗的第一杰作。"},
  "塞上听吹笛":{story:"高适长期在西北边塞生活，带兵、巡查、守边，是他日常的工作。一个雪后初晴的夜晚，牧马的人赶着马群归来，明月升上天空，皎洁的月光洒在戍边的城楼上。就在这时，一阵羌笛声悠悠地响了起来。\n高适侧耳细听，吹的正是《梅花落》这首古老的曲子。笛声婉转，随着夜风飘向远方。诗人听得入了神，恍惚间觉得：这哪里是笛声？分明是梅花的花瓣纷纷扬扬，被风吹了一夜，落满了整个关山！\n「借问梅花何处落，风吹一夜满关山」是这首诗最有名的两句。现实中，边塞雪原上一朵花也没有；可在笛声里，诗人「看」到了漫山遍野的梅花。把听到的笛曲和想到的景色交融在一起，虚虚实实，清丽动人，让荒寒的边塞一夜充满了诗意。这种写法，后世称为「通感」，非常考验诗人的想象力。"},
  "除夜作":{story:"除夕夜，千家万户都围在一起吃团圆饭，高适却独自住在异乡的旅馆里。这天夜里，他点着一盏昏黄的灯，怎么也睡不着——这大概是他客游在外时写下的诗，一说作于天宝年间任职途中。\n诗的开头很直白：旅馆的灯透着寒意，我独自躺在床上无法入眠，客居的心为什么忽然变得这样凄凉？接着，诗人说了一句特别巧妙的话：今夜，故乡的亲人们一定也在思念着千里之外的我吧。明明是自己想家，偏要说家人在想自己，这一「反过来写」，思念的味道反而更浓了。\n最后一句「霜鬓明朝又一年」更添伤感：明天一早，鬓角的白发又要多添几根，我又老了一岁。除夕是一年的终点，最容易让人感慨时光流逝。千百年来，无数在异乡过年的人读到这首诗，都会想起旅馆里那盏孤独的灯。"},
  "送李少府贬峡中王少府贬长沙":{story:"高适这首诗的题目很长，因为它要讲的事不寻常：一次宴席上，他要同时送别两位被贬官的朋友——一位李姓的少府（县尉的别称）被贬到峡中（今重庆一带），一位王姓的少府被贬到长沙（今湖南长沙）。两位朋友同时离开，一个往西一个往南，高适心里非常难过。\n饯行的时候，他停下马，举杯问两位友人：这一去，你们心情如何？然后他把两地的风景分别送给两位朋友作安慰：送给李少府的是巫峡的猿啼、白帝城边的古木；送给王少府的是衡阳的归雁、青枫江上的秋景。虽是贬所，可这些地方的山水也是天下有名的啊！\n结尾「长沙谪去古今怜」语气一转：被贬到长沙，自古以来就令人怜惜——当年汉朝的贾谊就是被贬到长沙的名臣。高适用这句诗告诉朋友：你们的遭遇并不孤单，古往今来多少有志之士都走过这条路。一首诗同时送两人，分得清、合得拢，情意绵密，是高适送别诗中的奇作。"},
  "营州歌":{story:"营州在今天辽宁朝阳一带，唐朝时是东北边地，汉人和契丹、奚等民族杂居在一起，风气粗犷豪迈。高适漫游边塞时到过这一带，对那里少年们的豪爽劲儿印象深刻，便写下了这首明快的小诗。\n诗里是这样写的：营州的少年们不喜欢关在家里，最爱在辽阔的原野上驰骋；他们穿着毛茸茸的狐皮袍子，在城墙下打猎，威风凛凛。当地的奶酒（虏酒）度数很低，他们喝上一千杯也醉不倒；这里的孩子十岁就会骑马，个个身手矫健。\n短短四句，没有任何修饰，却像一幅生动的边疆风俗画：猎装、美酒、骏马、少年，扑面而来的是蓬勃的生命力。高适用欣赏的眼光写出了边疆儿郎的尚武精神，也让今天的小朋友知道，古代的边塞不只有战争，还有这样鲜活、豪爽的生活。"},
  "和王七玉门关听吹笛":{story:"这首诗是高适的和诗——「和」就是照着朋友的诗题与韵脚唱和一首。这位「王七」一般认为就是王昌龄（他在兄弟中排行第七），他写过玉门关听笛的名作，高适在玉门关听到笛声，便和了一首。\n诗中的情景是：一个寂静的夜晚，胡人在戍楼的羌笛吹响了，曲调悠扬；月光如水，照着萧条的边楼，四周一片安闲。高适听出吹的也是《梅花落》的曲子，便问：这一夜，随着风声，究竟有多少梅花的花瓣落满了关山？\n玉门关是通往西域的门户，孤城、明月、羌笛，是边塞诗里最经典的三个意象。高适和王昌龄两位边塞诗人，一个在关前听笛，一个和诗回应，像隔着大漠的一场对话。后来「落梅满关山」的笛声，也成为唐诗里最能代表边塞夜色的画面之一。"},
  "送李侍御赴安西":{story:"安西都护府在遥远的西域，大约是今天新疆一带，从长安出发要走上几千里。朋友李侍御奉命去安西任职，高适在送别宴上写下这首诗，送友人踏上万里征途。\n开头两句非常有气势：远行的你就像被风吹起的蓬草，挥动金鞭，跨上名贵的铁骢马，直指遥远的边疆。接着高适替朋友道出心声：到万里之外去建功立业，是我们男儿的志向；而分别的种种心绪，都在这一杯酒里了。「功名万里外，心事一杯中」，一句写志向，一句写别情，豪迈和深情各占一半，恰到好处。\n诗中还写到朋友此去的路线：要经过燕支山以北的虏障，远隔着秦城长安与太白山以东的家乡。路途那么远，可全诗没有一丝愁苦，反而志气昂扬。后来「功名只向马上取，真是英雄一丈夫」（高适另一名句）可与此诗互相印证，这正是盛唐男儿向往建功立业的时代气象。"},
  "醉后赠张九旭":{story:"张旭是唐代著名的书法家，因为排行第九，人们称他为「张九旭」。他最厉害的本领是写狂草——喝醉以后，挥毫落笔，字迹如龙飞凤舞，人们送给他一个外号叫「草圣」，又称「张颠」。高适与他交往，十分钦佩他，在一次酒醉之后写下了这首诗。\n诗里说：这世上交朋友大多是随随便便、泛泛而交，只有这位老翁与众不同。兴致来了，提笔写字，笔下自然有了圣人的境界；喝醉之后说话，更是天真烂漫、毫无遮掩。别人醉后胡言遭人笑话，张旭的「颠」，却是艺术的真性情。\n后半首高适又替张旭惋惜：他一头白发，悠闲度日，不问世事；可他的才华明明就在眼前的青云之上，本该一飞冲天。这两句既赞美了张旭淡泊的品格，又叹惜他怀才不遇。张旭的草书后来被李白、杜甫等诗人都写诗称赞，成为中国书法史上的一面旗帜。"},
  "人日寄杜二拾遗":{story:"人日是农历正月初七，古人认为这一天是人的生日。公元761年（一说此年前后），高适正在蜀州（今四川崇州）做刺史，而他的老朋友杜甫——杜二，当时正流落成都，住在破旧的草堂里，生活困顿。\n正月初七这天，高适写下这首诗，寄给千里之外的杜甫。他说：人日这天我题了诗寄往你的草堂，远远怜惜你这老朋友也在思念故乡。你看那柳条抽出了新绿，我却不敢去看；梅花开满了枝头，也只会让人空自断肠——为什么？因为大好春光里，你却孤身一人漂泊在外啊！\n高适和杜甫是年轻时的旧交，几十年过去，一个做官一方，一个寄人篱下，身份虽不同，友情却没有变。「身在南蕃无所预，心怀百忧复千虑」，高适牵挂着老友的冷暖安危。据说几年后杜甫读到这首诗的遗稿时，感动得流下了眼泪。真正的朋友，就是隔得再远、隔得再久，心里也始终装着对方。"},
  "走马川行奉送出师西征":{story:"公元754年（天宝十三载），岑参正在安西北庭节度使封常清手下做判官。这年冬天，封常清出师西征，讨伐来犯的敌人，岑参随军出征前写下这首诗为将士送行，诗题里的「走马川」是西域的一条河川，一说即今新疆的车尔臣河。\n岑参先写西域的风有多可怕：九月的轮台，夜里狂风怒吼，满河的碎石大得像斗一样，被风吹得满地乱滚，黄沙一直扬到天上。这样的环境，人怎么待得下去？可紧接着，他笔锋一转写唐军的将士：将军的铠甲夜里都不敢脱，半夜行军，兵器相互碰撞，寒风像刀子一样刮着脸——没有一个人叫苦。\n诗的最后，岑参预祝凯旋：马毛带雪汗气蒸，五花连钱旋作冰，幕中草檄砚水凝——条件再苦，将士们的斗志比天气更硬。全诗句句押韵、节奏急促，像战鼓一样咚咚作响，把边塞的险恶和将士的英勇写得惊心动魄，是岑参边塞诗的代表作。"},
  "碛中作":{story:"公元755年，岑参离开长安的家，前往北庭都护府（在今新疆吉木萨尔一带）任职。西行的路要穿过大沙漠，「碛」就是沙漠的意思。行进在茫茫沙海之中，他写下了这首七言绝句。\n诗只有四句，却把塞外行军的滋味写尽了：我骑着马一路向西，仿佛要走到天边；自从离开家，已经看见月亮圆过两次了——也就是说，已经在路上走了两个多月。今夜走啊走，不知道还能不能找到宿营的地方，放眼望去，万里平沙，看不见一缕炊烟、一个人影。\n开头「走马西来欲到天」气势豪迈，仿佛天地都任他驰骋；可后两句笔锋一转，「今夜不知何处宿」又透出浓浓的乡愁和旅途的孤独。豪壮与柔情交织在一起，正是岑参边塞诗最动人的地方。也正是在这样的跋涉中，他把西域的雪山、热海、轮台都写进了诗里，为后人留下了一幅幅奇丽的边塞画卷。"},
  "山房春事":{story:"梁园是西汉梁孝王刘武营建的一座巨大园林，也叫兔园，故址在今河南商丘。当年这里亭台楼阁、奇花异石，天下的文人雅士如司马相如、枚乘都曾聚集于此，盛极一时。几百年后，唐朝的岑参来到这里，园子早已荒废，他触景生情，写下了这首诗。\n诗中的画面是：傍晚时分，梁园上空乌鸦乱飞，放眼望去一片萧条，只有三两户人家。园子里的树木不知道主人早已不在人世，春天一到，依然开出和当年一样的花。\n「庭树不知人去尽，春来还发旧时花」是全诗的名句。树没有感情，所以花开照旧；人有感情，所以见花伤心。用无知的花树反衬多情的吊古之人，一乐一哀，对比强烈，「物是人非」四个字不用说出口，读者自己已经体会到了。这种借无情之物写有情之人的手法，后来成为怀古诗的经典写法。"},
  "春梦":{story:"岑参的这首小诗，写的是对远方友人的思念。友人远在湘江那边，隔着千山万水，平日难得相见。那天夜里，春风吹起，诗人睡下了。\n梦，是人心里想说又说不出的话。后半夜，他梦见自己踏上了江南的土地，千里山河仿佛一瞬间就跨了过去，与思念已久的故人相见欢聚。醒来才知道是一场梦，枕头上仿佛还留着梦里的温度。\n「枕上片时春梦中，行尽江南数千里」是这首诗最奇妙的句子：梦只有枕上片时那么短，梦里却已经走完了江南几千里的路。现实中走不到的路，梦替你走；现实中见不到的人，梦替你去见。岑参用短短的二十八个字，把相思写得又快又远又深情。后世很多人形容梦境的神奇，都会想起这两句诗。"},
  "寄左省杜拾遗":{story:"公元753年，岑参在朝廷里做右补阙，他的好朋友杜甫做左拾遗。补阙和拾遗都是谏官，专门负责给皇帝提意见；唐朝皇宫中，门下省在左边，中书省在右边，所以杜甫属左省，岑参属右省，两人同朝为官，情谊很深。\n这首诗就是岑参寄给杜甫的。前四句写同朝上班的情形：每天一早，我们并排快步走上红色的台阶，分别到左右两省办公；清晨跟着皇帝的仪仗进殿，傍晚回家时衣服上还带着御香的香气。这几句写得工整漂亮，记录了两人在朝堂上并肩共事的日子。\n结尾两句意味深长：「圣朝无阙事，自觉谏书稀。」意思是：如今的圣明朝廷好像没有什么缺漏需要指出来，我自己觉得劝谏的奏书都变少了。表面上是夸朝廷，实际上暗含讽刺——是国家真的完美无缺，还是谏官的话根本没人听呢？好友之间用这种方式互相唱和，既亲密又有锋芒，是唐人交游诗中很有味道的一首。"},
  "和贾舍人早朝大明宫之作":{story:"公元761年（一说760年前后），唐肃宗朝的中书舍人贾至写了一首《早朝大明宫呈两省僚友》，描写早朝的盛况，分送同僚唱和。王维、杜甫都写了和诗，岑参的这一首最为响亮。\n岑参笔下的大明宫早朝是这样一幅景象：清晨，鸡声报晓，长安的大道上曙光带着寒意；黄莺啼鸣，京城的春色将尽。金殿上的晓钟一响，千万扇宫门次第打开；白玉台阶前，皇帝的仪仗如云，簇拥着百官上朝。\n结尾「独有凤凰池上客，阳春一曲和皆难」是高明的手笔：凤凰池是中书省的别称，贾至正在那里做官。岑参说，贾至的原诗像高雅的《阳春白雪》一样美妙，我们大家想要唱和，都觉得难以企及。既赞了诗，又捧了人，还点明了同僚的情谊。全诗辞藻华丽、气象庄严，是中唐唱和诗中的名作。"},
  "轮台歌奉送封大夫出师西征":{story:"公元754年（一说753年），岑参在西北边疆做判官，跟随封常清（封大夫）驻守轮台。边关传来紧急军情，封常清率军西征，岑参写下这首诗为大军壮行。\n诗一开头就气氛紧张：轮台城头夜里吹起了号角，城北的旄头星坠落——古人认为旄头星主胡兵，星落预示着敌军将败。昨夜加急的军书刚刚送过渠黎，敌军已经到了金山西面，边关危急！\n接着写大军出征的声势：清晨的号角吹响，将士们浩浩荡荡开拔；四面的战鼓擂起来，声浪仿佛让雪海翻腾；三军将士齐声呐喊，连阴山都为之震动。「四边伐鼓雪海涌，三军大呼阴山动」，短短两句，把千军万马的声威写得地动山摇，是写军队声势的名句。诗的最后，岑参赞颂封常清不辞辛苦、誓死报国的决心。全诗紧张、雄壮、豪迈，读起来像站在西北的高冈上，亲眼看见了大军出塞的场面。"},
  "热海行送崔侍御还京":{story:"热海就是今天吉尔吉斯斯坦境内的伊塞克湖，古称热海、大清池，地处西域，据说湖水冬天不结冰，还带着温热，是一个神奇的所在。崔侍御在边疆任职期满，要从热海一带回长安，岑参写这首诗为他送行。\n诗的开头非常新奇：我从阴山胡人那里听说，西边的热海水热得像烧开了一样。海上热得连鸟都不敢飞过，可湖水里的鲤鱼却长得又长又肥。热气腾腾的水面，配上「势吞月窟侵太白，气连赤坂通单于」的夸张描写，热海的声势仿佛要吞没月亮、连接天山，让读者对这片遥远的湖泊充满了想象。\n最妙的是诗的转折：热海这么热，可崔侍御是御史台的官员，御史台又称柏台，以执法严明著称，所谓「霜威」。岑参说：崔大人身为柏台御史，他身上的清霜之威寒光逼人，连热海这样的酷热之地也要让他三分。用热海之「热」反衬御史之「寒」，比喻新奇贴切，送行诗能写得这么有想象力，正是岑参的本事。"},
"登柳州城楼寄漳汀封连四州刺史":{story:"唐宪宗元和十年（815年），柳宗元被贬永州十年后奉诏回京，却再次被贬为更远的柳州刺史。他登上柳州城楼极目四望，想起一同遭贬的友人——韩泰在漳州、韩晔在汀州、陈谏在封州、刘禹锡在连州，五人都被抛撒在天涯海角的角落。\n他写下「城上高楼接大荒，海天愁思正茫茫」，城楼外是一望无际的荒凉，愁思像海一样茫茫无边。「惊风乱飐芙蓉水，密雨斜侵薜荔墙」，狂风掀翻水中的荷花，密雨斜打着墙上的薜荔——这风雨不正像朝廷里一次次打击他们的政治风浪吗？\n最伤感的是「共来百越文身地，犹自音书滞一乡」。大家一同被贬到这纹身的蛮荒之地，本已够苦，偏偏还分散五处，连一封信都难以寄达。此诗写景苍茫、抒情深沉，是柳宗元七律的名篇。"},
  "与浩初上人同看山寄京华亲故":{story:"元和十年（815年）后，柳宗元贬居柳州。一天，他与僧人浩初上人一同登高望远，眼前柳州海边一座座尖峭的山峰连绵起伏，直指天空。\n他说「海畔尖山似剑铓，秋来处处割愁肠」——海边的尖山像宝剑的锋芒，秋天里处处都是，仿佛要把人的愁肠一根根割断。这个比喻多么奇特，多么痛！\n「若为化得身千亿，散上峰头望故乡」，他恨不得化作千万亿个身子，散立在每一座山峰顶上，一起眺望万里之外的长安和故乡。这个奇妙的想象化用了佛经中「化身千亿」的说法。全诗短短二十八个字，把贬谪思乡的悲苦写得惊心动魄。"},
  "别舍弟宗一":{story:"约元和十三年（818年），柳宗元的堂弟柳宗一将离开柳州，取道赴江陵（今湖北江陵）。送别时，兄弟二人在越江边双双落泪，难分难舍。\n「零落残魂倍黯然，双垂别泪越江边」，他本已是零落残魂，再加上与弟弟分别，更是黯然神伤。「一身去国六千里，万死投荒十二年」，他算了一笔让人心酸的账：离乡整整六千里，在荒蛮之地熬了十二年，历尽千辛万苦。\n「桂岭瘴来云似墨，洞庭春尽水如天」，弟弟此去要经过桂岭的瘴气、洞庭的烟水，云水相隔，今后音信恐怕更加渺茫。一首诗写尽贬谪者送别亲人的凄凉，字字是泪。"},
  "岭南江行":{story:"柳宗元贬居柳州期间，一次乘船沿瘴江而行，把沿途风物写进诗中。江水向南流去，隐入云烟；放眼望去，黄茅遍地，一直铺到海边，满目荒凉。\n「山腹雨晴添象迹，潭心日暖长蛟涎」，山腰间雨后留下大象的足迹，深潭在暖日里仿佛有蛟龙吐涎。瘴江、黄茅、象迹、蛟涎，字字写尽岭南的荒僻与险恶。\n但他没有消沉：「从此忧来非一事，岂容华发待流年」——今后值得忧心的事何止一件，怎能让白发空度岁月！在险恶的环境里，他仍提醒自己振作有为。全诗于写景中见风骨，是贬谪诗中的硬语。"},
  "溪居":{story:"柳宗元谪居永州时，住在冉溪边，把溪改名为「愚溪」，还写下了《永州八记》。这首《溪居》说：「久为簪组累，幸此南夷谪」——长久以来被官场所累，幸亏被贬到这南方来。\n「闲依农圃邻，偶似山林客。晓耕翻露草，夜榜响溪石」，白天与种田人为邻，清晨踏着露水耕种，夜里划船触响溪石，日子似乎闲散又自在。\n可细心的读者会发现，这个「幸」字其实是反话。诗人嘴上说得清闲，心里却积着深深的愤懑——有谁真的愿意以被贬为「幸」呢？全诗含蓄委婉，闲适的字句背后藏着不平的鸣响，这正是柳宗元诗的深沉之处。"},
  "晨诣超师院读禅经":{story:"贬居永州时，柳宗元常到超师（一位法号超的僧人）的寺院中去。一天清晨，他早早起身，「汲井漱寒齿，清心拂尘服」，打来井水漱口，拂去衣上的尘土，让心也清净下来。\n「闲持贝叶书，步出东斋读」，他手里拿着贝叶书，走到东斋外静静诵读。贝叶书就是佛经——古时候印度人把经文写在贝多罗树的叶子上，所以佛经又有个美丽的名字叫贝叶经。\n读着读着，他渐入「澹然离言说，悟悦心自足」的境界——言语说不尽的淡泊之乐涌上心头，内心充实而愉悦。在贬谪的苦闷里，佛法给了他片刻安宁。全诗清丽淡远，让人仿佛能听见清晨诵经的轻声。"},
  "酬曹侍御过象县见寄":{story:"柳宗元任柳州刺史时，一位姓曹的侍御（官名，姓名已不可考）经过象县（今广西象州），写诗寄给他。柳宗元读后，作这首小诗相答。\n「破额山前碧玉流，骚人遥驻木兰舟」，他想象友人乘坐着芳香的木兰舟，停泊在碧玉般的江水前。这里柳宗元自称「骚人」，因为他像屈原一样被贬江南，心中满是与屈原相通的忧愤。\n「春风无限潇湘意，欲采蘋花不自由」，春风里满是潇湘的情意，他多想采一枝蘋花寄给远方友人，却身不由己。古人采蘋花赠给远方的人寄托情谊，他想赠而不能赠，正因为被牢牢困在贬所之中。短短二十八字，温柔深情又暗含悲愤。"},
  "柳州二月榕叶落尽偶题":{story:"元和年间，柳宗元在柳州任上。当地气候与中原大不相同，农历二月里下了一场大雨，山城中的百花被风雨打落殆尽，大榕树的叶子也飘落了满院。\n「山城过雨百花尽，榕叶满庭莺乱啼」，春天本应是百花盛开的时节，这里却百花落尽，莺鸟在满庭落叶中乱啼，景象竟像深秋一般。\n他触景伤情：「宦情羁思共凄凄，春半如秋意转迷」，做官的失意与客居的愁思一齐涌上心头，春天过了一半，却凄凉得像秋天，让人心绪迷惘。一场异乡的风雨，写出贬谪者心中化不开的春愁，语短而情深。"},
  "题榴花":{story:"五月盛夏，韩愈看见庭院里的石榴花开得明艳如火，红得耀眼，枝间还结出了小小的果实。他欣然提笔：「五月榴花照眼明，枝间时见子初成。」\n可是笔锋一转：「可怜此地无车马，颠倒青苔落绛英」，可惜这里地处偏僻，没有车马游人，红艳艳的花瓣飘落下来，乱乱地铺在青苔上，无人欣赏。\n有人说，这是韩愈借榴花自况——花开得再艳，果实结得再好，长在无人问津的地方，也只好自开自落；也有人说他在惋惜人才的埋没，多少有才华的人就像这落在青苔上的榴花，无人赏识。短短四句，由明丽转入惋惜，意味深长。"},
  "湘中":{story:"元和十四年（819年），韩愈因上《谏佛骨表》触怒唐宪宗，被贬潮州刺史，踏上了艰险的南方之路。途经湘水时，他想起这里相传就是屈原自沉的汨罗江。\n「猿愁鱼踊水翻波，自古流传是汨罗」，两岸猿声哀愁，鱼儿跃出水面，江波翻腾——他仿佛看见当年忧愤投江的屈原身影。\n「蘋藻满盘无处奠，空闻渔父扣舷歌」，他备好满盘的蘋藻想祭奠屈原，却不知道该在江上哪一处献祭，只听见渔父敲着船舷歌唱。当年贾谊被贬长沙，曾写文章投进湘水凭吊屈原；如今的韩愈，也在凭吊屈原的同时，哀悼自己的命运，两代人的悲怆在江上重叠。"},
  "答张十一":{story:"元和元年（806年）前后，韩愈与张署同为监察御史，因直言朝政，一起被贬到广东阳山——韩愈任阳山令，张署任临武令。张署排行十一，人称张十一。春天里，韩愈写下此诗答赠患难中的友人。\n「山净江空水见沙，哀猿啼处两三家」，阳山一带山水清净，江边只见两三户人家，处处听见猿猴哀啼。「筼筜竞长纤纤笋，踯躅闲开艳艳花」，粗大的筼筜竹竞相抽出新笋，踯躅花静静开得鲜艳——荒僻的山城也有生机盎然的春景。\n但韩愈心中并不平静：「未报恩波知死所，莫令炎瘴送生涯」，他还没有报答君恩，不知将来会死在哪里，只盼不要让南方的瘴气白白断送一生。身在荒远，仍念念不忘报国，这正是韩愈的耿耿之心。"},
  "题木居士二首·其一":{story:"韩愈在南方时路过一处村落，看见道旁有一段古木，相传被雷打火烧过，树桩粗矮，根瘤像人头，树干像人身。村民们觉得神奇，给它披红挂彩，称为「木居士」，天天有人来磕头求福。\n韩愈觉得又好笑又可叹，提笔写道：「火透波穿不计春，根如头面干如身」，这截木头不知经历了多少年的火烧水冲，碰巧长得像人形；「偶然题作木居士，便有无穷求福人」，不过偶然被起了这个名号，就有数不清的人跑来求福。\n全诗寓庄于谐，表面上像在说笑，其实辛辣地讽刺了盲目崇拜、不问是非的陋俗——一块枯木尚且被顶礼膜拜，人间的愚昧不正如此吗？短短四句，幽默中藏着深刻的批评。"},
  "听颖师弹琴":{story:"颖师是一位善于弹琴的僧人，韩愈听他弹琴后写下这首千古名作。琴声一起，「昵昵儿女语，恩怨相尔汝」，像小儿女贴耳细语，恩恩怨怨，卿卿我我；忽然「划然变轩昂，勇士赴敌场」，琴声陡然高亢，像勇士奔赴战场。\n接着琴声又化作「浮云柳絮无根蒂，天地阔远随飞扬」，像浮云柳絮随风飘荡；忽而「喧啾百鸟群，忽见孤凤凰」，像百鸟喧闹之中，一只凤凰冲天而起。琴声千变万化，韩愈只用一连串生活里看得见的画面，就把看不见的声音写活了。\n「嗟余有两耳，未省听丝篁。自闻颖师弹，起坐在一旁。推手遽止之，湿衣泪滂滂」，他自嘲平日不懂音乐，这次却听得坐立不安，最后伸手止住琴声，才发现自己早已泪流满面、衣衫尽湿。写音乐的诗能写到这样真切动人，难怪后世苏轼、欧阳修都留下评说。"},
  "山石":{story:"相传贞元十七年（801年）前后，韩愈游洛阳惠林寺，写下这首著名的记游诗。开篇「山石荦确行径微，黄昏到寺蝙蝠飞」，山石嶙峋，小路狭窄，他到寺时已是黄昏，蝙蝠在殿前飞舞。\n雨后初晴：「升堂坐阶新雨足，芭蕉叶大栀子肥」，坐在台阶上，看芭蕉叶又大又绿，栀子花开得又白又肥。僧人称赞古壁上的佛画，打着火把去看，火光摇曳，画面幽暗难辨。接着铺床拂席，端来粗饭菜羹，虽是粗茶淡饭，也吃得心满意足。\n夜深静卧，百虫声绝，明月照进门来；清晨独自离开，在云雾缭绕的山间穿行，山花红得照眼，泉水激石作响，松子落在阶前。「人生如此自可乐，岂必局束为人鞿」，人生能这样自由自在，何必被人间的缰绳捆住！全诗以文为诗，风格奇崛，被后人推为韩愈诗的代表作。"},
"钱塘湖春行":{story:"长庆二年（822年），白居易出任杭州刺史。次年春天，他骑马沿西湖（唐代称钱塘湖）春游，从孤山寺北、贾公亭西一路行来，只见春水初涨、白云低垂。\n「几处早莺争暖树，谁家新燕啄春泥」——早出的黄莺争抢向阳的树枝，新来的燕子衔泥筑巢，莺歌燕舞，正是西湖早春最动人的光景。\n行至湖东，绿杨成荫的白沙堤（即今白堤一带）令他流连忘返，「最爱湖东行不足，绿杨阴里白沙堤」。全诗处处紧扣一个「早」字，把刚刚苏醒的西湖写得生机勃勃，是吟咏西湖的千古名篇。"},
  "夜雪":{story:"此诗约作于白居易贬居江州时期。寒冷的冬夜，诗人从睡梦中醒来，先是被子和枕头的冰凉让他惊讶，继而看见窗户透出一片光亮。\n夜深了，他分明感到雪下得很厚，不时还听到竹子被积雪压断的声响。\n全诗不着一个「雪」字，却从触觉（衾枕冷）、视觉（窗户明）、听觉（折竹声）三个角度，把一场纷纷扬扬的夜雪写得历历在目。这种侧面烘托的手法，正是白居易绝句的高明之处。"},
  "晚春":{story:"韩愈笔下的春天不肯悄然离去。花草树木仿佛知道春将归去，于是百般红紫、争芳斗艳，要在最后的春光里尽情绽放。\n「杨花榆荚无才思，惟解漫天作雪飞」——就连那没有艳丽姿色的杨花榆荚也不甘落后，化作漫天飞雪随风起舞。\n诗人用拟人的手法写草木「惜春」，表面诙谐，实则寄寓深意：春光易逝，即使是平凡如杨花榆荚，也要抓紧时光展现自己。后人常借此诗勉励人珍惜光阴、奋发有为。"},
  "浪淘沙":{story:"刘禹锡被贬朗州、连州期间，学习当地民歌风格，写下《浪淘沙九首》组诗，这是其中第一首。\n「九曲黄河万里沙，浪淘风簸自天涯」，弯弯曲曲的黄河裹挟万里黄沙，从天边奔腾而来。后两句他借用了一个美丽的传说：汉代张骞乘木筏（槎）溯黄河而上，竟来到了银河，见到了牛郎织女。\n「如今直上银河去，同到牵牛织女家」——诗人真想沿着黄河一直上到天上的银河去！想象大胆奇特，把民歌的朴素语言和浪漫幻想结合在一起，展现了刘禹锡豪宕不羁的胸襟。"},
  "石头城":{story:"唐敬宗宝历年间，刘禹锡途经六朝古都金陵（今南京），写下组诗《金陵五题》，这是第一首。石头城原是三国时孙权修筑的要塞，依山傍江，曾是何等雄壮。\n如今故国山围依旧，江潮拍打着空荡荡的城池，又寂寞地退回；只有当年从秦淮河东边升起的明月，夜深时还越过城墙（女墙，即城上的矮墙）照进空城。\n山、潮、月依旧，而六朝的繁华早已灰飞烟灭。诗人不着一字议论，只以「旧时月」见证兴亡，便写尽「物是人非」的无限苍凉，白居易读后曾叹服「后之诗人无复措词矣」。"},
  "蜀先主庙":{story:"刘禹锡任夔州刺史时，拜谒了长江白帝城附近的蜀先主庙——祭祀蜀汉昭烈帝刘备的祠庙，写下这首五律。\n「天下英雄气，千秋尚凛然」，开篇化用曹操煮酒论英雄的典故：当年曹操对刘备说「今天下英雄，唯使君与操耳」。千百年过去，庙中犹有凛然英雄之气。\n「势分三足鼎，业复五铢钱」概括刘备一生：三分天下成鼎足之势，建立蜀汉、恢复汉室（五铢钱为汉代通行货币，王莽篡汉时废止，光武帝中兴后恢复，此处喻指中兴汉室）。全诗气象雄浑，在历代咏刘备的诗中独占鳌头。"},
  "再游玄都观":{story:"元和十年（815年），刘禹锡结束十年贬谪回京，写下《元和十年自朗州至京戏赠看花诸君子》：「玄都观里桃千树，尽是刘郎去后栽」，借桃花讽刺朝中排挤他的新贵，结果再遭贬逐，一去又是十二年。\n大和二年（828年），他终于重返长安，再游玄都观，只见百亩庭院大半长满青苔，当年盛极一时的桃花一株不剩，只有野菜花开得正好。\n他提笔写下这首绝句：「种桃道士归何处，前度刘郎今又来！」——种下桃树的新贵们如今已不知去向，而我这个老刘郎又回来了！不向权贵低头的倔强与自豪跃然纸上，「前度刘郎」也从此成为一个著名典故。"},
  "赏牡丹":{story:"唐代长安城爱花成风，最盛者莫过于牡丹。每到暮春牡丹盛开，长安人倾城出游赏玩，车马塞途，万人空巷。刘禹锡以这首七绝咏之。\n「庭前芍药妖无格，池上芙蕖净少情。唯有牡丹真国色，花开时节动京城」——芍药虽艳却缺少风骨，荷花虽雅却不够多情，只有牡丹才称得上「真国色」，花开时节轰动整个京城。\n「国色天香」遂成为牡丹的代名词。这首诗没有一句直接写牡丹的形态，全用旁衬与品评之法，反而把牡丹「花中之王」的地位写得无可争议。"}
};
